    keywords = '가래|객담|sputum|기침|cough|가르랑|수포음|crackle|rale|천명|wheez|흡인|suction|폐렴|pneumonia|모세기관지염|bronchiolitis|RSV'
    cause = '기도 분비물 증가'
    long = '대상자는 퇴원 시 기도 분비물 없이 깨끗한 호흡음을 유지할 것이다.'
    short = @('대상자는 2일 내 청진 시 수포음이 감소할 것이다.','대상자는 3일 내 효과적으로 기침하여 객담을 배출할 것이다.')
    diag = @(
        @{plan='매 4시간마다 호흡음을 청진하고 호흡수, SpO2를 사정한다.';why='비정상 호흡음과 SpO2 저하는 기도 분비물 축적과 저산소증을 나타낸다.'},
        @{plan='객담의 양, 색, 점도를 사정한다.';why='객담의 양상은 감염 여부와 기도 청결 정도를 나타낸다.'})
    ther = @(
        @{plan='반좌위를 취하게 하고 2시간마다 체위를 변경한다.';why='횡격막이 내려가 폐 확장이 쉬워지고, 체위 변경은 분비물 이동을 돕는다.'},
        @{plan='금기가 아닐 시 수분 섭취를 격려한다.';why='분비물을 묽게 하여 배출을 쉽게 한다.'},
        @{plan='처방에 따라 네뷸라이저를 적용하고 흉부물리요법(타진, 진동)을 시행한다.';why='기관지를 확장하고 분비물을 느슨하게 하여 배출을 돕는다.'},
        @{plan='필요 시 무균적으로 흡인한다.';why='스스로 배출하지 못하는 분비물을 제거하여 기도 개방성을 유지한다. 흡인 전후 산소화 상태를 확인한다.'})
    edu = @(
        @{plan='효과적인 기침과 심호흡 방법을 교육한다.';why='스스로 분비물을 배출하고 무기폐를 예방할 수 있다.'},
        @{plan='보호자에게 등 두드리기(타진)와 수분 섭취 방법을 교육한다.';why='보호자가 참여하면 퇴원 후에도 분비물 배출을 도울 수 있다.'})
}
'구강점막 통합성 손상' = @{
    en = 'Impaired oral mucous membrane integrity'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체적 손상 Physical injury'
    page = 24
    problem = '구강점막 손상'
    priority = 3
    reason = '입안 통증으로 먹고 마시지 못하게 하여 탈수·영양 문제로 이어질 수 있는 실제적 문제이다'
    evalData = '구강 병변의 수·크기, 구강 통증 표현, 섭취량, 침 흘림 여부'
    keywords = '구내염|stomatitis|입안|입 안|구강|수포|궤양|ulcer|침을 ?흘|수족구|hand-foot-and-mouth|HFMD|헤르판지나|herpangina|아구창'
    cause = '바이러스 감염에 의한 구강 내 수포'
    long = '대상자는 퇴원 시 구강점막 병변이 호전되어 통증 없이 식사할 것이다.'
    short = @('대상자는 3일 내 구강 통증을 호소하지 않을 것이다.','대상자는 2일 내 하루 수분 섭취량이 목표량 이상 유지될 것이다.')
    diag = @(
        @{plan='매 듀티마다 구강점막 상태(수포, 궤양, 발적, 출혈)를 사정한다.';why='병변의 진행과 회복 정도를 객관적으로 평가할 수 있다.'},
        @{plan='섭취량과 구강 통증 정도를 사정한다.';why='구강 통증은 섭취 저하와 탈수의 주요 원인이다.'})
    ther = @(
        @{plan='식후와 취침 전 미온수나 생리식염수로 부드럽게 구강 간호를 제공한다.';why='구강을 청결히 하여 2차 감염을 예방하고 점막 회복을 돕는다.'},
        @{plan='차갑고 부드러운 음식과 음료를 제공하고 맵거나 짜고 신 음식을 피한다.';why='자극을 줄여 통증을 감소시키고 섭취량을 늘린다.'},
        @{plan='처방에 따라 진통·해열제를 식사 전에 투여한다.';why='식사 시 통증을 줄여 섭취를 도울 수 있다.'})
    edu = @(
        @{plan='보호자에게 구강 간호 방법과 자극적인 음식을 피해야 하는 이유를 교육한다.';why='보호자가 직접 구강 간호를 하여 회복을 도울 수 있다.'},
        @{plan='손 씻기와 식기 분리 등 전파 예방 방법을 교육한다.';why='바이러스성 구강 질환은 접촉으로 쉽게 전파된다.'})
}
'아동 낙상의 위험' = @{
    en = 'Risk for child falls'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체적 손상 Physical injury'
    page = 24
    problem = '낙상 위험'
    priority = 5
    reason = '아직 일어나지 않은 위험 진단이지만 아동은 발달 특성상 낙상 위험이 높아 안전 요구로서 예방이 필요하다'
    evalData = '아동 낙상 위험 평가 점수(Humpty Dumpty 등), 낙상 발생 여부, 보호자의 낙상 예방 수칙 이행 여부'
    keywords = '낙상|\bfalls?\b|침대에서|기어|걸음마|보채|진정|수면제|어지러'
    cause = '아동의 발달 특성과 낯선 병원 환경'
    long = '대상자는 퇴원 시까지 낙상 없이 지낼 것이다.'
    short = @('보호자는 1일 내 낙상 예방 수칙을 두 가지 이상 말로 표현할 것이다.','대상자는 입원 기간 동안 침상 난간을 올린 상태를 유지할 것이다.')
    diag = @(
        @{plan='입원 시와 매 듀티마다 아동 낙상 위험 평가도구(Humpty Dumpty 등)로 사정한다.';why='위험 정도를 객관적으로 파악하여 맞춤형 예방 중재를 할 수 있다.'},
        @{plan='낙상 위험 약물(진정제, 해열·진통제 투여 후 졸림) 투여 여부를 확인한다.';why='약물에 의한 졸림과 어지러움은 낙상 위험을 높인다.'})
    ther = @(
        @{plan='침상 난간을 항상 올리고 침대 높이를 낮게 유지한다.';why='아동이 침대에서 떨어지는 것을 막는다.'},
        @{plan='보호자가 자리를 비울 때 간호사에게 알리도록 한다.';why='아동을 혼자 두는 시간을 줄여 낙상을 예방한다.'},
        @{plan='미끄럼 방지 신발을 신기고 바닥을 건조하게 유지한다.';why='미끄러짐으로 인한 낙상을 예방한다.'})
    edu = @(
        @{plan='보호자에게 낙상 예방 수칙(침상 난간 올리기, 아동 혼자 두지 않기)을 교육한다.';why='아동의 안전은 보호자의 참여가 있어야 효과적으로 지킬 수 있다.'})
}
}

# >>> 추가 진단 (NursingHelper/data/extra.json에서 build_templates.py로 자동 생성 · 직접 고치지 마세요)
$script:Templates['비효과적 건강자가관리'] = @{
    en = 'Ineffective health self-management'
    domain = '1. 건강증진 Health promotion'
    cls = '2. 건강관리 Health management'
    page = $null
    problem = '건강자가관리 부족'
    priority = 7
    reason = '생명을 즉시 위협하는 문제는 아니지만 치료 요법을 지키지 못하면 질병이 악화되고 재입원으로 이어지므로 생리적 문제가 안정된 후 다룬다'
    evalData = '투약·식이·운동 이행 여부, 자가 측정 기록(혈압·혈당 등), 질병과 치료 요법에 대한 설명 정도, 증상 악화 시 대처 방법 표현 여부'
    keywords = '복약 ?(불이행|순응도)|약을? (안|못|잘 안) ?먹|약을? 자주 (잊|깜빡)|임의로? (중단|끊)|자가관리|식이 ?조절 (안|못)|외래 (안|미)방문|noncompliance|nonadherence|재입원|readmission'
    cause = '복잡한 치료 요법에 대한 지식 부족'
    long = '대상자는 퇴원 시 처방된 치료 요법을 일상생활에서 스스로 실천하는 방법을 말로 표현할 것이다.'
    short = @('대상자는 3일 내 복용 중인 약물의 이름, 용량, 복용 시간을 정확히 말할 것이다.','대상자는 1주일 내 증상 악화 시 병원에 연락해야 하는 징후를 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='대상자가 질병과 치료 요법(약물, 식이, 운동)을 얼마나 알고 있는지 사정한다.';why='현재 지식 수준을 파악해야 부족한 부분에 맞춘 교육 계획을 세울 수 있다.'},
        @{plan='치료 요법을 지키지 못하는 이유(비용, 부작용, 복잡한 복용 일정, 신념, 인지 저하)를 사정한다.';why='불이행의 원인에 따라 중재 방법이 달라지므로 원인을 먼저 확인해야 효과적으로 돕는다.'},
        @{plan='자가 측정 기록(혈압, 혈당, 체중)과 외래 방문 이력을 확인한다.';why='객관적 기록은 대상자의 실제 자가관리 수준과 질병 조절 정도를 보여준다.'})
    ther = @(
        @{plan='대상자와 함께 실천 가능한 구체적인 목표를 정한다.';why='대상자가 직접 참여해 정한 목표는 동기를 높이고 실천 가능성을 높인다.'},
        @{plan='복약 일정을 단순화하도록 의료진과 상의하고 약 달력, 요일별 약통, 휴대폰 알람 사용을 돕는다.';why='복용 횟수가 적고 기억 보조 도구가 있으면 복약 이행률이 높아진다.'},
        @{plan='대상자의 생활 습관과 일과에 맞추어 치료 요법을 조정한다.';why='일상생활에 자연스럽게 녹아든 요법은 오래 지속하기 쉽다.'},
        @{plan='작은 실천과 성공을 긍정적으로 강화한다.';why='긍정적 강화는 자기효능감을 높여 건강 행위를 지속하게 한다.'},
        @{plan='필요 시 보호자, 지역사회 보건소, 사회복지 자원과 연계한다.';why='경제적·사회적 지지 자원은 치료 요법을 꾸준히 지킬 수 있는 환경을 만든다.'})
    edu = @(
        @{plan='대상자에게 질병의 경과와 치료 요법을 지켜야 하는 이유를 쉬운 말과 자료로 교육하고 되묻기(teach-back)로 이해를 확인한다.';why='대상자가 자신의 말로 다시 설명하게 하면 이해 정도를 확인하고 잘못 이해한 부분을 바로잡을 수 있다.'},
        @{plan='대상자와 보호자에게 증상 악화 징후와 병원에 연락해야 할 상황을 교육한다.';why='이상 징후를 조기에 알아차리면 합병증과 응급 입원을 예방할 수 있다.'})
}
$script:Templates['비효과적 가족건강자가관리'] = @{
    en = 'Ineffective family health self-management'
    domain = '1. 건강증진 Health promotion'
    cls = '2. 건강관리 Health management'
    page = $null
    problem = '가족 건강관리 부족'
    priority = 7
    reason = '생리적 위기는 아니지만 가족이 치료 요법을 관리하지 못하면 대상자의 질병 조절이 어려워지므로 생리적 문제 해결 후 다룬다'
    evalData = '가족의 치료 요법 이해 정도, 투약·식이 관리 수행 여부, 가족 내 역할 분담, 돌봄 부담 표현, 이용 가능한 지지 자원'
    keywords = '보호자 ?(부재|없|바빠|힘들)|돌볼 사람 (이|)?없|돌봄 부담|간병 (부담|힘들)|가족이 (관리|챙기)지 못|보호자가 (약|식이)|caregiver (burden|strain)|family (management|coping)|독거'
    cause = '가족의 돌봄 부담'
    long = '대상자의 가족은 퇴원 시 대상자의 치료 요법을 가정에서 관리하는 방법을 말로 표현하고 시범 보일 것이다.'
    short = @('대상자의 가족은 3일 내 대상자의 투약 일정과 주의사항을 정확히 말할 것이다.','대상자의 가족은 1주일 내 가족 구성원 간 돌봄 역할 분담 계획을 세울 것이다.')
    diag = @(
        @{plan='가족이 대상자의 질병과 치료 요법을 얼마나 이해하고 있는지 사정한다.';why='가족의 지식 수준을 알아야 필요한 교육 내용을 정할 수 있다.'},
        @{plan='가족 구조, 주 돌봄 제공자, 역할 분담, 경제적 상황을 사정한다.';why='가족의 자원과 한계를 파악해야 실현 가능한 관리 계획을 세울 수 있다.'},
        @{plan='주 돌봄 제공자의 피로, 스트레스, 돌봄 부담 정도를 사정한다.';why='돌봄 제공자가 지치면 치료 요법 관리가 소홀해지므로 부담 정도를 확인해야 한다.'})
    ther = @(
        @{plan='가족과 함께 가정에서 실천할 수 있는 간단한 관리 계획(투약표, 식단, 일정표)을 만든다.';why='가족이 계획 수립에 참여하면 책임감과 실천 의지가 높아진다.'},
        @{plan='가족 구성원이 돌봄 역할을 나누도록 가족 면담을 돕는다.';why='역할을 분담하면 한 사람에게 부담이 집중되는 것을 막아 관리가 지속된다.'},
        @{plan='가족의 걱정과 감정을 표현할 기회를 제공하고 경청한다.';why='정서적 지지는 가족의 스트레스를 줄이고 문제 해결 능력을 높인다.'},
        @{plan='필요 시 지역사회 자원(보건소, 방문간호, 장기요양서비스, 사회복지사)과 연계한다.';why='외부 지지 자원은 가족의 돌봄 부담을 덜어 지속적인 건강관리를 가능하게 한다.'})
    edu = @(
        @{plan='가족에게 치료 요법(투약, 식이, 활동)과 관리 방법을 시범을 보이며 교육하고 직접 해 보게 한다.';why='직접 수행해 보면 기술을 익히고 가정에서 자신감 있게 관리할 수 있다.'},
        @{plan='가족에게 대상자의 상태 악화 징후와 응급 시 연락 방법을 교육한다.';why='가족이 이상 징후를 조기에 알아차리면 신속한 대처로 합병증을 예방할 수 있다.'})
}
$script:Templates['노쇠 증후군'] = @{
    en = 'Frail elderly syndrome'
    domain = '1. 건강증진 Health promotion'
    cls = '2. 건강관리 Health management'
    page = $null
    problem = '노쇠'
    priority = 4
    reason = '노쇠는 근력·영양·활동 저하를 포함하는 생리적 문제로 낙상과 기능 저하로 이어지므로 ABC 이후 기본 생리적 요구로 우선 다룬다'
    evalData = '체중 변화, 악력·보행 속도, 일상생활수행능력(ADL) 정도, 식사 섭취량, 피로 호소, 활동량'
    keywords = '노쇠|frail|근감소|sarcopenia|체중 감소|악력 (저하|감소)|보행 속도 (저하|느림)|기력 (없|저하)|쇠약|ADL (저하|의존)|고령'
    cause = '만성 질환과 신체 활동 감소'
    long = '대상자는 퇴원 시 현재 수준 이상의 일상생활수행능력을 유지할 것이다.'
    short = @('대상자는 1주일 내 매 식사량의 2/3 이상을 섭취할 것이다.','대상자는 1주일 내 보조기구를 이용하여 하루 2회 이상 병동 복도를 걸을 것이다.')
    diag = @(
        @{plan='입원 시와 매주 체중, 식사 섭취량, 영양 상태(알부민, 단백질)를 사정한다.';why='의도하지 않은 체중 감소와 영양 결핍은 노쇠의 핵심 요소로 진행 정도를 보여준다.'},
        @{plan='일상생활수행능력(ADL), 보행 상태, 근력, 낙상 위험도(Morse Fall Scale)를 사정한다.';why='기능 상태를 반복 사정하면 신체 기능 저하와 낙상 위험을 조기에 파악할 수 있다.'},
        @{plan='인지 기능, 우울, 복용 중인 약물 수(다약제 복용)를 확인한다.';why='인지 저하·우울·다약제 복용은 노쇠를 악화시키고 낙상과 섬망의 위험을 높인다.'})
    ther = @(
        @{plan='대상자의 기호를 반영한 고단백·고열량 식이를 제공하고 필요 시 영양사와 상의한다.';why='충분한 단백질과 열량 섭취는 근육량 유지와 기력 회복에 필요하다.'},
        @{plan='금기가 아닐 시 대상자의 능력에 맞춰 점진적인 근력·보행 운동을 격려한다.';why='규칙적인 저항 운동과 보행은 근력 저하를 늦추고 신체 기능을 유지시킨다.'},
        @{plan='침대 높이를 낮추고 호출벨을 가까이 두며 미끄럼 방지 신발을 신게 한다.';why='노쇠한 노인은 낙상 위험이 높으므로 안전한 환경이 손상을 예방한다.'},
        @{plan='대상자가 할 수 있는 자가간호는 스스로 하도록 격려하고 필요한 부분만 돕는다.';why='스스로 하는 활동은 남아 있는 기능을 유지하고 의존도를 줄인다.'},
        @{plan='복용 약물을 의료진과 함께 검토하여 불필요한 약물 조정을 상의한다.';why='다약제 복용을 줄이면 약물 부작용, 낙상, 인지 저하 위험이 감소한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 가정에서 할 수 있는 간단한 운동과 단백질 섭취 방법을 교육한다.';why='퇴원 후에도 운동과 영양을 지속해야 노쇠의 진행을 늦출 수 있다.'},
        @{plan='보호자에게 가정 내 낙상 예방 방법(조명, 미끄럼 방지 매트, 문턱 제거)을 교육한다.';why='가정 환경을 정비하면 노쇠 노인의 낙상과 골절을 예방할 수 있다.'})
}
$script:Templates['비효과적 건강유지행동'] = @{
    en = 'Ineffective health maintenance behaviors'
    domain = '1. 건강증진 Health promotion'
    cls = '2. 건강관리 Health management'
    page = $null
    problem = '건강유지행동 부족'
    priority = 7
    reason = '즉각적인 생리적 위협은 아니지만 건강 증진 행위가 부족하면 장기적으로 질병 발생 위험이 높아지므로 다른 문제 해결 후 다룬다'
    evalData = '건강검진·예방접종 여부, 흡연·음주·운동·식습관, 건강 증진 행위에 대한 지식과 실천 의지 표현'
    keywords = '건강검진 ?(안|미|받은 적 없)|예방접종 ?(안|미)|흡연|담배|음주|술을? 자주|운동 ?(안|안 함|하지 않)|불규칙한 식사|폭음|smok|alcohol|sedentary|좌식'
    cause = '건강 증진 행위에 대한 지식 부족'
    long = '대상자는 퇴원 시 자신에게 필요한 건강 유지 행위와 실천 계획을 말로 표현할 것이다.'
    short = @('대상자는 3일 내 자신의 건강 위험 요인을 두 가지 이상 말할 것이다.','대상자는 1주일 내 실천할 건강 행위 목표(금연, 운동 등)를 한 가지 이상 정할 것이다.')
    diag = @(
        @{plan='대상자의 생활 습관(흡연, 음주, 운동, 식습관, 수면)을 사정한다.';why='건강 위험 행위를 파악해야 중재가 필요한 우선 영역을 정할 수 있다.'},
        @{plan='건강검진, 예방접종, 정기 진료 이용 현황을 확인한다.';why='예방적 건강관리 이용 여부는 대상자의 건강 유지 수준을 보여준다.'},
        @{plan='건강 행위를 방해하는 요인(시간, 비용, 정보 부족, 동기 부족)과 건강 신념을 사정한다.';why='방해 요인과 신념을 알아야 대상자에게 맞는 현실적인 중재를 계획할 수 있다.'})
    ther = @(
        @{plan='대상자와 함께 실천 가능한 작은 단계의 건강 행위 목표를 세운다.';why='작고 구체적인 목표는 성공 경험을 주어 행동 변화를 지속시킨다.'},
        @{plan='대상자의 변화 단계(무관심기, 준비기 등)에 맞추어 동기면담을 적용한다.';why='변화 준비 정도에 맞춘 접근은 저항을 줄이고 스스로 변화하려는 동기를 높인다.'},
        @{plan='금연 클리닉, 보건소 건강증진 프로그램 등 지역사회 자원을 안내한다.';why='전문 프로그램과 지지 자원은 건강 행위를 꾸준히 유지하도록 돕는다.'},
        @{plan='실천한 행위를 칭찬하고 긍정적으로 강화한다.';why='긍정적 강화는 자기효능감을 높여 건강 행위를 지속하게 한다.'})
    edu = @(
        @{plan='대상자에게 연령과 건강 상태에 맞는 건강검진, 예방접종, 생활 습관 관리 방법을 교육한다.';why='정확한 정보는 대상자가 스스로 건강을 관리할 수 있는 바탕이 된다.'},
        @{plan='대상자와 보호자에게 위험 행위(흡연, 과음)가 건강에 미치는 영향을 교육한다.';why='위험 행위의 결과를 이해하면 행동 변화의 필요성을 느끼게 된다.'})
}
$script:Templates['비만'] = @{
    en = 'Obesity'
    domain = '2. 영양 Nutrition'
    cls = '1. 섭취 Ingestion'
    page = $null
    problem = '비만'
    priority = 4
    reason = '비만은 당뇨·고혈압·심혈관 질환 등의 위험을 높이는 생리적 영양 문제이나 급성 생명 위협은 아니므로 ABC 이후 기본 생리적 요구로 다룬다'
    evalData = '체중·BMI·허리둘레 변화, 하루 섭취 열량과 식습관, 신체 활동량, 체중 감량 목표와 실천 방법 표현 여부'
    keywords = '비만|obes|BMI ?(3\d|[4-9]\d)|BMI.{0,6}(3\d|[4-9]\d)|체중 (과다|증가)|허리둘레|복부비만|과식|폭식|야식|고도비만|대사증후군'
    cause = '에너지 소비를 초과하는 열량 섭취'
    long = '대상자는 퇴원 시 체중 감량을 위한 식이와 운동 계획을 말로 표현할 것이다.'
    short = @('대상자는 3일 내 하루 섭취한 음식을 식사일지에 기록할 것이다.','대상자는 1주일 내 하루 30분 이상 걷기 운동을 실천할 것이다.')
    diag = @(
        @{plan='매일 같은 시간, 같은 저울로 체중을 측정하고 주 1회 BMI와 허리둘레를 확인한다.';why='같은 조건에서 측정해야 체중 변화를 정확히 비교할 수 있고, 허리둘레는 복부비만과 대사 위험을 반영한다.'},
        @{plan='식습관(식사 횟수, 간식, 야식, 음료, 외식 빈도)과 하루 섭취 열량을 사정한다.';why='과잉 섭취의 원인이 되는 식습관을 파악해야 구체적인 식이 조절 계획을 세울 수 있다.'},
        @{plan='혈당, 지질 검사, 혈압 등 비만 관련 합병증 지표를 확인한다.';why='비만은 대사증후군과 심혈관 질환의 위험 요인이므로 동반 질환을 함께 확인해야 한다.'})
    ther = @(
        @{plan='영양사와 상의하여 대상자의 기호를 반영한 저열량·균형 식이를 계획한다.';why='무리한 제한보다 균형 잡힌 저열량 식이가 영양 결핍 없이 체중 감량을 지속시킨다.'},
        @{plan='금기가 아닐 시 대상자의 체력에 맞는 유산소 운동을 점진적으로 늘리도록 격려한다.';why='규칙적인 유산소 운동은 에너지 소비를 늘리고 심폐 기능을 향상시킨다.'},
        @{plan='대상자와 함께 현실적인 체중 감량 목표(주 0.5~1kg)를 정한다.';why='급격한 감량보다 점진적 감량이 안전하며 요요 현상을 줄인다.'},
        @{plan='식사일지와 체중 기록을 함께 확인하고 실천한 부분을 칭찬한다.';why='자기 감시와 긍정적 강화는 행동 변화를 오래 유지하게 한다.'},
        @{plan='체중에 대한 감정과 스트레스를 표현하도록 격려한다.';why='스트레스성 과식이 있는 경우 정서적 지지가 식습관 개선에 도움이 된다.'})
    edu = @(
        @{plan='대상자에게 식품 성분표 읽는 법, 저열량 조리법, 천천히 먹는 습관을 교육한다.';why='실생활에서 활용할 수 있는 방법은 퇴원 후에도 식이 조절을 지속하게 한다.'},
        @{plan='대상자와 보호자에게 비만이 건강에 미치는 영향과 가족이 함께하는 식습관 개선의 중요성을 교육한다.';why='가족의 지지와 참여는 대상자의 체중 관리 성공률을 높인다.'})
}
$script:Templates['과체중'] = @{
    en = 'Overweight'
    domain = '2. 영양 Nutrition'
    cls = '1. 섭취 Ingestion'
    page = $null
    problem = '과체중'
    priority = 4
    reason = '과체중은 비만과 만성 질환으로 진행할 수 있는 영양 문제이나 급성 위협이 아니므로 ABC 이후 기본 생리적 요구로 다룬다'
    evalData = '체중·BMI·허리둘레 변화, 식사일지 기록, 하루 신체 활동 시간, 체중 관리 방법 표현 여부'
    keywords = '과체중|overweight|BMI ?(2[3-9])|BMI.{0,6}2[3-9]|체중 (증가|늘었)|간식을? 자주|야식|운동 부족|좌식 생활|sedentary|단 음료|탄산음료'
    cause = '좌식 생활 습관과 신체 활동 부족'
    long = '대상자는 퇴원 시 정상 체중을 유지하기 위한 식이와 운동 계획을 말로 표현할 것이다.'
    short = @('대상자는 3일 내 체중 증가와 관련된 자신의 식습관을 두 가지 이상 말할 것이다.','대상자는 1주일 내 하루 30분 이상 신체 활동을 실천할 것이다.')
    diag = @(
        @{plan='매일 같은 시간, 같은 저울로 체중을 측정하고 BMI와 허리둘레를 확인한다.';why='일정한 조건의 측정은 체중 변화 추이를 정확하게 보여준다.'},
        @{plan='하루 식사 내용, 간식·음료 섭취, 식사 시간과 속도를 사정한다.';why='체중 증가와 관련된 구체적인 식습관을 파악해야 개선 방향을 정할 수 있다.'},
        @{plan='하루 신체 활동량과 앉아서 보내는 시간을 사정한다.';why='활동량 부족은 에너지 소비를 줄여 체중 증가의 주요 원인이 된다.'})
    ther = @(
        @{plan='대상자와 함께 실천 가능한 식이 목표(단 음료 줄이기, 야식 줄이기 등)를 정한다.';why='구체적이고 작은 목표는 실천 가능성을 높이고 성공 경험을 준다.'},
        @{plan='금기가 아닐 시 걷기, 계단 이용 등 일상생활 속 활동을 늘리도록 격려한다.';why='일상 활동을 늘리면 큰 부담 없이 에너지 소비를 높일 수 있다.'},
        @{plan='식사일지와 활동 기록을 작성하도록 돕고 함께 검토한다.';why='자기 감시는 자신의 행동을 인식하게 하여 행동 변화를 돕는다.'},
        @{plan='목표를 달성한 부분을 칭찬하고 격려한다.';why='긍정적 강화는 건강 행위를 지속하려는 동기를 높인다.'})
    edu = @(
        @{plan='대상자에게 균형 잡힌 식사 구성, 적정 열량, 건강한 간식 선택 방법을 교육한다.';why='올바른 영양 지식은 스스로 식단을 조절하는 능력을 높인다.'},
        @{plan='대상자에게 과체중이 비만과 만성 질환으로 진행할 수 있음을 설명하고 규칙적인 체중 측정을 교육한다.';why='위험을 이해하고 체중을 스스로 확인하면 조기에 관리할 수 있다.'})
}
$script:Templates['비효과적 모유수유'] = @{
    en = 'Ineffective breastfeeding'
    domain = '2. 영양 Nutrition'
    cls = '1. 섭취 Ingestion'
    page = $null
    problem = '모유수유 어려움'
    priority = 4
    reason = '모유수유 문제는 신생아의 영양과 수분 공급에 직접 영향을 주는 기본 생리적 요구이므로 ABC 이후 우선적으로 다룬다'
    evalData = '젖물림 상태(LATCH 점수), 수유 횟수와 시간, 신생아 체중 변화, 하루 소변·대변 횟수, 유두 통증·손상 여부, 산모의 수유 자신감 표현'
    keywords = '모유 ?수유 ?(어려|힘들|실패|거부)|젖을? (안|못) ?(물|빨)|젖물림|latch|LATCH|유두 ?(통증|균열|열상|상처)|nipple|breastfeed|유방 울혈|engorgement|젖이 (안|잘 안) 나|분유로 바꾸'
    cause = '부적절한 젖물림 자세'
    long = '대상자는 퇴원 시 올바른 자세와 젖물림으로 모유수유를 할 것이다.'
    short = @('대상자는 2일 내 올바른 수유 자세와 젖물림 방법을 시범 보일 것이다.','대상자는 3일 내 신생아에게 하루 8회 이상 모유수유를 할 것이다.')
    diag = @(
        @{plan='수유 시 산모의 자세와 신생아의 젖물림 상태를 관찰하고 LATCH 점수로 평가한다.';why='젖물림이 잘못되면 젖이 효과적으로 나오지 않고 유두 손상이 생기므로 객관적 도구로 평가해야 한다.'},
        @{plan='신생아의 체중 변화, 하루 소변·대변 횟수, 수유 후 만족 행동을 사정한다.';why='충분한 수유 여부는 신생아의 체중과 배설 양상으로 확인할 수 있다.'},
        @{plan='산모의 유방(울혈, 유두 통증·균열)과 수유에 대한 걱정, 피로 정도를 사정한다.';why='유방 문제와 산모의 불안·피로는 모유수유를 방해하는 주요 요인이다.'})
    ther = @(
        @{plan='수유 시 산모 곁에서 편안한 자세(요람 자세, 교차 요람 자세, 미식축구 자세)를 취하도록 돕는다.';why='편안하고 안정된 자세는 신생아가 깊게 젖을 물 수 있게 하여 수유 효과를 높인다.'},
        @{plan='신생아가 유두와 유륜의 대부분을 깊게 물도록 돕고 잘못 물었을 때 손가락으로 입을 떼어 다시 물리도록 한다.';why='깊은 젖물림은 유두 손상을 예방하고 효과적인 젖 배출을 돕는다.'},
        @{plan='모자동실을 격려하고 신생아의 배고픔 신호에 맞추어 자주 수유하게 한다.';why='자주 빨리면 프로락틴과 옥시토신 분비가 촉진되어 모유 생산이 늘어난다.'},
        @{plan='유두 통증이 있으면 수유 후 모유를 유두에 발라 자연 건조하도록 하고 울혈 시 수유 전 온찜질과 수유 후 냉찜질을 적용한다.';why='모유는 유두 상처 치유를 돕고, 온찜질은 사출을 돕고 냉찜질은 울혈로 인한 부종과 통증을 줄인다.'},
        @{plan='산모의 노력을 칭찬하고 정서적 지지를 제공한다.';why='산모의 자신감과 안정감은 옥시토신 분비를 도와 수유 지속에 도움이 된다.'})
    edu = @(
        @{plan='산모에게 신생아의 배고픔 신호(입 오물거림, 손 빨기, 고개 돌리기)와 충분한 수유의 지표(하루 소변 6회 이상, 체중 증가)를 교육한다.';why='산모가 신호와 지표를 알면 적절한 시기에 수유하고 수유량이 충분한지 스스로 판단할 수 있다.'},
        @{plan='산모와 보호자에게 유방 울혈·유선염의 증상과 퇴원 후 이용할 수 있는 모유수유 상담 자원을 교육한다.';why='합병증을 조기에 발견하고 도움을 받으면 모유수유를 중단하지 않고 지속할 수 있다.'})
}
$script:Templates['불충분한 모유 생산'] = @{
    en = 'Inadequate human milk production'
    domain = '2. 영양 Nutrition'
    cls = '1. 섭취 Ingestion'
    page = $null
    problem = '모유 생산 부족'
    priority = 4
    reason = '모유 생산 부족은 신생아의 영양과 수분 공급에 직접 영향을 주는 기본 생리적 문제이므로 ABC 이후 우선적으로 다룬다'
    evalData = '하루 수유·유축 횟수, 유축량, 신생아 체중 변화, 신생아 하루 소변·대변 횟수, 산모의 수분·영양 섭취와 휴식 정도'
    keywords = '젖이 (안|잘 안|적게|부족) ?나|젖양 ?(부족|적)|모유 ?(양|량)? ?(부족|감소|적)|유축량 ?(적|감소)|insufficient (milk|lactation)|low milk supply|수유 횟수 (적|부족)|분유 보충'
    cause = '불충분한 수유 및 유축 빈도'
    long = '대상자는 퇴원 시 모유 생산을 늘리는 방법을 말로 표현하고 실천할 것이다.'
    short = @('대상자는 2일 내 24시간 동안 8~12회 수유 또는 유축을 할 것이다.','대상자는 3일 내 모유 생산을 늘리는 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='하루 수유와 유축 횟수, 수유 시간, 유축량을 기록하고 확인한다.';why='모유 생산은 젖을 비워 주는 빈도에 비례하므로 수유 패턴을 확인해야 원인을 알 수 있다.'},
        @{plan='신생아의 체중 변화와 하루 소변·대변 횟수를 사정한다.';why='신생아의 체중과 배설 양상은 섭취한 모유량이 충분한지 보여주는 지표다.'},
        @{plan='산모의 피로, 수면, 수분·영양 섭취, 통증, 스트레스 정도와 모유 생산에 영향을 주는 요인(분만 시 출혈, 약물)을 사정한다.';why='피로와 스트레스, 산후 출혈 등은 옥시토신·프로락틴 분비를 방해하여 모유 생산을 줄일 수 있다.'})
    ther = @(
        @{plan='24시간 동안 8~12회 수유하거나, 직접 수유가 어려우면 같은 횟수로 유축하도록 돕는다.';why='자주 젖을 비우면 프로락틴 분비가 증가하여 모유 생산이 늘어난다.'},
        @{plan='수유 시 양쪽 유방을 번갈아 충분히 비우게 하고 수유 전 유방 마사지와 온찜질을 적용한다.';why='유방을 완전히 비우면 모유 생산 억제 인자가 줄고, 마사지와 온찜질은 사출 반사를 돕는다.'},
        @{plan='피부 접촉(캥거루 케어)과 모자동실을 격려한다.';why='피부 접촉은 옥시토신 분비를 촉진하여 젖 사출과 모유 생산을 돕는다.'},
        @{plan='산모가 충분히 휴식하고 수분과 영양을 섭취하도록 돕는다.';why='충분한 휴식과 영양은 산모의 회복과 모유 생산에 필요하다.'},
        @{plan='신생아의 체중 감소가 크면 의료진과 상의하여 보충 수유 방법(컵, 수유 보조기)을 정한다.';why='신생아의 영양이 부족하지 않도록 보충하면서도 젖병 혼동을 줄여 모유수유를 유지할 수 있다.'})
    edu = @(
        @{plan='산모에게 모유 생산 원리(수요와 공급)와 자주 수유·유축해야 하는 이유를 교육한다.';why='원리를 이해하면 수유 횟수를 스스로 유지하려는 동기가 높아진다.'},
        @{plan='산모와 보호자에게 신생아가 충분히 먹고 있다는 지표와 병원에 연락해야 하는 상황(소변 감소, 체중 감소 지속, 황달 악화)을 교육한다.';why='이상 징후를 조기에 알아차리면 신생아의 탈수와 영양 부족을 예방할 수 있다.'})
}
$script:Templates['연하장애'] = @{
    en = 'Impaired swallowing'
    domain = '2. 영양 Nutrition'
    cls = '1. 섭취 Ingestion'
    page = $null
    problem = '연하장애'
    priority = 1
    reason = '삼킴 기능이 손상되면 음식물이 기도로 넘어가 흡인과 질식, 흡인성 폐렴을 일으킬 수 있으므로 기도 유지 차원에서 가장 먼저 다룬다'
    evalData = '연하 선별검사 결과, 식사 중 기침·사레·목소리 변화, SpO2, 호흡음, 체온, 식사 섭취량과 체중, 안전한 식사 방법 표현 여부'
    keywords = '연하 ?(곤란|장애)|삼키기 (힘들|어려)|삼킴 ?(곤란|장애)|dysphagia|사레|식사 중 기침|흡인|aspiration|물 마시면 기침|침 ?흘|drooling|뇌졸중|stroke|CVA|비위관|L-?tube|levin|점도증진제'
    cause = '뇌졸중으로 인한 신경근육 손상'
    long = '대상자는 퇴원 시 흡인 없이 안전하게 음식을 섭취할 것이다.'
    short = @('대상자는 3일 내 식사 중 기침이나 사레 없이 처방된 식이를 섭취할 것이다.','대상자는 1주일 내 안전하게 삼키는 방법(턱 당기기, 소량씩 먹기)을 시범 보일 것이다.')
    diag = @(
        @{plan='식이 시작 전 연하 선별검사(물 삼킴 검사 등)를 시행하고 필요 시 연하 평가(VFSS)를 의뢰한다.';why='삼킴 기능을 확인하기 전에 경구 섭취를 시작하면 흡인 위험이 크므로 먼저 평가해야 한다.'},
        @{plan='식사 중과 식사 후 기침, 사레, 젖은 목소리, 입 안 음식물 잔여, SpO2 저하를 관찰한다.';why='이러한 증상은 흡인을 시사하는 징후로, 조기에 발견하면 흡인성 폐렴을 예방할 수 있다.'},
        @{plan='매 듀티마다 호흡음과 체온을 사정하고 식사 섭취량과 체중을 확인한다.';why='폐 수포음과 발열은 흡인성 폐렴의 징후이고, 섭취량과 체중은 영양 상태를 보여준다.'})
    ther = @(
        @{plan='식사 중과 식후 30분 이상 상체를 90도 가까이 세운 앉은 자세를 유지한다.';why='똑바로 앉은 자세는 중력으로 음식물이 식도로 넘어가게 하고 역류와 흡인을 줄인다.'},
        @{plan='처방된 식이 형태(점도증진제를 넣은 액체, 갈거나 다진 음식)를 제공하고 소량씩 천천히 먹게 한다.';why='적절한 점도와 소량 섭취는 삼키는 시간을 확보하여 흡인 위험을 낮춘다.'},
        @{plan='삼킬 때 턱을 당기도록 하고 마비가 있으면 건강한 쪽으로 음식을 넣는다.';why='턱 당기기는 기도 입구를 좁혀 흡인을 막고, 건측으로 넣으면 음식물 조절이 쉬워진다.'},
        @{plan='식사 전후 구강 간호를 시행하고 침상 옆에 흡인기를 준비한다.';why='구강 내 세균과 음식물 잔여를 줄이면 흡인성 폐렴 위험이 감소하고, 흡인기는 응급 시 기도를 확보한다.'},
        @{plan='식사 중 대화나 TV 시청 등 주의를 분산시키는 요인을 줄인다.';why='식사에 집중해야 삼킴 동작을 의식적으로 조절하여 사레를 줄일 수 있다.'})
    edu = @(
        @{plan='대상자와 보호자에게 안전한 식사 자세, 음식 형태, 한 입 양, 턱 당기기 방법을 교육한다.';why='보호자가 방법을 알면 퇴원 후 가정에서도 흡인 없이 식사를 도울 수 있다.'},
        @{plan='보호자에게 흡인 징후(기침, 숨참, 얼굴색 변화)와 응급 시 대처 방법, 발열 시 병원에 알려야 함을 교육한다.';why='흡인과 흡인성 폐렴을 조기에 발견하고 대처하면 생명을 위협하는 합병증을 막을 수 있다.'})
}
$script:Templates['비효과적 영아 수유역동'] = @{
    en = 'Ineffective infant feeding dynamics'
    domain = '2. 영양 Nutrition'
    cls = '1. 섭취 Ingestion'
    page = $null
    problem = '영아 수유 문제'
    priority = 4
    reason = '영아의 수유 문제는 성장과 수분 공급에 직접 영향을 주는 기본 생리적 요구로 ABC 이후 우선적으로 다룬다'
    evalData = '수유량과 수유 시간, 영아 체중과 성장곡선, 하루 소변·대변 횟수, 수유 중 빨기·삼키기·호흡 협응, 보호자의 수유 방법 시범 여부'
    keywords = '수유 ?(거부|곤란|어려|문제)|분유를? (안|잘 안|적게) ?먹|빠는 힘 (약|없)|weak suck|poor (feeding|suck)|feeding (difficulty|intolerance)|체중 증가 (불량|부족)|성장 부진|failure to thrive|FTT|수유 중 (청색증|무호흡|사레)|미숙아|조산아|preterm'
    cause = '영아의 미숙한 빨기·삼키기·호흡 협응'
    long = '영아는 퇴원 시 연령에 맞는 수유량을 섭취하고 체중이 증가할 것이다.'
    short = @('영아는 3일 내 처방된 1회 수유량을 30분 이내에 섭취할 것이다.','영아의 보호자는 3일 내 올바른 수유 자세와 배고픔·포만 신호를 시범 보이고 말로 표현할 것이다.')
    diag = @(
        @{plan='매 수유 시 수유량, 수유 시간, 빨기·삼키기·호흡 협응, 수유 중 SpO2와 피부색 변화를 관찰한다.';why='빨기·삼키기·호흡의 협응이 미숙하면 수유 중 사레, 무호흡, 산소포화도 저하가 생길 수 있다.'},
        @{plan='매일 같은 시간, 같은 저울로 체중을 측정하고 성장곡선과 하루 소변·대변 횟수를 확인한다.';why='체중 증가와 배설 양상은 영아의 수유가 충분한지 보여주는 객관적 지표다.'},
        @{plan='보호자의 수유 방법(자세, 젖병 각도, 수유 간격)과 영아의 신호를 읽는 능력을 관찰한다.';why='보호자의 수유 방법과 신호 해석이 부적절하면 과소·과다 수유가 생길 수 있다.'})
    ther = @(
        @{plan='영아를 반쯤 세운 자세로 안고 머리와 몸을 일직선으로 받쳐 수유한다.';why='반좌위는 흡인을 줄이고 영아가 안정적으로 빨고 삼킬 수 있게 한다.'},
        @{plan='영아의 배고픔·포만·스트레스 신호(고개 돌리기, 손 펴기, 피부색 변화)에 맞추어 수유 속도를 조절하고 필요 시 쉬게 한다.';why='영아의 신호에 반응하는 수유는 피로와 사레를 줄이고 안전한 수유를 돕는다.'},
        @{plan='수유 중간과 수유 후 트림을 시키고 수유 후 30분간 상체를 약간 높여 관찰한다.';why='트림은 삼킨 공기를 배출하여 구토와 역류를 줄인다.'},
        @{plan='처방에 따라 젖꼭지 유량을 조절하거나 비위관 보충 수유를 시행하고 위잔류량을 확인한다.';why='영아의 능력에 맞는 유량과 보충 수유는 에너지 소모를 줄이면서 필요한 영양을 공급한다.'},
        @{plan='조용하고 자극이 적은 환경에서 수유한다.';why='외부 자극을 줄이면 영아가 수유에 집중하고 생리적으로 안정된다.'})
    edu = @(
        @{plan='보호자에게 올바른 수유 자세, 젖병 잡는 각도, 트림 시키는 방법을 시범 보이고 직접 해 보게 한다.';why='직접 수행해 보면 기술이 익숙해져 가정에서도 안전하게 수유할 수 있다.'},
        @{plan='보호자에게 영아의 배고픔·포만 신호와 병원에 연락해야 하는 상황(수유 거부, 소변 감소, 수유 중 청색증, 체중 감소)을 교육한다.';why='보호자가 신호와 위험 징후를 알면 적절히 수유하고 문제를 조기에 발견할 수 있다.'})
}
$script:Templates['불안정한 혈당 수치의 위험'] = @{
    en = 'Risk for unstable blood glucose level'
    domain = '2. 영양 Nutrition'
    cls = '4. 대사 Metabolism'
    page = $null
    problem = '혈당 불안정 위험'
    priority = 4
    reason = '아직 나타나지 않은 위험 진단이지만 저혈당·고혈당은 의식 저하로 빠르게 진행할 수 있는 대사 문제이므로 생리적 요구로 우선 관리한다'
    evalData = '식전·취침 전 혈당, HbA1c, 저혈당·고혈당 증상 유무, 식사 섭취량, 인슐린·경구혈당강하제 투여 시간, 저혈당 대처 방법 표현 여부'
    keywords = '혈당|BST|FBS|PP2|HbA1c|당화혈색소|glucose|당뇨|DM\b|diabet|인슐린|insulin|저혈당|hypoglyc|고혈당|hyperglyc|메트포르민|metformin|란투스|휴마로그|노보래피드|식은땀'
    cause = '불규칙한 식사와 혈당강하제 투여'
    long = '대상자는 퇴원 시까지 혈당을 목표 범위 안에서 유지할 것이다.'
    short = @('대상자는 3일 내 식전 혈당이 80~130mg/dL 범위를 유지할 것이다.','대상자는 3일 내 저혈당 증상과 대처 방법(15g 당 섭취 후 15분 뒤 재측정)을 말로 표현할 것이다.')
    diag = @(
        @{plan='처방에 따라 식전과 취침 전 혈당을 측정하고 추이를 기록한다.';why='정기적인 혈당 측정은 혈당 변동을 조기에 발견하고 투약 조정의 근거가 된다.'},
        @{plan='저혈당 증상(식은땀, 떨림, 빈맥, 어지러움, 의식 저하)과 고혈당 증상(다뇨, 다갈, 피로)을 관찰한다.';why='증상을 빠르게 알아차려야 저혈당 쇼크나 고혈당 위기를 예방할 수 있다.'},
        @{plan='식사 섭취량, 금식 여부, 활동량, 감염·스트레스, 스테로이드 투여 여부를 확인한다.';why='섭취량 감소와 금식은 저혈당을, 감염·스트레스·스테로이드는 고혈당을 유발할 수 있다.'})
    ther = @(
        @{plan='처방에 따라 인슐린 또는 경구혈당강하제를 정확한 시간과 용량으로 투여하고 식사 시간과 맞춘다.';why='약물과 식사 시간이 맞지 않으면 저혈당이나 고혈당이 생길 수 있다.'},
        @{plan='금식이나 식사량 감소 시 혈당강하제 투여 전 의료진에게 확인한다.';why='섭취가 없는 상태에서 혈당강하제를 투여하면 저혈당 위험이 커진다.'},
        @{plan='저혈당 시 의식이 있으면 15g의 단순당(주스 반 컵 등)을 제공하고 15분 후 혈당을 재측정하며, 의식이 없으면 처방에 따라 포도당을 정맥 투여한다.';why='단순당은 빠르게 흡수되어 혈당을 올리며, 재측정으로 교정 여부를 확인해야 한다.'},
        @{plan='영양사와 상의하여 규칙적인 시간에 일정한 열량의 식사를 제공한다.';why='일정한 식사는 혈당 변동 폭을 줄인다.'})
    edu = @(
        @{plan='대상자에게 자가 혈당 측정 방법, 저혈당·고혈당 증상과 대처 방법을 교육하고 직접 시범 보이게 한다.';why='대상자가 스스로 측정하고 대처할 수 있으면 퇴원 후 응급 상황을 예방할 수 있다.'},
        @{plan='대상자와 보호자에게 규칙적인 식사, 운동 전후 혈당 확인, 아플 때(sick day) 관리 방법과 사탕 등 당 휴대를 교육한다.';why='생활 속 혈당 변동 요인을 관리하면 혈당을 안정적으로 유지할 수 있다.'})
}
$script:Templates['신생아 고빌리루빈혈증'] = @{
    en = 'Neonatal hyperbilirubinemia'
    domain = '2. 영양 Nutrition'
    cls = '4. 대사 Metabolism'
    page = $null
    problem = '신생아 황달'
    priority = 4
    reason = '빌리루빈이 계속 오르면 핵황달로 뇌손상이 생길 수 있는 생리적 대사 문제이므로 ABC 이후 우선적으로 관리한다'
    evalData = '혈청·경피 빌리루빈 수치 추이, 피부·공막 황달 범위, 수유 횟수와 섭취량, 하루 소변·대변 횟수와 변 색깔, 체중, 체온, 기면·빨기 약화 여부'
    keywords = '황달|jaundice|빌리루빈|bilirubin|TSB|TcB|광선요법|phototherapy|고빌리루빈|hyperbilirubin|공막 황달|피부가 노랗|노랗게|핵황달|kernicterus|ABO 부적합|교환수혈'
    cause = '미성숙한 간 기능과 불충분한 수유'
    long = '신생아는 퇴원 시 빌리루빈 수치가 연령(시간)별 치료 기준 이하로 유지될 것이다.'
    short = @('신생아는 2일 내 하루 8~12회 수유하고 하루 소변 6회 이상, 대변 3회 이상을 볼 것이다.','신생아는 3일 내 혈청 빌리루빈 수치가 감소할 것이다.')
    diag = @(
        @{plan='처방에 따라 혈청 또는 경피 빌리루빈 수치를 측정하고 생후 시간별 기준표(nomogram)와 비교한다.';why='빌리루빈은 생후 시간에 따라 위험 기준이 다르므로 기준표와 비교해야 치료 필요성을 정확히 판단할 수 있다.'},
        @{plan='자연광 아래에서 피부를 눌러 황달의 범위(얼굴에서 몸통, 다리로 진행)와 공막 황달을 관찰한다.';why='황달은 머리에서 발 쪽으로 진행하므로 범위를 보면 대략적인 진행 정도를 알 수 있다.'},
        @{plan='매 듀티마다 수유 상태, 활력징후, 기면, 빨기 약화, 고음의 울음, 근긴장도 변화를 관찰한다.';why='기면과 빨기 약화, 고음의 울음은 급성 빌리루빈 뇌병증의 초기 징후일 수 있어 즉시 보고해야 한다.'})
    ther = @(
        @{plan='처방에 따라 광선요법을 시행하고 기저귀 외 피부를 최대한 노출하며 안대로 눈을 보호한다.';why='광선은 피부의 빌리루빈을 수용성 형태로 바꾸어 배설을 돕고, 안대는 망막 손상을 예방한다.'},
        @{plan='광선요법 중 2~4시간마다 체온을 측정하고 2~3시간마다 체위를 변경한다.';why='광선 장치는 고체온이나 수분 손실을 유발할 수 있고, 체위 변경은 피부 노출 면적을 고르게 한다.'},
        @{plan='하루 8~12회 수유를 격려하고 섭취량과 배설량, 체중을 기록한다.';why='충분한 수유는 장 운동을 늘려 빌리루빈의 대변 배설을 촉진하고 탈수를 예방한다.'},
        @{plan='광선요법 중 피부에 오일이나 로션을 바르지 않고 묽은 녹색 변으로 인한 피부 자극을 관리한다.';why='오일은 화상 위험을 높이고, 광선요법 중 늘어난 대변은 기저귀 피부염을 유발할 수 있다.'},
        @{plan='수유와 기저귀 교환 시를 제외하고 광선요법을 지속하되 수유 시 안대를 벗겨 부모와 눈을 맞추게 한다.';why='치료 효과를 유지하면서 부모와 신생아의 애착 형성을 도울 수 있다.'})
    edu = @(
        @{plan='보호자에게 신생아 황달의 원인, 광선요법의 목적과 주의사항을 교육한다.';why='보호자가 치료를 이해하면 불안이 줄고 치료에 적극적으로 협조할 수 있다.'},
        @{plan='보호자에게 퇴원 후 황달 관찰 방법과 병원에 연락해야 하는 상황(황달이 다리까지 진행, 잘 먹지 않음, 늘어짐, 소변 감소, 회색 변)을 교육한다.';why='퇴원 후 빌리루빈이 다시 오를 수 있으므로 보호자가 조기에 발견해야 핵황달을 예방할 수 있다.'})
}
$script:Templates['간 기능 장애의 위험'] = @{
    en = 'Risk for impaired liver function'
    domain = '2. 영양 Nutrition'
    cls = '4. 대사 Metabolism'
    page = $null
    problem = '간 기능 장애 위험'
    priority = 5
    reason = '아직 나타나지 않은 위험 진단이므로 실제적 진단보다 우선순위가 낮지만, 간 손상을 예방하기 위한 안전 요구로 관리가 필요하다'
    evalData = 'AST·ALT·빌리루빈·알부민·PT(INR) 추이, 황달·복부 불편감·식욕부진 유무, 간독성 약물 복용 여부, 음주 여부, 간 보호 방법 표현 여부'
    keywords = 'AST|ALT|GOT|GPT|간수치|간 ?기능|liver function|LFT|간염|hepatitis|HBV|HCV|지방간|fatty liver|간경화|cirrhosis|아세트아미노펜 과다|acetaminophen|항결핵제|이소니아지드|isoniazid|리팜핀|rifampin|음주|alcohol'
    cause = '간독성 약물 사용'
    long = '대상자는 퇴원 시까지 간 기능 검사 수치가 정상 범위를 유지할 것이다.'
    short = @('대상자는 3일 내 간에 부담을 주는 약물과 음식(술, 임의 복용 약, 건강보조식품)을 두 가지 이상 말할 것이다.','대상자는 1주일 내 AST·ALT가 정상 범위를 유지할 것이다.')
    diag = @(
        @{plan='처방에 따라 간 기능 검사(AST, ALT, 빌리루빈, 알부민, PT/INR) 결과를 확인하고 추이를 비교한다.';why='간 기능 검사 수치의 변화는 간 손상을 조기에 발견하는 객관적인 지표다.'},
        @{plan='황달, 피로, 식욕부진, 오심, 우상복부 불편감, 진한 소변, 출혈 경향을 관찰한다.';why='이러한 증상은 간 기능 저하의 징후로 조기에 발견하면 원인 약물 중단 등 빠른 대처가 가능하다.'},
        @{plan='복용 중인 약물(처방약, 일반약, 한약, 건강보조식품)과 음주량, 간염 병력을 확인한다.';why='간독성 약물과 음주, 바이러스 간염은 간 손상의 주요 위험 요인이다.'})
    ther = @(
        @{plan='간독성 약물 투여 시 처방된 용량과 간격을 정확히 지키고 이상 징후가 있으면 즉시 보고한다.';why='정확한 용량 관리와 조기 보고는 약물로 인한 간 손상을 예방한다.'},
        @{plan='아세트아미노펜 등 간에서 대사되는 약물이 중복 투여되지 않는지 확인한다.';why='여러 약물에 같은 성분이 들어 있으면 하루 최대 용량을 넘겨 간 손상을 일으킬 수 있다.'},
        @{plan='금기가 아닐 시 균형 잡힌 식사와 적절한 단백질 섭취를 격려한다.';why='적절한 영양은 간세포 재생과 간 기능 유지에 도움이 된다.'},
        @{plan='충분한 휴식을 취하도록 돕는다.';why='휴식은 간의 대사 부담을 줄이고 간 혈류를 늘려 회복을 돕는다.'})
    edu = @(
        @{plan='대상자에게 금주와 의사와 상의 없이 약, 한약, 건강보조식품을 복용하지 않도록 교육한다.';why='술과 임의 복용 약물은 간에 직접 부담을 주어 간 손상의 위험을 높인다.'},
        @{plan='대상자와 보호자에게 간 기능 저하 증상(황달, 진한 소변, 심한 피로, 복부 불편감)과 정기적인 간 기능 검사의 필요성을 교육한다.';why='증상을 알고 정기적으로 검사하면 간 손상을 조기에 발견하여 치료할 수 있다.'})
}
$script:Templates['과도한 체액량'] = @{
    en = 'Excessive fluid volume'
    domain = '2. 영양 Nutrition'
    cls = '5. 수화 Hydration'
    page = $null
    problem = '체액 과다'
    priority = 2
    reason = '체액이 과다하면 폐부종과 심부전 악화로 호흡과 순환에 직접 영향을 주므로 ABC 중 순환 문제로 우선 다룬다'
    evalData = '매일 같은 시간 체중, I/O, 부종 정도, 폐 수포음·호흡곤란·SpO2, 혈압·경정맥 팽대, 혈청 나트륨·BUN/Cr, 수분·염분 제한 이행 여부'
    keywords = '부종|edema|함요|pitting|체중 (증가|늘)|체액 ?(과다|과잉)|fluid overload|hypervolem|폐부종|pulmonary edema|수포음|crackle|rale|경정맥 ?팽대|JVD|심부전|heart failure|CHF|신부전|CKD|투석|라식스|lasix|furosemide|복수|ascites|I/?O ?(불균형|positive)'
    cause = '나트륨과 수분의 과다 정체'
    long = '대상자는 퇴원 시 부종이 감소하고 체액 균형을 유지할 것이다.'
    short = @('대상자는 3일 내 체중이 하루 0.5~1kg 감소하고 섭취량보다 배설량이 많을 것이다.','대상자는 3일 내 하루 수분·염분 제한량을 정확히 말로 표현할 것이다.')
    diag = @(
        @{plan='매일 아침 같은 시간, 같은 저울, 같은 옷차림으로 체중을 측정한다.';why='체중 1kg 증가는 약 1L의 체액 정체를 의미하므로 체중은 체액 변화를 가장 민감하게 보여준다.'},
        @{plan='매 듀티마다 I/O를 측정하고 부종 부위와 정도(함요부종 등급)를 사정한다.';why='섭취량과 배설량, 부종 정도를 비교하면 체액 정체의 정도와 치료 효과를 평가할 수 있다.'},
        @{plan='매 4시간마다 V/S, 호흡음(수포음), 호흡곤란, SpO2, 경정맥 팽대를 사정하고 전해질·BUN/Cr 결과를 확인한다.';why='폐 수포음과 호흡곤란은 폐부종의 징후이며, 전해질과 신기능은 이뇨 치료의 부작용과 원인 질환을 반영한다.'})
    ther = @(
        @{plan='처방에 따라 이뇨제를 투여하고 투여 후 소변량, 혈압, 혈청 칼륨을 확인한다.';why='이뇨제는 나트륨과 수분 배설을 늘려 체액을 줄이지만 저칼륨혈증과 저혈압을 일으킬 수 있다.'},
        @{plan='처방된 수분 제한과 저염식을 제공하고 하루 수분 섭취량을 나누어 계획한다.';why='수분과 나트륨 섭취를 줄이면 체액 정체가 감소하며, 나누어 계획하면 갈증을 견디기 쉽다.'},
        @{plan='호흡곤란 시 반좌위나 좌위를 취하게 하고 처방에 따라 산소를 투여한다.';why='상체를 높이면 정맥 환류가 줄고 횡격막이 내려가 폐 확장과 가스 교환이 좋아진다.'},
        @{plan='부종 부위를 심장보다 높이고 2시간마다 체위를 변경하며 피부를 보호한다.';why='부종 부위 거상은 정맥 환류를 돕고, 부종 피부는 손상되기 쉬우므로 압력을 분산해야 한다.'},
        @{plan='갈증 완화를 위해 구강 간호, 얼음 조각, 무설탕 껌을 제공한다.';why='수분 제한 중 갈증을 완화하면 제한을 지키기 쉬워진다.'})
    edu = @(
        @{plan='대상자에게 매일 체중 측정 방법과 하루 1kg 이상 또는 일주일에 2kg 이상 체중 증가 시 병원에 알리도록 교육한다.';why='급격한 체중 증가는 체액 정체 악화의 초기 신호이므로 스스로 확인하면 조기에 대처할 수 있다.'},
        @{plan='대상자와 보호자에게 저염식(국물·김치·가공식품 줄이기)과 수분 제한 방법, 숨참·부종 악화 시 대처 방법을 교육한다.';why='가정에서 식이를 조절하고 증상을 알아차리면 재입원을 예방할 수 있다.'})
}
$script:Templates['불충분한 체액량의 위험'] = @{
    en = 'Risk for inadequate fluid volume'
    domain = '2. 영양 Nutrition'
    cls = '5. 수화 Hydration'
    page = $null
    problem = '체액 부족 위험'
    priority = 2
    reason = '아직 나타나지 않은 위험 진단이지만 체액이 부족하면 순환 혈액량이 감소하여 저혈압과 쇼크로 진행할 수 있으므로 순환 문제로 우선 다룬다'
    evalData = 'I/O, 체중, 혈압·맥박, 소변량(0.5mL/kg/hr 이상)과 요비중, 피부 탄력·점막 건조, BUN/Cr·Hct·전해질, 수분 섭취 방법 표현 여부'
    keywords = '구토|vomit|설사|diarrh|탈수|dehydrat|구강 ?(건조|점막 건조)|피부 탄력 ?(저하|감소)|turgor|소변량 ?(감소|적)|핍뇨|oliguria|요비중|금식|NPO|갈증|발한|고열|출혈|배액량 ?(많|증가)|이뇨제'
    cause = '구토와 설사로 인한 체액 손실'
    long = '대상자는 퇴원 시까지 적절한 체액량을 유지할 것이다.'
    short = @('대상자는 2일 내 시간당 소변량이 0.5mL/kg 이상을 유지할 것이다.','대상자는 2일 내 하루 수분 섭취 목표량과 탈수 증상을 말로 표현할 것이다.')
    diag = @(
        @{plan='매 듀티마다 I/O를 측정하고 매일 같은 시간에 체중을 측정한다.';why='섭취량과 배설량, 체중 변화를 비교하면 체액 손실을 조기에 발견할 수 있다.'},
        @{plan='매 4시간마다 V/S(빈맥, 혈압 저하, 기립성 저혈압)와 소변량·요비중을 확인한다.';why='체액이 줄면 보상 기전으로 맥박이 빨라지고 소변이 농축되며, 이후 혈압이 떨어진다.'},
        @{plan='피부 탄력, 구강 점막 건조, 갈증, 의식 변화와 BUN/Cr, Hct, 전해질 결과를 확인한다.';why='탈수의 신체 징후와 혈액 농축 지표는 체액 부족의 정도를 객관적으로 보여준다.'})
    ther = @(
        @{plan='금기가 아닐 시 하루 1,500~2,000mL 이상의 수분 섭취를 격려하고 대상자가 좋아하는 음료를 자주 조금씩 제공한다.';why='자주 조금씩 마시면 구토를 덜 유발하면서 수분을 보충할 수 있다.'},
        @{plan='처방에 따라 수액을 정확한 속도로 주입하고 주입 부위를 관찰한다.';why='정맥 수액은 경구 섭취가 부족할 때 빠르게 체액을 보충하며, 과다 주입은 체액 과다를 일으킬 수 있다.'},
        @{plan='처방에 따라 항구토제나 지사제를 투여하고 효과를 확인한다.';why='구토와 설사를 조절하면 체액 손실의 원인을 줄일 수 있다.'},
        @{plan='발열 시 처방에 따라 해열제를 투여하고 서늘한 환경을 유지한다.';why='발열은 불감성 수분 손실을 늘리므로 체온을 조절하면 체액 손실이 줄어든다.'})
    edu = @(
        @{plan='대상자와 보호자에게 탈수 증상(갈증, 입 마름, 소변 감소, 어지러움)과 수분 섭취의 중요성을 교육한다.';why='탈수 징후를 조기에 알아차리면 빠르게 수분을 보충하여 심각한 체액 부족을 예방할 수 있다.'},
        @{plan='대상자에게 섭취량과 배설량을 기록하는 방법을 교육하고 참여하게 한다.';why='대상자가 직접 기록하면 정확한 I/O 측정이 가능하고 스스로 체액 관리에 관심을 갖게 된다.'})
}
$script:Templates['체액 불균형의 위험'] = @{
    en = 'Risk for imbalanced fluid volume'
    domain = '2. 영양 Nutrition'
    cls = '5. 수화 Hydration'
    page = $null
    problem = '체액 불균형 위험'
    priority = 2
    reason = '아직 나타나지 않은 위험 진단이지만 체액이 갑자기 부족하거나 과다해지면 혈압과 순환에 직접 영향을 주므로 순환 문제로 우선 다룬다'
    evalData = 'I/O와 체중 변화, V/S와 중심정맥압, 부종·탈수 징후, 폐 호흡음, 소변량, 전해질·BUN/Cr, 배액량'
    keywords = '대수술|major surgery|수술 후|post ?op|개복|laparotomy|수액 ?(대량|과다)|fluid therapy|CVP|중심정맥압|배액량|drain|복수 천자|paracentesis|투석|dialysis|화상|burn|패혈증|sepsis|췌장염|pancreatitis|장폐색|ileus|third spac|제3공간'
    cause = '대수술로 인한 체액 이동'
    long = '대상자는 퇴원 시까지 체액 균형을 유지할 것이다.'
    short = @('대상자는 3일 내 24시간 I/O 차이가 ±500mL 이내로 유지될 것이다.','대상자는 3일 내 혈압과 맥박이 평소 범위 안에서 유지될 것이다.')
    diag = @(
        @{plan='매 듀티마다 I/O(수액, 경구 섭취, 소변, 배액, 구토)를 정확히 측정하고 24시간 총량을 비교한다.';why='섭취와 배설의 균형을 비교하면 체액 부족이나 과다를 조기에 파악할 수 있다.'},
        @{plan='매일 같은 시간에 체중을 측정하고 부종과 탈수 징후(점막 건조, 피부 탄력)를 함께 사정한다.';why='체중과 신체 징후의 변화는 체액 이동의 방향과 정도를 보여준다.'},
        @{plan='매 4시간마다 V/S, 호흡음, 소변량을 확인하고 처방 시 중심정맥압과 전해질·BUN/Cr을 확인한다.';why='혈압 저하·빈맥·소변 감소는 체액 부족을, 수포음·혈압 상승은 체액 과다를 시사한다.'})
    ther = @(
        @{plan='처방에 따라 수액을 정확한 속도로 주입하고 주입 펌프를 사용한다.';why='정확한 주입 속도는 체액 부족과 과다를 모두 예방한다.'},
        @{plan='소변량이 시간당 0.5mL/kg 미만이거나 수포음, 호흡곤란이 나타나면 즉시 보고한다.';why='조기 보고는 쇼크나 폐부종으로 진행하기 전에 치료를 조정할 수 있게 한다.'},
        @{plan='배액관의 배액량과 양상을 기록하고 배액관이 막히지 않도록 관리한다.';why='배액은 체액 손실의 중요한 경로이므로 정확히 측정해야 보충량을 결정할 수 있다.'},
        @{plan='처방된 수분 섭취 계획(제한 또는 증가)을 대상자와 함께 하루 시간대별로 나누어 실천한다.';why='계획적인 수분 섭취는 급격한 체액 변동을 막는다.'})
    edu = @(
        @{plan='대상자와 보호자에게 I/O 측정의 목적과 기록 방법을 교육한다.';why='대상자와 보호자가 참여하면 측정이 정확해지고 체액 관리에 협조할 수 있다.'},
        @{plan='대상자에게 어지러움, 갈증, 숨참, 부종 증가가 있으면 즉시 알리도록 교육한다.';why='주관적 증상은 체액 불균형의 초기 신호로 조기 대처에 도움이 된다.'})
}
$script:Templates['전해질 불균형의 위험'] = @{
    en = 'Risk for electrolyte imbalance'
    domain = '2. 영양 Nutrition'
    cls = '5. 수화 Hydration'
    page = $null
    problem = '전해질 불균형 위험'
    priority = 2
    reason = '아직 나타나지 않은 위험 진단이지만 칼륨·나트륨 등의 이상은 부정맥과 의식 변화를 일으킬 수 있어 순환 문제로 우선 관리한다'
    evalData = '혈청 Na·K·Ca·Mg 수치 추이, 심전도 변화, 근력 저하·경련·저림, 의식 상태, I/O, 이뇨제 등 약물 투여 여부'
    keywords = '전해질|electrolyte|나트륨|sodium|Na\+?\s?\d|저나트륨|hyponatrem|고나트륨|칼륨|potassium|K\+?\s?\d|저칼륨|hypokal|고칼륨|hyperkal|칼슘|calcium|마그네슘|magnesium|이뇨제|라식스|lasix|furosemide|구토|설사|SIADH|신부전|투석|KCl|EKG 변화|부정맥'
    cause = '이뇨제 사용과 체액 손실'
    long = '대상자는 퇴원 시까지 혈청 전해질 수치가 정상 범위를 유지할 것이다.'
    short = @('대상자는 3일 내 혈청 칼륨이 3.5~5.0mEq/L, 나트륨이 135~145mEq/L 범위를 유지할 것이다.','대상자는 3일 내 전해질 이상 증상(근력 저하, 저림, 심계항진)을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='처방에 따라 혈청 전해질(Na, K, Ca, Mg) 결과를 확인하고 이전 결과와 비교한다.';why='전해질 수치의 변화 추이를 보면 이상을 조기에 발견하고 교정할 수 있다.'},
        @{plan='매 4시간마다 V/S와 맥박의 규칙성을 확인하고 필요 시 심전도를 확인한다.';why='칼륨과 칼슘, 마그네슘 이상은 부정맥을 일으킬 수 있어 심장 리듬 관찰이 중요하다.'},
        @{plan='근력 저하, 근경련, 저림, 의식 변화, 오심, 장음 감소를 관찰하고 I/O를 측정한다.';why='전해질 이상은 신경근육과 위장관 증상으로 먼저 나타나며, 체액 변화는 전해질 농도에 직접 영향을 준다.'})
    ther = @(
        @{plan='처방에 따라 전해질 보충제를 투여하고, 염화칼륨(KCl)은 반드시 희석하여 정해진 속도로 정맥 주입한다.';why='KCl을 희석하지 않거나 빠르게 주입하면 치명적인 부정맥과 심정지를 일으킬 수 있다.'},
        @{plan='칼륨 보충 전 소변량이 충분한지(시간당 30mL 이상) 확인한다.';why='신장으로 칼륨이 배설되지 않으면 보충 시 고칼륨혈증이 생길 수 있다.'},
        @{plan='이뇨제, 하제 등 전해질에 영향을 주는 약물 투여 시 투여 후 전해질 결과를 확인한다.';why='약물로 인한 전해질 변화를 조기에 확인하면 용량 조절이 가능하다.'},
        @{plan='처방된 식이(칼륨이 풍부한 음식 또는 제한식, 염분 조절)를 제공한다.';why='식이 조절은 전해질을 안정적으로 유지하는 데 도움이 된다.'})
    edu = @(
        @{plan='대상자에게 복용 약물(이뇨제 등)과 전해질 이상의 관계, 이상 증상(근력 저하, 저림, 심계항진)을 교육한다.';why='대상자가 증상을 알면 조기에 알려 심각한 합병증을 예방할 수 있다.'},
        @{plan='대상자와 보호자에게 처방에 맞는 식이(칼륨이 많은 음식 등)와 정기적인 혈액검사의 필요성을 교육한다.';why='퇴원 후에도 식이와 검사를 통해 전해질을 지속적으로 관리할 수 있다.'})
}
$script:Templates['배뇨 장애'] = @{
    en = 'Impaired urinary elimination'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '1. 비뇨기계 기능 Urinary function'
    page = $null
    problem = '배뇨 장애'
    priority = 4
    reason = '배뇨는 기본 생리적 배설 요구로 불편감과 감염을 유발하지만 즉각적인 생명 위협은 아니므로 ABC 이후에 다룬다'
    evalData = '배뇨 횟수·양·양상(배뇨일지), 배뇨 시 작열감·빈뇨·절박뇨 유무, 소변 색과 냄새, 요검사·소변배양 결과, 수분 섭취량'
    keywords = '배뇨 ?(곤란|장애|통|시 통증|시 따끔)|소변 ?(볼 때 따끔|자주|찔끔|탁|혈뇨)|빈뇨|frequency|dysuria|작열감|잔뇨감|야간뇨|nocturia|혈뇨|hematuria|요로감염|UTI|방광염|cystitis|소변 ?검사.{0,6}(WBC|nitrite)|nitrite|농뇨'
    cause = '요로감염'
    long = '대상자는 퇴원 시 불편감 없이 정상적인 배뇨 양상을 회복할 것이다.'
    short = @('대상자는 3일 내 배뇨 시 작열감과 빈뇨가 감소했다고 말할 것이다.','대상자는 3일 내 하루 수분 1,500~2,000mL 이상을 섭취할 것이다.')
    diag = @(
        @{plan='배뇨일지를 작성하여 배뇨 횟수, 양, 시간, 배뇨 시 불편감을 확인한다.';why='배뇨 양상을 기록하면 문제의 유형과 정도를 객관적으로 파악할 수 있다.'},
        @{plan='소변의 색, 혼탁도, 냄새, 혈뇨 여부를 관찰하고 요검사와 소변배양 결과를 확인한다.';why='소변의 변화와 검사 결과는 요로감염 등 배뇨 장애의 원인을 확인하는 근거가 된다.'},
        @{plan='하복부 팽만, 잔뇨감, 발열, 옆구리 통증 유무를 사정한다.';why='잔뇨와 발열, 옆구리 통증은 요정체나 상부 요로감염(신우신염)의 징후일 수 있다.'})
    ther = @(
        @{plan='금기가 아닐 시 하루 1,500~2,000mL 이상의 수분 섭취를 격려한다.';why='충분한 소변 생성은 방광을 씻어 내어 세균 증식을 줄인다.'},
        @{plan='처방에 따라 항생제를 정해진 시간에 투여하고 끝까지 복용하도록 한다.';why='정해진 기간 동안 투여해야 감염이 완전히 치료되고 재발과 내성이 줄어든다.'},
        @{plan='카페인, 알코올, 탄산음료 등 방광 자극 음료를 줄이도록 한다.';why='방광 자극 물질은 빈뇨와 절박뇨를 악화시킨다.'},
        @{plan='규칙적인 시간에 배뇨하도록 하고 화장실 이용이 쉬운 환경을 제공한다.';why='정기적인 배뇨는 방광 내 소변 정체를 줄이고 배뇨 조절을 돕는다.'})
    edu = @(
        @{plan='대상자에게 회음부를 앞에서 뒤로 닦는 방법과 소변을 오래 참지 않도록 교육한다.';why='올바른 회음부 위생과 규칙적인 배뇨는 요로감염의 재발을 예방한다.'},
        @{plan='대상자에게 발열, 옆구리 통증, 혈뇨가 나타나면 즉시 알리도록 교육한다.';why='이러한 증상은 감염이 상부 요로로 퍼졌다는 신호로 빠른 치료가 필요하다.'})
}
$script:Templates['요정체'] = @{
    en = 'Urinary retention'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '1. 비뇨기계 기능 Urinary function'
    page = $null
    problem = '요정체'
    priority = 4
    reason = '방광에 소변이 차서 배출되지 않으면 통증과 방광 손상, 요로감염, 신장 손상을 유발하는 생리적 배설 문제이므로 ABC 이후 우선적으로 다룬다'
    evalData = '자연 배뇨 여부와 배뇨량, 방광 초음파(bladder scan) 잔뇨량, 치골상부 팽만·불편감, I/O, 도뇨 시행 횟수와 양'
    keywords = '요정체|urinary retention|소변이? (안|잘 안) ?나|소변을? (못|안) ?(봄|보|봤)|배뇨 ?(못|곤란)|방광 ?(팽만|팽창)|잔뇨|PVR|residual urine|bladder scan|방광 ?스캔|단순 ?도뇨|인공 ?도뇨|self ?cath|전립선 ?비대|BPH|척추마취|spinal anesthesia|자가도뇨'
    cause = '척추마취 후 방광 감각 저하'
    long = '대상자는 퇴원 시 잔뇨 없이 스스로 배뇨할 것이다.'
    short = @('대상자는 수술 후 6~8시간 내 자연 배뇨를 할 것이다.','대상자는 3일 내 배뇨 후 잔뇨량이 100mL 미만으로 유지될 것이다.')
    diag = @(
        @{plan='마지막 배뇨 시간과 배뇨량을 확인하고 I/O를 측정한다.';why='섭취량에 비해 배뇨가 없거나 적으면 요정체를 의심할 수 있다.'},
        @{plan='치골상부를 촉진·타진하여 방광 팽만과 불편감을 사정한다.';why='방광이 팽창하면 치골 위로 둥글게 만져지고 타진 시 둔탁음이 들린다.'},
        @{plan='방광 초음파(bladder scan)로 배뇨 전후 방광 용적과 잔뇨량을 측정한다.';why='잔뇨량을 객관적으로 측정하면 도뇨 필요성을 판단하고 불필요한 도뇨를 줄일 수 있다.'})
    ther = @(
        @{plan='금기가 아닐 시 앉거나 선 자세 등 평소 배뇨 자세를 취하게 하고 사생활을 보장한다.';why='익숙한 자세와 편안한 환경은 회음부 근육의 이완을 도와 배뇨를 촉진한다.'},
        @{plan='물 흐르는 소리 들려주기, 회음부에 따뜻한 물 붓기 등으로 배뇨 반사를 자극한다.';why='감각 자극은 배뇨 반사를 촉진하여 자연 배뇨를 돕는다.'},
        @{plan='자연 배뇨가 되지 않거나 방광 용적이 기준(보통 400~500mL) 이상이면 처방에 따라 무균적으로 단순 도뇨를 시행한다.';why='방광 과팽창은 배뇨근 손상과 감염을 일으키므로 적절한 시기에 소변을 배출해야 한다.'},
        @{plan='방광 내 소변이 많을 때 병원 지침에 따라 천천히 배출하며 V/S를 관찰한다.';why='다량의 소변을 빠르게 배출하면 혈압 저하나 방광 출혈이 생길 수 있다.'},
        @{plan='처방에 따라 요정체를 유발하는 약물(항콜린제, 마약성 진통제)을 확인하고 필요 시 의료진과 상의한다.';why='일부 약물은 배뇨근 수축을 억제하여 요정체를 악화시킨다.'})
    edu = @(
        @{plan='대상자에게 소변이 마려운 느낌이 들면 참지 말고 바로 알리도록 교육한다.';why='조기에 알리면 방광이 과팽창하기 전에 배뇨를 도울 수 있다.'},
        @{plan='자가도뇨가 필요한 대상자와 보호자에게 청결 간헐적 자가도뇨 방법과 요로감염 증상을 시범과 함께 교육한다.';why='올바른 자가도뇨는 가정에서 잔뇨를 줄이고 감염을 예방한다.'})
}
$script:Templates['복압성 요실금'] = @{
    en = 'Stress urinary incontinence'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '1. 비뇨기계 기능 Urinary function'
    page = $null
    problem = '복압성 요실금'
    priority = 4
    reason = '복압성 요실금은 배설 기능의 문제로 피부 손상과 사회적 위축을 일으키지만 생명 위협은 아니므로 ABC 이후 기본 생리적 요구로 다룬다'
    evalData = '요실금 횟수와 상황(배뇨일지), 패드 사용 개수, 골반저근 운동 수행 여부와 방법, 회음부 피부 상태, 삶의 질 관련 표현'
    keywords = '복압성|stress (urinary )?incontinence|SUI|기침할 때 (소변|찔끔)|재채기할 때 (소변|샌)|웃을 때 (소변|샌)|뛸 때 (소변|샌)|무거운 것을? 들 때|소변이 (샌|새)|찔끔|요실금|패드|골반저근|케겔|kegel|다산|질식분만|폐경'
    cause = '골반저근 약화'
    long = '대상자는 퇴원 시 골반저근 운동을 스스로 실천하고 요실금 횟수가 감소할 것이다.'
    short = @('대상자는 2일 내 골반저근 운동 방법을 정확히 시범 보일 것이다.','대상자는 1주일 내 하루 3회, 1회 10번 이상 골반저근 운동을 실천할 것이다.')
    diag = @(
        @{plan='배뇨일지를 작성하여 요실금 횟수, 양, 발생 상황(기침, 재채기, 운동)을 확인한다.';why='요실금이 생기는 상황을 알면 유형을 확인하고 중재 효과를 평가할 수 있다.'},
        @{plan='출산력, 폐경 여부, 비만, 만성 기침, 변비 등 복압을 높이거나 골반저근을 약하게 하는 요인을 사정한다.';why='위험 요인을 파악하여 줄이면 요실금을 개선할 수 있다.'},
        @{plan='회음부 피부 상태(발적, 짓무름)와 요실금이 일상생활과 정서에 미치는 영향을 사정한다.';why='소변에 의한 피부 손상과 수치심, 사회적 위축은 함께 관리해야 할 문제다.'})
    ther = @(
        @{plan='골반저근 운동(케겔 운동)을 정확한 방법으로 하도록 지도한다.';why='골반저근을 강화하면 요도 지지력이 높아져 복압 상승 시 소변 누출이 줄어든다.'},
        @{plan='기침이나 재채기 전 골반저근을 미리 조이도록(knack) 한다.';why='복압이 오르기 직전에 근육을 수축하면 요도가 닫혀 소변 누출을 막는다.'},
        @{plan='금기가 아닐 시 체중 조절, 변비 예방, 금연을 격려한다.';why='비만, 변비, 만성 기침은 복압을 반복적으로 높여 요실금을 악화시킨다.'},
        @{plan='흡수 패드를 적절히 사용하고 젖으면 바로 교환하며 회음부를 깨끗하고 건조하게 유지한다.';why='젖은 상태가 지속되면 피부염과 감염 위험이 높아진다.'},
        @{plan='대상자의 수치심과 걱정을 공감하며 표현하도록 격려한다.';why='정서적 지지는 수치심을 줄이고 치료에 적극적으로 참여하게 한다.'})
    edu = @(
        @{plan='대상자에게 골반저근 운동을 꾸준히 해야 효과가 나타남(보통 수주~수개월)을 교육한다.';why='효과가 나타나는 데 시간이 걸린다는 것을 알면 중도에 포기하지 않고 지속할 수 있다.'},
        @{plan='대상자에게 지나친 수분 제한은 하지 말고 카페인과 알코올을 줄이도록 교육한다.';why='수분을 너무 줄이면 소변이 농축되어 방광을 자극하고 요로감염 위험이 높아진다.'})
}
$script:Templates['절박성 요실금'] = @{
    en = 'Urge urinary incontinence'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '1. 비뇨기계 기능 Urinary function'
    page = $null
    problem = '절박성 요실금'
    priority = 4
    reason = '절박성 요실금은 배설 기능의 문제로 낙상과 피부 손상, 사회적 위축을 일으키지만 생명 위협은 아니므로 ABC 이후 기본 생리적 요구로 다룬다'
    evalData = '배뇨 간격과 요실금 횟수(배뇨일지), 절박감 정도, 야간뇨 횟수, 방광 훈련 수행 여부, 회음부 피부 상태, 화장실 이동 중 낙상 여부'
    keywords = '절박성|절박뇨|urge|urgency|OAB|과민성 방광|overactive bladder|갑자기 소변이 (마렵|급)|화장실에 가기 전에 (샌|새|나와)|참지 못하고|빈뇨|야간뇨|nocturia|요실금|베시케어|vesicare|solifenacin|베타미가|mirabegron|옥시부티닌|oxybutynin'
    cause = '배뇨근 과활동'
    long = '대상자는 퇴원 시 배뇨 간격이 늘어나고 요실금 횟수가 감소할 것이다.'
    short = @('대상자는 3일 내 정해진 시간 간격(2시간)에 맞추어 배뇨할 것이다.','대상자는 1주일 내 절박감을 조절하는 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='배뇨일지를 작성하여 배뇨 간격, 배뇨량, 요실금 횟수, 절박감 발생 상황을 확인한다.';why='배뇨 양상을 알아야 방광 훈련의 시작 간격을 정하고 효과를 평가할 수 있다.'},
        @{plan='요로감염 증상과 요검사 결과, 방광 자극 음식·음료 섭취, 복용 약물(이뇨제 등)을 확인한다.';why='요로감염과 방광 자극 물질, 이뇨제는 절박감을 악화시키는 교정 가능한 원인이다.'},
        @{plan='화장실까지의 거리, 이동 능력, 낙상 위험도(Morse Fall Scale)와 회음부 피부 상태를 사정한다.';why='급하게 화장실로 이동하다 낙상하기 쉬우며, 요실금으로 피부 손상이 생길 수 있다.'})
    ther = @(
        @{plan='배뇨일지를 바탕으로 방광 훈련을 시행하여 정해진 시간에 배뇨하고 배뇨 간격을 점차 15~30분씩 늘린다.';why='계획적으로 배뇨 간격을 늘리면 방광 용적이 커지고 배뇨근 과활동이 줄어든다.'},
        @{plan='절박감이 생기면 바로 뛰어가지 말고 멈춰 서서 골반저근을 빠르게 여러 번 조이고 심호흡하도록 한다.';why='골반저근 수축은 배뇨근 수축을 반사적으로 억제하여 절박감을 가라앉힌다.'},
        @{plan='처방에 따라 방광 진정제(항무스카린제, 베타3 작용제)를 투여하고 입 마름, 변비, 요정체, 인지 변화를 관찰한다.';why='약물은 배뇨근 과활동을 줄이지만 항무스카린제는 노인에서 부작용이 흔해 관찰이 필요하다.'},
        @{plan='화장실과 가까운 침상을 배정하고 야간 조명, 이동식 변기, 호출벨을 가까이 둔다.';why='화장실 접근성을 높이면 요실금과 급한 이동으로 인한 낙상을 줄일 수 있다.'},
        @{plan='카페인, 알코올, 탄산음료를 줄이고 취침 2~3시간 전 수분 섭취를 줄이도록 한다.';why='방광 자극 물질과 취침 전 수분은 절박감과 야간뇨를 늘린다.'})
    edu = @(
        @{plan='대상자에게 방광 훈련과 절박감 억제 방법을 교육하고 가정에서 배뇨일지를 계속 쓰도록 한다.';why='스스로 방광 훈련을 지속하면 퇴원 후에도 증상이 개선된다.'},
        @{plan='대상자와 보호자에게 가정 내 화장실 동선 정리, 야간 조명 등 낙상 예방 방법을 교육한다.';why='절박감으로 급히 이동할 때 생기는 낙상을 예방할 수 있다.'})
}
$script:Templates['변비'] = @{
    en = 'Constipation'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '2. 위장계 기능 Gastrointestinal function'
    page = $null
    problem = '변비'
    priority = 4
    reason = '배변은 기본 생리적 배설 요구로 복부 불편감과 식욕 저하를 일으키지만 즉각적인 생명 위협은 아니므로 ABC 이후에 다룬다'
    evalData = '배변 횟수·양·굳기(브리스톨 대변 척도), 마지막 배변일, 복부 팽만과 장음, 수분·섬유질 섭취량, 활동량, 하제 사용 후 반응'
    keywords = '변비|constipation|배변.{0,4}(없|못|힘|안)|대변.{0,4}(없|못|힘|안)|딱딱한 변|hard stool|복부 ?팽만|장음 ?(감소|저하)|bowel sound ?(decreas|hypo)|가스가 (안|차)|둘코락스|dulcolax|마그밀|magmil|듀파락|duphalac|락툴로오스|lactulose|관장|enema|아락실|브리스톨'
    cause = '활동 감소와 섬유질 섭취 부족'
    long = '대상자는 퇴원 시 규칙적이고 편안한 배변 양상을 회복할 것이다.'
    short = @('대상자는 3일 내 부드러운 변을 1회 이상 볼 것이다.','대상자는 3일 내 변비 예방 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매일 배변 횟수, 양, 굳기(브리스톨 대변 척도), 배변 시 힘주기 정도를 사정한다.';why='배변 양상을 기록하면 변비의 정도와 중재 효과를 객관적으로 평가할 수 있다.'},
        @{plan='매 듀티마다 복부 팽만, 장음, 압통을 사정한다.';why='장음 감소와 복부 팽만은 장운동 저하를 의미하며, 심한 통증과 구토가 동반되면 장폐색을 의심해야 한다.'},
        @{plan='수분·섬유질 섭취량, 활동량, 변비를 유발하는 약물(마약성 진통제, 철분제, 항콜린제) 사용을 확인한다.';why='변비의 원인을 알아야 교정 가능한 요인을 찾아 중재할 수 있다.'})
    ther = @(
        @{plan='금기가 아닐 시 하루 1,500~2,000mL 이상의 수분과 섬유질이 풍부한 음식(채소, 과일, 잡곡) 섭취를 격려한다.';why='수분과 섬유질은 대변의 부피를 늘리고 부드럽게 하여 장운동을 촉진한다.'},
        @{plan='금기가 아닐 시 침상 밖 활동과 보행을 격려한다.';why='신체 활동은 장의 연동 운동을 자극한다.'},
        @{plan='시계 방향으로 복부 마사지를 시행한다.';why='대장의 주행 방향을 따라 마사지하면 장 내용물의 이동을 돕는다.'},
        @{plan='식후 30분 등 일정한 시간에 화장실에 가도록 하고 사생활을 보장한다.';why='식후에는 위대장 반사로 장운동이 활발해지며, 편안한 환경은 배변을 돕는다.'},
        @{plan='처방에 따라 완하제나 관장을 시행하고 배변 여부와 복부 불편감, 전해질 이상을 확인한다.';why='약물은 장운동을 촉진하거나 변을 부드럽게 하지만 과다 사용 시 설사와 전해질 불균형이 생길 수 있다.'})
    edu = @(
        @{plan='대상자에게 변비 예방을 위한 수분·섬유질 섭취, 규칙적인 운동과 배변 습관을 교육한다.';why='생활 습관을 개선하면 퇴원 후에도 변비 재발을 예방할 수 있다.'},
        @{plan='대상자에게 변의를 참지 말고 완하제를 임의로 장기간 사용하지 않도록 교육한다.';why='변의를 참으면 직장 감각이 둔해지고, 완하제를 오래 쓰면 장이 약물에 의존하게 된다.'})
}
$script:Templates['변비의 위험'] = @{
    en = 'Risk for constipation'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '2. 위장계 기능 Gastrointestinal function'
    page = $null
    problem = '변비 위험'
    priority = 5
    reason = '아직 변비가 나타나지 않은 위험 진단이므로 실제적 문제보다 우선순위가 낮지만, 예방하지 않으면 배설 장애와 불편감으로 이어질 수 있다'
    evalData = '배변 횟수와 양상(브리스톨 대변 척도), 복부 팽만·장음, 하루 수분·섬유질 섭취량, 활동량, 변비 예방 방법 설명 여부'
    keywords = '변비|배변 ?곤란|딱딱한 ?변|대변 ?안|며칠째 ?대변|constipation|마약성|opioid|옥시코돈|oxycodone|코데인|codeine|철분제|ferrous|침상 ?안정|bed ?rest|부동|활동 ?감소|수분 ?섭취 ?감소|금식|\bNPO\b'
    cause = '활동 감소와 마약성 진통제 사용'
    long = '대상자는 퇴원 시까지 변비 없이 규칙적인 배변 양상을 유지할 것이다.'
    short = @('대상자는 3일 내 최소 1회 이상 부드러운 변을 볼 것이다.','대상자는 2일 내 변비 예방 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매일 배변 횟수, 양, 굳기(브리스톨 대변 척도), 배변 시 힘주기 여부를 사정한다.';why='평소 배변 양상과 비교하여 변화를 확인하면 변비를 조기에 발견할 수 있다.'},
        @{plan='매 듀티마다 복부 팽만, 장음, 복부 불편감을 사정한다.';why='장음 감소와 복부 팽만은 장운동 저하를 나타내는 객관적 지표가 된다.'},
        @{plan='변비를 유발할 수 있는 약물(마약성 진통제, 철분제, 항콜린제 등)과 하루 수분·섬유질 섭취량을 확인한다.';why='약물과 식이는 변비의 주요 위험 요인이므로 이를 파악해야 예방 중재를 계획할 수 있다.'})
    ther = @(
        @{plan='금기가 아닐 시 하루 1,500~2,000mL 이상 수분 섭취를 격려한다.';why='충분한 수분은 대변의 수분 함량을 유지하여 변을 부드럽게 한다.'},
        @{plan='섬유질이 풍부한 음식(채소, 과일, 잡곡)을 섭취하도록 격려한다.';why='섬유질은 대변의 부피를 늘리고 장 연동운동을 자극한다.'},
        @{plan='상태가 허락하는 범위에서 조기 이상과 걷기를 격려한다.';why='신체 활동은 장의 연동운동을 촉진하여 배변을 돕는다.'},
        @{plan='일정한 시간(특히 식후)에 배변을 시도하고 사생활이 보장되는 환경을 제공한다.';why='식후에는 위대장 반사가 일어나 배변이 쉬우며, 사생활 보장은 배변 반사 억제를 줄인다.'},
        @{plan='처방에 따라 완하제나 대변 연화제를 투여하고 배변 양상과 복부 경련·설사 여부를 확인한다.';why='마약성 진통제 사용 시 예방적 완하제는 변비 발생을 줄이며, 과다 투여 시 설사와 전해질 불균형이 생길 수 있다.'})
    edu = @(
        @{plan='대상자와 보호자에게 수분·섬유질 섭취와 활동의 중요성을 교육한다.';why='변비 예방 원리를 이해하면 대상자가 스스로 생활습관을 조절할 수 있다.'},
        @{plan='변의를 느끼면 참지 말고 3일 이상 배변이 없으면 알리도록 교육한다.';why='변의를 반복해서 참으면 직장 감각이 둔해져 변비가 생기며, 조기 보고로 빠르게 중재할 수 있다.'})
}
$script:Templates['설사'] = @{
    en = 'Diarrhea'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '2. 위장계 기능 Gastrointestinal function'
    page = $null
    problem = '설사'
    priority = 2
    reason = '잦은 묽은 변으로 수분과 전해질이 빠르게 손실되어 탈수와 순환 문제로 이어질 수 있으므로 우선 해결이 필요하다'
    evalData = '하루 배변 횟수와 양상, I/O, 피부 탄력·점막 건조, 혈청 전해질(Na, K), 체중, 항문 주위 피부 상태'
    keywords = '설사|묽은 ?변|물 ?같은 ?변|수양성 ?변|watery|diarrhea|loose stool|하루 ?\d+ ?회 ?(변|배변)|장염|enteritis|gastroenteritis|C\.? ?diff|클로스트리디|노로|rotavirus|로타|경관 ?영양|tube feeding'
    cause = '장 감염'
    long = '대상자는 퇴원 시 정상적인 배변 양상을 회복할 것이다.'
    short = @('대상자는 2일 내 하루 배변 횟수가 3회 이하로 감소할 것이다.','대상자는 3일 내 혈청 칼륨이 정상 범위(3.5~5.0mEq/L)를 유지할 것이다.')
    diag = @(
        @{plan='매 배변 시 횟수, 양, 굳기, 색, 혈액·점액 동반 여부를 기록한다.';why='설사의 양상과 변화를 객관적으로 기록하면 원인 추정과 중재 효과 평가에 도움이 된다.'},
        @{plan='매 듀티마다 I/O와 탈수 징후(피부 탄력 저하, 점막 건조, 소변량 감소, 빈맥, 기립성 저혈압)를 사정한다.';why='설사로 인한 체액 손실은 탈수와 저혈량으로 진행할 수 있어 조기 발견이 중요하다.'},
        @{plan='혈청 전해질(Na, K)과 대변 검사(대변 배양, C. difficile 독소) 결과를 확인한다.';why='설사 시 칼륨과 나트륨이 손실되어 부정맥과 근력 저하가 올 수 있으며, 감염성 원인을 확인해야 적절한 치료와 격리가 가능하다.'})
    ther = @(
        @{plan='처방에 따라 경구 수분 전해질 용액이나 수액을 공급한다.';why='손실된 수분과 전해질을 보충하여 탈수와 전해질 불균형을 예방한다.'},
        @{plan='설사가 줄 때까지 기름지고 자극적인 음식, 카페인, 유제품을 제한하고 소화가 쉬운 음식을 소량씩 제공한다.';why='자극적인 음식과 유당은 장운동과 삼투압을 증가시켜 설사를 악화시킬 수 있다.'},
        @{plan='배변 후 항문 주위를 미온수로 부드럽게 씻고 말린 뒤 피부 보호제를 바른다.';why='설사 변의 소화효소와 잦은 닦기는 항문 주위 피부를 손상시키므로 피부 보호가 필요하다.'},
        @{plan='감염성 설사가 의심되면 접촉주의 격리를 시행하고 비누와 물로 손 위생을 한다.';why='C. difficile 포자는 알코올 손소독제로 제거되지 않으므로 비누와 물로 씻어야 교차 감염을 막는다.'},
        @{plan='처방에 따라 지사제나 정장제를 투여하고 복부 팽만과 장음 변화를 관찰한다.';why='감염성 설사에서 지사제는 병원체 배출을 늦출 수 있으므로 처방에 따라서만 사용하고 장 마비 징후를 살핀다.'})
    edu = @(
        @{plan='대상자와 보호자에게 탈수 징후와 수분 보충 방법을 교육한다.';why='탈수 징후를 알면 조기에 수분을 보충하고 의료진에게 알릴 수 있다.'},
        @{plan='배변 후와 식사 전 비누로 손 씻기와 개인 위생용품 분리 사용을 교육한다.';why='손 위생은 감염성 설사의 가족 내 전파를 막는 가장 효과적인 방법이다.'})
}
$script:Templates['위장관 운동기능 장애'] = @{
    en = 'Dysfunctional gastrointestinal motility'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '2. 위장계 기능 Gastrointestinal function'
    page = $null
    problem = '위장관 운동 장애'
    priority = 4
    reason = '장운동의 증가 또는 감소로 소화·흡수와 배설 기능이 방해받는 생리적 문제로, 순환이나 호흡 문제보다는 후순위이다'
    evalData = '장음(빈도·양상), 복부 둘레와 팽만, 오심·구토, 가스·배변 배출 여부, 비위관 배액량, 식이 섭취 상태'
    keywords = '장음 ?(감소|저하|소실|항진)|bowel sound|장마비|마비성 ?장폐색|ileus|복부 ?팽만|abdominal distension|위 ?배출 ?지연|gastroparesis|위마비|비위관|L-?tube|Levin|NG ?tube|가스 ?배출 ?(없|안)|방귀|flatus|덤핑|dumping'
    cause = '복부 수술 후 장운동 저하'
    long = '대상자는 퇴원 시 정상적인 장운동을 회복하여 식이를 섭취할 수 있을 것이다.'
    short = @('대상자는 2일 내 장음이 분당 5~30회로 회복될 것이다.','대상자는 3일 내 가스 배출 또는 배변이 있을 것이다.')
    diag = @(
        @{plan='매 4시간마다 네 부위 복부 청진으로 장음의 빈도와 양상을 사정한다.';why='장음은 장운동 상태를 직접 반영하며, 장음의 소실이나 항진은 장마비나 폐색의 지표가 된다.'},
        @{plan='매 듀티마다 복부 팽만, 복부 둘레, 오심·구토, 복통 양상을 사정한다.';why='복부 둘레 증가와 구토는 장 내용물과 가스의 정체를 나타내어 장운동 회복 정도를 평가할 수 있다.'},
        @{plan='가스 배출과 배변 여부, 비위관 배액의 양과 색을 기록한다.';why='가스 배출은 장운동 회복의 대표적 지표이며, 배액량 감소는 위장관 통과가 회복되고 있음을 의미한다.'})
    ther = @(
        @{plan='처방에 따라 금식을 유지하고 비위관을 저압 간헐적 흡인으로 관리하며 개방성을 확인한다.';why='장운동이 회복될 때까지 위장관 내 압력을 낮춰 구토와 흡인을 예방하고 문합부 긴장을 줄인다.'},
        @{plan='금기가 아닐 시 조기 이상과 걷기를 격려한다.';why='신체 활동은 장의 연동운동을 자극하여 장마비 회복을 앞당긴다.'},
        @{plan='장음과 가스 배출이 확인되면 처방에 따라 물부터 유동식, 연식 순으로 식이를 진행한다.';why='단계적 식이 진행은 위장관의 부담을 줄이고 오심·팽만 재발을 예방한다.'},
        @{plan='처방에 따라 위장관 운동 촉진제(메토클로프라마이드 등)를 투여하고 추체외로 증상을 관찰한다.';why='운동 촉진제는 위 배출과 장운동을 증가시키지만 근육 경직, 떨림 같은 부작용이 생길 수 있다.'},
        @{plan='마약성 진통제 사용을 최소화할 수 있도록 처방에 따라 비마약성 진통제를 병용한다.';why='마약성 진통제는 장 운동을 억제하여 장마비를 지연시키므로 사용량을 줄이는 것이 도움이 된다.'})
    edu = @(
        @{plan='대상자에게 가스 배출이나 배변이 있으면 알리고 복부 팽만·구토가 생기면 즉시 알리도록 교육한다.';why='장운동 회복이나 악화 징후를 빠르게 확인하여 식이 진행과 치료를 조정할 수 있다.'},
        @{plan='식이 재개 후 소량씩 천천히 먹고 가스를 만드는 음식(탄산음료, 콩류)을 피하도록 교육한다.';why='소량 섭취와 가스 유발 음식 제한은 복부 팽만과 불편감을 줄인다.'})
}
$script:Templates['가스교환 장애'] = @{
    en = 'Impaired gas exchange'
    domain = '3. 배설/교환 Elimination/Exchange'
    cls = '4. 호흡기계 기능 Respiratory function'
    page = $null
    problem = '가스교환 장애'
    priority = 1
    reason = '폐포에서 산소와 이산화탄소 교환이 원활하지 않아 저산소증이 생길 수 있는 ABC 중 호흡 문제이므로 최우선이다'
    evalData = 'SpO2, ABGA(PaO2, PaCO2, pH), 호흡수·호흡 양상, 의식 수준, 청색증 여부, 산소 요구량 변화'
    keywords = 'SpO2 ?[:=]? ?[0-8]\d ?%|산소포화도 ?(저하|감소)|저산소|hypoxemia|hypoxia|PaO2|PaCO2|ABGA|ABG|고탄산|hypercapnia|청색증|cyanosis|COPD|만성 ?폐쇄성|폐렴|pneumonia|ARDS|폐부종|pulmonary edema|폐색전|pulmonary embolism|비강 ?캐뉼라|nasal cannula|O2 ?\d+ ?L|산소 ?\d+ ?L|venturi|벤츄리'
    cause = '폐포-모세혈관막의 변화'
    long = '대상자는 퇴원 시 실내 공기에서 정상 범위의 산소포화도를 유지할 것이다.'
    short = @('대상자는 2일 내 SpO2를 95% 이상(COPD 대상자는 88~92%) 유지할 것이다.','대상자는 3일 내 ABGA 결과가 정상 범위(PaO2 80~100mmHg, PaCO2 35~45mmHg, pH 7.35~7.45)로 회복될 것이다.')
    diag = @(
        @{plan='매 1~4시간마다 SpO2, 호흡수, 호흡 깊이와 양상, 보조근 사용 여부를 사정한다.';why='호흡 상태와 산소포화도의 변화는 가스교환 악화를 조기에 알려주는 지표이다.'},
        @{plan='처방에 따라 ABGA 결과를 확인하고 PaO2, PaCO2, pH의 변화를 비교한다.';why='ABGA는 산소화와 환기 상태, 산-염기 균형을 객관적으로 평가하는 검사이다.'},
        @{plan='의식 수준, 불안·안절부절, 청색증, 빈맥 같은 저산소증 징후를 관찰한다.';why='뇌는 저산소에 민감하여 의식 변화와 안절부절이 초기 징후로 나타나며, 청색증은 늦게 나타나는 징후이다.'})
    ther = @(
        @{plan='처방에 따라 산소를 투여하고 목표 SpO2에 맞게 유량을 조절한다.';why='적절한 산소 공급은 저산소증을 교정하며, 만성 고탄산혈증 대상자는 과다 산소로 호흡 동기가 저하될 수 있어 목표 범위를 지킨다.'},
        @{plan='금기가 아닐 시 반좌위(High Fowler''s) 또는 앞으로 기댄 자세를 취하게 한다.';why='상체를 올리면 횡격막이 내려가 폐 확장이 쉬워지고 환기가 증가한다.'},
        @{plan='심호흡, 기침, 입술 오므리기 호흡을 격려하고 필요 시 분비물을 흡인한다.';why='분비물 제거와 효과적인 호흡은 폐포 환기를 개선하고, 입술 오므리기 호흡은 기도 허탈을 막아 이산화탄소 배출을 돕는다.'},
        @{plan='처방에 따라 기관지 확장제, 이뇨제, 항생제 등을 투여하고 효과와 부작용을 관찰한다.';why='원인 질환을 치료해야 가스교환이 개선되며, 기관지 확장제는 빈맥·떨림을 유발할 수 있어 관찰이 필요하다.'},
        @{plan='활동과 휴식을 조절하고 처치를 묶어서 시행하여 산소 소모를 줄인다.';why='불필요한 활동을 줄이면 산소 요구량이 감소하여 호흡 부담이 줄어든다.'})
    edu = @(
        @{plan='대상자에게 입술 오므리기 호흡과 복식호흡 방법을 교육한다.';why='스스로 효과적인 호흡법을 사용하면 호흡곤란을 조절하고 환기를 개선할 수 있다.'},
        @{plan='대상자와 보호자에게 산소 기구를 임의로 조절하지 않고 화기를 가까이하지 않도록 교육한다.';why='산소는 연소를 돕기 때문에 화재 위험이 있고, 임의로 유량을 바꾸면 저산소증이나 고탄산혈증이 생길 수 있다.'})
}
$script:Templates['신체 기동성 장애'] = @{
    en = 'Impaired physical mobility'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '2. 활동/운동 Activity/Exercise'
    page = $null
    problem = '신체 기동성 장애'
    priority = 4
    reason = '움직임의 제한으로 일상생활과 합병증 예방에 영향을 주는 기본 생리 욕구 문제로, 호흡·순환 문제보다는 후순위이다'
    evalData = '근력(MMT 등급), 관절가동범위, 보행·이동 시 필요한 도움 정도, 보조기구 사용 능력, 피부 상태, 활동 참여 정도'
    keywords = '편마비|hemiplegia|하지 ?마비|paraplegia|사지 ?마비|quadriplegia|근력 ?(저하|약화)|MMT|ROM ?제한|관절가동범위|골절|fracture|고관절|\bhip\b|슬관절 ?치환|TKR|TKA|THR|뇌졸중|stroke|CVA|파킨슨|parkinson|깁스|cast|견인|traction|움직이기 ?(힘들|어렵)'
    cause = '근력 저하와 신경근 손상'
    long = '대상자는 퇴원 시 보조기구를 이용하여 스스로 원하는 곳으로 이동할 수 있을 것이다.'
    short = @('대상자는 1주일 내 환측 하지의 근력이 한 등급 이상 향상될 것이다.','대상자는 3일 내 보조기구를 사용하여 병실 안에서 10m 이상 걸을 것이다.')
    diag = @(
        @{plan='매일 근력(MMT), 관절가동범위, 움직임의 제한 정도를 사정한다.';why='근력과 관절 기능을 반복 평가해야 기동성의 변화와 재활 효과를 객관적으로 확인할 수 있다.'},
        @{plan='활동 시 통증, 피로, 어지러움, 활력징후 변화를 관찰한다.';why='활동을 방해하는 요인과 활동에 대한 신체 반응을 파악해야 안전한 활동 수준을 정할 수 있다.'},
        @{plan='부동으로 인한 합병증(피부 발적, 하지 부종·통증, 관절 경축, 호흡음 감소)을 사정한다.';why='움직임이 줄면 욕창, 심부정맥혈전증, 경축, 무기폐가 생길 수 있어 조기 발견이 필요하다.'})
    ther = @(
        @{plan='금기가 아닐 시 하루 2~3회 능동적 또는 수동적 관절범위운동을 시행한다.';why='관절범위운동은 관절 경축과 근위축을 예방하고 혈액순환을 돕는다.'},
        @{plan='물리치료사와 협력하여 침상 → 앉기 → 서기 → 걷기 순으로 단계적으로 활동을 늘린다.';why='단계적 활동 증가는 기립성 저혈압과 낙상을 줄이면서 근력과 지구력을 회복시킨다.'},
        @{plan='보조기구(보행기, 지팡이, 휠체어)를 대상자 상태에 맞게 준비하고 사용을 돕는다.';why='적절한 보조기구는 체중 부하를 분산시켜 안전하게 움직일 수 있게 한다.'},
        @{plan='최소 2시간마다 체위를 변경하고 신체 선열을 유지한다.';why='체위 변경과 바른 자세는 압력을 분산시켜 욕창과 기형을 예방한다.'},
        @{plan='처방에 따라 활동 30분 전 진통제를 투여한다.';why='통증을 미리 조절하면 활동 참여가 늘어나 재활 효과가 높아진다.'})
    edu = @(
        @{plan='대상자와 보호자에게 보조기구 사용법과 안전한 이동 방법을 교육한다.';why='올바른 사용법을 알면 퇴원 후에도 낙상 없이 스스로 이동할 수 있다.'},
        @{plan='대상자에게 침상에서 할 수 있는 근력 강화 운동(발목 펌프 운동, 대퇴사두근 운동)을 교육한다.';why='스스로 운동을 반복하면 근력이 유지되고 정맥혈 정체를 예방할 수 있다.'})
}
$script:Templates['침상 기동성 장애'] = @{
    en = 'Impaired bed mobility'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '2. 활동/운동 Activity/Exercise'
    page = $null
    problem = '침상 기동성 장애'
    priority = 4
    reason = '침상에서 스스로 자세를 바꾸지 못해 피부 손상과 합병증으로 이어질 수 있는 기본 생리 욕구 문제로, 호흡·순환 문제보다는 후순위이다'
    evalData = '침상 내 돌아눕기·앉기·위로 올라가기 수행 정도와 필요한 도움 정도, 근력, 피부 발적 여부, 체위 변경 빈도'
    keywords = '돌아눕(기|지 ?못)|체위 ?변경 ?(못|어렵)|스스로 ?(못 ?움직|돌아눕)|침상 ?(안정|생활)|bed ?ridden|와상|bedridden|침상에서 ?(못|움직)|사지 ?마비|quadriplegia|척수 ?손상|spinal cord injury|\bSCI\b|\bALS\b|루게릭'
    cause = '근력 저하와 신경근 손상'
    long = '대상자는 퇴원 시 최소한의 도움으로 침상에서 자세를 바꿀 수 있을 것이다.'
    short = @('대상자는 3일 내 침대 난간을 잡고 스스로 옆으로 돌아누울 것이다.','대상자는 1주일 내 도움을 받아 누운 자세에서 침상 가장자리에 앉을 것이다.')
    diag = @(
        @{plan='매일 침상 내 움직임(돌아눕기, 위로 올라가기, 앉기)의 수행 정도와 필요한 도움을 사정한다.';why='어떤 동작에 얼마나 도움이 필요한지 알아야 맞춤 중재와 진척 평가가 가능하다.'},
        @{plan='상지와 몸통의 근력, 통증, 의식 수준을 사정한다.';why='침상 내 움직임은 상지와 몸통 근력에 의존하며, 통증과 의식 저하는 움직임을 제한하는 요인이다.'},
        @{plan='매 체위 변경 시 뼈 돌출 부위의 피부 발적과 손상을 확인한다.';why='스스로 움직이지 못하면 압력이 한 부위에 집중되어 욕창 위험이 높아진다.'})
    ther = @(
        @{plan='최소 2시간마다 체위를 변경하고 베개로 신체 선열을 유지한다.';why='정기적인 체위 변경은 압력을 분산시켜 피부 손상과 관절 기형을 예방한다.'},
        @{plan='침대 난간, 트래피즈(삼각 손잡이) 등 스스로 움직일 수 있는 보조 도구를 제공한다.';why='보조 도구는 남아 있는 근력을 활용하게 하여 독립적인 움직임을 늘린다.'},
        @{plan='체위 변경 시 시트를 이용하여 끌지 말고 들어서 옮긴다.';why='끄는 동작은 마찰력과 응전력을 발생시켜 피부를 손상시킨다.'},
        @{plan='대상자가 할 수 있는 동작은 스스로 하도록 격려하고 필요한 부분만 돕는다.';why='스스로 움직이는 경험은 근력 유지와 자신감 향상에 도움이 된다.'},
        @{plan='물리치료사와 협력하여 상지·몸통 근력 강화 운동을 시행한다.';why='근력이 향상되어야 침상 내 움직임이 독립적으로 가능해진다.'})
    edu = @(
        @{plan='보호자에게 2시간마다 체위 변경하는 방법과 베개 사용법을 교육한다.';why='보호자가 올바른 방법을 알면 퇴원 후에도 욕창과 합병증을 예방할 수 있다.'},
        @{plan='대상자에게 난간이나 트래피즈를 이용해 돌아눕는 방법을 교육한다.';why='효과적인 방법을 익히면 에너지 소모를 줄이며 스스로 자세를 바꿀 수 있다.'})
}
$script:Templates['보행 장애'] = @{
    en = 'Impaired walking'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '2. 활동/운동 Activity/Exercise'
    page = $null
    problem = '보행 장애'
    priority = 4
    reason = '걷기 능력의 제한으로 일상생활과 독립성이 떨어지는 기본 생리 욕구 문제로, 호흡·순환 문제보다는 후순위이다'
    evalData = '보행 거리와 속도, 보행 양상(보폭, 균형), 보조기구 사용 능력, 하지 근력, 보행 중 통증·어지러움, 낙상 여부'
    keywords = '보행 ?(장애|곤란|불안정|불가)|걷기 ?(힘들|어렵)|못 ?걷|절뚝|파행|claudication|gait|보행기|walker|지팡이|cane|목발|crutch|하지 ?근력 ?저하|고관절 ?골절|hip fracture|슬관절 ?치환|TKR|TKA|족하수|foot drop'
    cause = '하지 근력 저하와 통증'
    long = '대상자는 퇴원 시 보조기구를 이용하여 안전하게 원하는 거리를 걸을 수 있을 것이다.'
    short = @('대상자는 3일 내 보행기를 이용하여 복도를 20m 이상 걸을 것이다.','대상자는 1주일 내 보조기구의 올바른 사용법을 시범 보일 것이다.')
    diag = @(
        @{plan='매일 보행 거리, 보행 양상(보폭, 균형, 자세), 필요한 도움 정도를 사정한다.';why='보행 능력을 객관적으로 기록해야 중재 효과와 진척을 평가할 수 있다.'},
        @{plan='하지 근력, 관절가동범위, 보행 시 통증 정도를 사정한다.';why='근력 저하와 통증은 보행을 방해하는 주요 요인이므로 원인을 알아야 중재가 가능하다.'},
        @{plan='보행 전후 기립성 저혈압, 어지러움, 호흡곤란 여부를 확인한다.';why='보행 중 어지러움과 저혈압은 낙상의 원인이 되므로 안전한 보행 가능 여부를 먼저 확인한다.'})
    ther = @(
        @{plan='처음 보행 시에는 침상에 앉기 → 다리 늘어뜨리기 → 서기 순으로 천천히 진행하고 곁에서 보조한다.';why='자세를 단계적으로 바꾸면 기립성 저혈압을 줄이고 낙상을 예방할 수 있다.'},
        @{plan='대상자에게 맞는 보조기구(보행기, 지팡이, 목발)를 준비하고 높이를 조절한다.';why='알맞은 높이의 보조기구는 체중을 분산시키고 바른 자세로 걷게 한다.'},
        @{plan='미끄럼 방지 신발을 신게 하고 보행 경로의 장애물과 물기를 제거한다.';why='안전한 환경은 보행 중 넘어짐을 예방한다.'},
        @{plan='물리치료사와 협력하여 하지 근력 강화와 균형 운동을 시행하고 보행 거리를 점차 늘린다.';why='근력과 균형이 향상되면 보행의 안정성과 지구력이 높아진다.'},
        @{plan='처방에 따라 보행 30분 전 진통제를 투여한다.';why='통증을 미리 조절하면 보행 참여가 늘어나 재활이 촉진된다.'})
    edu = @(
        @{plan='대상자와 보호자에게 보조기구 사용법(지팡이는 건측 손에 잡기, 계단 오르내리기 방법)을 교육한다.';why='올바른 사용법은 환측 하지의 부담을 줄이고 퇴원 후 낙상을 예방한다.'},
        @{plan='가정 내 낙상 위험 요인(문턱, 미끄러운 바닥, 어두운 조명)을 정리하도록 교육한다.';why='가정 환경을 정비하면 퇴원 후에도 안전하게 걸을 수 있다.'})
}
$script:Templates['이동 능력 장애'] = @{
    en = 'Impaired transfer ability'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '2. 활동/운동 Activity/Exercise'
    page = $null
    problem = '이동 능력 장애'
    priority = 4
    reason = '침대·의자·변기 사이를 스스로 옮겨 앉지 못해 일상생활과 안전이 제한되는 기본 생리 욕구 문제로, 호흡·순환 문제보다는 후순위이다'
    evalData = '침대↔휠체어↔변기 이동 시 필요한 도움 정도, 앉은 자세 균형, 상·하지 근력, 이동 중 낙상 여부, 보조기구 사용 능력'
    keywords = '휠체어|wheelchair|옮겨 ?앉|이동 ?(시 ?)?(도움|보조|어려|불가)|transfer|침대에서 ?(못 ?내려|내려오기)|변기 ?(이동|사용 ?어려)|편마비|hemiplegia|하지 ?마비|paraplegia|절단|amputation|리프트|\blift\b'
    cause = '근력 저하와 균형 장애'
    long = '대상자는 퇴원 시 최소한의 도움으로 침대와 휠체어 사이를 안전하게 이동할 것이다.'
    short = @('대상자는 3일 내 1인의 도움을 받아 침대에서 휠체어로 안전하게 이동할 것이다.','대상자는 1주일 내 안전한 이동 방법을 순서대로 말로 표현할 것이다.')
    diag = @(
        @{plan='이동 동작(앉기, 서기, 돌기, 옮겨 앉기)별로 수행 능력과 필요한 도움 정도를 사정한다.';why='어느 단계에서 도움이 필요한지 알아야 안전한 이동 방법과 인력을 계획할 수 있다.'},
        @{plan='앉은 자세와 선 자세의 균형, 상·하지 근력, 체중 지지 가능 여부를 사정한다.';why='균형과 근력은 안전한 이동의 기본 조건이며, 체중 지지 제한은 이동 방법을 결정한다.'},
        @{plan='이동 시 어지러움, 통증, 활력징후 변화를 관찰한다.';why='이동 중 기립성 저혈압이나 통증은 낙상의 원인이 되므로 사전 확인이 필요하다.'})
    ther = @(
        @{plan='이동 전 침대 높이를 휠체어와 맞추고 휠체어를 건측에 30~45도로 두고 바퀴를 잠근다.';why='건측으로 이동하면 강한 쪽 다리로 체중을 지지할 수 있고, 바퀴 잠금은 미끄러짐을 막는다.'},
        @{plan='이동 벨트나 이동 보조기구를 사용하고 필요 시 2인 이상이 보조한다.';why='보조기구와 충분한 인력은 대상자와 간호사 모두의 손상을 예방한다.'},
        @{plan='대상자가 할 수 있는 동작은 스스로 하게 하고 각 단계를 짧게 설명하며 진행한다.';why='참여를 격려하면 근력과 자신감이 향상되고, 단계별 설명은 협조를 높인다.'},
        @{plan='물리치료사와 협력하여 앉은 자세 균형과 상지·하지 근력 강화 운동을 시행한다.';why='균형과 근력이 좋아지면 이동의 독립성이 높아진다.'})
    edu = @(
        @{plan='대상자와 보호자에게 침대-휠체어-변기 이동 방법과 휠체어 바퀴 잠금 확인을 교육하고 시범 보이게 한다.';why='직접 연습하면 퇴원 후에도 안전하게 이동을 도울 수 있다.'},
        @{plan='보호자에게 허리를 굽히지 말고 무릎을 굽혀 다리 힘으로 돕는 신체역학을 교육한다.';why='올바른 신체역학은 보호자의 허리 손상을 예방한다.'})
}
$script:Templates['비사용 증후군의 위험'] = @{
    en = 'Risk for disuse syndrome'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '2. 활동/운동 Activity/Exercise'
    page = $null
    problem = '부동 합병증 위험'
    priority = 5
    reason = '아직 합병증이 나타나지 않은 위험 진단이지만, 장기간 부동은 욕창·혈전·폐렴 등 여러 계통의 합병증으로 이어질 수 있어 예방이 필요하다'
    evalData = '피부 상태(브레이든 점수), 하지 부종·통증, 호흡음, 관절가동범위, 배변 양상, 근력, 체위 변경 수행 여부'
    keywords = '장기 ?(침상|부동)|부동|immobil|와상|bedridden|bed ?ridden|의식 ?저하|혼수|coma|사지 ?마비|quadriplegia|척수 ?손상|\bSCI\b|진정제 ?(투여|사용)|sedation|견인|traction|침상 ?안정|bed ?rest|브레이든|braden'
    cause = '장기간의 침상 안정'
    long = '대상자는 퇴원 시까지 부동으로 인한 합병증(욕창, 심부정맥혈전증, 폐렴, 관절 경축) 없이 지낼 것이다.'
    short = @('대상자는 1주일 내 뼈 돌출 부위에 피부 발적 없이 지낼 것이다.','대상자는 3일 내 하루 3회 이상 관절범위운동에 참여할 것이다.')
    diag = @(
        @{plan='매일 브레이든 척도로 욕창 위험을 사정하고 뼈 돌출 부위의 피부를 확인한다.';why='부동은 압력을 한 부위에 집중시켜 욕창을 유발하므로 정기적인 위험 평가가 필요하다.'},
        @{plan='매 듀티마다 하지의 부종, 통증, 열감, 종아리 둘레 차이를 사정한다.';why='정맥혈 정체는 심부정맥혈전증을 일으키며 조기 발견으로 폐색전증을 예방할 수 있다.'},
        @{plan='호흡음, 기침 능력, 관절가동범위, 배변 양상을 사정한다.';why='부동은 무기폐·폐렴, 관절 경축, 변비 등 여러 계통에 합병증을 일으킬 수 있다.'})
    ther = @(
        @{plan='최소 2시간마다 체위를 변경하고 압력 분산 매트리스를 적용한다.';why='체위 변경과 압력 분산은 조직 허혈을 막아 욕창을 예방한다.'},
        @{plan='금기가 아닐 시 하루 2~3회 능동적 또는 수동적 관절범위운동을 시행한다.';why='관절범위운동은 관절 경축과 근위축을 예방하고 순환을 돕는다.'},
        @{plan='심호흡, 기침, 강화폐활량계(incentive spirometer) 사용을 1시간마다 격려한다.';why='폐 확장을 유지하면 분비물 정체를 막아 무기폐와 폐렴을 예방한다.'},
        @{plan='처방에 따라 항혈전 스타킹, 간헐적 공기압박기를 적용하거나 항응고제를 투여하고 출혈 징후를 관찰한다.';why='정맥 환류를 돕고 혈액 응고를 억제하여 심부정맥혈전증을 예방하며, 항응고제 사용 시 출혈 위험이 있다.'},
        @{plan='금기가 아닐 시 수분 섭취(1,500~2,000mL/일)와 섬유질 섭취를 격려한다.';why='수분과 섬유질은 변비와 요로결석, 혈액 농축을 예방한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 체위 변경, 관절범위운동, 발목 펌프 운동 방법을 교육한다.';why='가족이 함께 참여하면 합병증 예방 활동을 꾸준히 지속할 수 있다.'},
        @{plan='종아리 통증·부종, 갑작스러운 호흡곤란, 피부 발적이 생기면 즉시 알리도록 교육한다.';why='심부정맥혈전증, 폐색전증, 욕창의 초기 징후를 빨리 알리면 즉시 치료할 수 있다.'})
}
$script:Templates['피로'] = @{
    en = 'Fatigue'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '3. 에너지 균형 Energy balance'
    page = $null
    problem = '피로'
    priority = 4
    reason = '지속적인 피로는 일상생활과 자가간호 수행을 방해하는 생리적 문제이지만, 생명을 위협하는 문제보다는 후순위이다'
    evalData = '피로 정도(0~10점 척도), 일상생활 수행 정도, 수면 시간, Hb·Hct, 활동 후 회복 시간, 피로를 표현하는 말'
    keywords = '피로|피곤|기운이 ?없|힘이 ?없|무기력|기력 ?저하|fatigue|tired|exhaust|탈진|항암|chemo|방사선 ?치료|radiation|빈혈|anemia|Hb ?[:=]? ?[0-9]\.|투석|dialysis|CKD|만성 ?신부전'
    cause = '질병 과정과 항암 치료'
    long = '대상자는 퇴원 시 에너지를 조절하여 원하는 일상생활을 수행할 수 있을 것이다.'
    short = @('대상자는 3일 내 피로 점수(0~10점)가 2점 이상 감소할 것이다.','대상자는 2일 내 에너지 보존 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매일 피로 정도를 0~10점 척도로 사정하고 하루 중 피로가 심한 시간대를 확인한다.';why='피로는 주관적 증상이므로 척도로 반복 평가해야 변화와 중재 효과를 알 수 있다.'},
        @{plan='피로에 영향을 주는 요인(빈혈, 수면 부족, 통증, 영양 부족, 우울, 약물)을 확인한다.';why='피로는 여러 원인이 함께 작용하므로 교정 가능한 원인을 찾아야 효과적으로 중재할 수 있다.'},
        @{plan='Hb, Hct, 전해질, 알부민 등 검사 결과를 확인한다.';why='빈혈과 영양 결핍, 전해질 불균형은 조직의 에너지 생산을 떨어뜨려 피로를 유발한다.'})
    ther = @(
        @{plan='대상자와 함께 하루 일과를 계획하여 중요한 활동은 에너지가 많은 시간에 하도록 한다.';why='활동의 우선순위를 정하고 시간을 조절하면 제한된 에너지를 효율적으로 사용할 수 있다.'},
        @{plan='활동 사이에 휴식 시간을 두고 밤에는 방해받지 않는 수면을 보장한다.';why='충분한 휴식과 수면은 에너지를 회복시킨다.'},
        @{plan='상태에 맞는 가벼운 운동(짧은 걷기)을 점차 늘리도록 격려한다.';why='적절한 유산소 활동은 오히려 체력을 높여 암 관련 피로 등을 줄이는 데 효과가 있다.'},
        @{plan='단백질과 열량이 충분한 식사를 소량씩 자주 제공한다.';why='적절한 영양은 에너지 생산과 조직 회복에 필요하다.'},
        @{plan='처방에 따라 빈혈 교정(철분제, 수혈 등) 치료를 시행하고 반응을 관찰한다.';why='빈혈을 교정하면 조직의 산소 공급이 늘어 피로가 감소한다.'})
    edu = @(
        @{plan='대상자에게 에너지 보존 방법(앉아서 하기, 물건을 가까이 두기, 일을 나누어 하기)을 교육한다.';why='에너지 소모를 줄이는 방법을 알면 피로를 덜 느끼며 자가간호를 할 수 있다.'},
        @{plan='보호자에게 대상자의 피로를 이해하고 필요한 일을 도와주도록 교육한다.';why='가족의 이해와 도움은 대상자의 심리적 부담과 신체적 피로를 줄인다.'})
}
$script:Templates['활동 지속성 감소'] = @{
    en = 'Decreased activity tolerance'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '활동 지속성 감소'
    priority = 4
    reason = '활동 시 산소 공급과 요구의 불균형으로 일상생활 수행이 제한되는 생리적 문제로, 호흡·순환 위기보다는 후순위이다'
    evalData = '활동 전·중·후 활력징후와 SpO2, 활동 시 호흡곤란·피로 표현, 보그(Borg) 운동자각도, 걸을 수 있는 거리, 일상생활 수행 정도'
    keywords = '활동 ?(시 )?(숨이 ?차|호흡곤란)|조금만 ?(걸어도|움직여도)|\bDOE\b|dyspnea on exertion|운동 ?시 ?호흡곤란|activity intolerance|NYHA|심부전|heart failure|CHF|COPD|빈혈|anemia|숨이 ?차서 ?(못|쉬어)'
    cause = '산소 공급과 요구의 불균형'
    long = '대상자는 퇴원 시 활력징후가 정상 범위 내에서 유지되며 원하는 일상생활을 수행할 수 있을 것이다.'
    short = @('대상자는 3일 내 활동 후 3분 이내에 맥박과 호흡수가 활동 전 수준으로 회복될 것이다.','대상자는 1주일 내 호흡곤란 없이 복도를 30m 이상 걸을 것이다.')
    diag = @(
        @{plan='활동 전, 활동 중, 활동 후 3분에 맥박, 혈압, 호흡수, SpO2를 측정한다.';why='활동에 대한 심폐 반응을 확인하면 대상자가 견딜 수 있는 활동 수준을 판단할 수 있다.'},
        @{plan='활동 중 호흡곤란, 흉통, 어지러움, 창백, 발한 등 활동 불내성 징후를 관찰한다.';why='이러한 증상은 산소 요구가 공급을 넘어섰다는 신호이므로 즉시 활동을 중단해야 한다.'},
        @{plan='보그(Borg) 운동자각도와 일상생활 수행 정도를 사정한다.';why='주관적 운동 강도와 수행 능력을 함께 보면 활동량 증가의 목표를 정할 수 있다.'})
    ther = @(
        @{plan='활동 중 맥박이 안정 시보다 20회/분 이상 증가하거나 SpO2가 90% 미만이면 활동을 중단하고 휴식하게 한다.';why='과도한 심폐 반응은 심근과 조직의 산소 부족을 의미하므로 활동을 멈춰 부담을 줄인다.'},
        @{plan='앉기 → 서기 → 걷기 순으로 활동량을 단계적으로 늘린다.';why='점진적 활동 증가는 심폐 기능이 적응할 시간을 주어 지구력을 높인다.'},
        @{plan='활동 사이에 휴식 시간을 계획하고 식사 직후에는 활동을 피한다.';why='식후에는 소화를 위해 혈류가 위장관으로 몰려 활동 시 산소 부족이 쉽게 생긴다.'},
        @{plan='처방에 따라 활동 시 산소를 투여한다.';why='보충 산소는 활동 중 산소 공급을 늘려 호흡곤란과 피로를 줄인다.'},
        @{plan='세면, 식사 등 일상생활 중 필요한 부분을 돕고 앉아서 하도록 한다.';why='앉아서 활동하면 에너지 소모가 줄어 더 오래 활동을 지속할 수 있다.'})
    edu = @(
        @{plan='대상자에게 활동 중 호흡곤란, 흉통, 어지러움이 생기면 즉시 멈추고 알리도록 교육한다.';why='위험 징후를 스스로 알아차리면 심각한 합병증을 예방할 수 있다.'},
        @{plan='대상자와 보호자에게 에너지 보존 방법과 단계적 활동 계획을 교육한다.';why='퇴원 후에도 무리 없이 활동량을 늘려 독립적인 생활을 할 수 있다.'})
}
$script:Templates['활동 지속성 감소의 위험'] = @{
    en = 'Risk for decreased activity tolerance'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '활동 지속성 감소 위험'
    priority = 5
    reason = '아직 활동 불내성이 나타나지 않은 위험 진단이므로 실제적 문제보다 우선순위가 낮지만, 예방하지 않으면 일상생활 수행이 제한될 수 있다'
    evalData = '활동 전·후 활력징후와 SpO2, 활동 시 피로·호흡곤란 표현, 활동량, 활동 후 회복 시간'
    keywords = '장기 ?침상|침상 ?안정|bed ?rest|deconditioning|체력 ?저하|심부전|heart failure|CHF|COPD|심근경색|\bA?MI\b|빈혈|anemia|수술 ?후 ?첫 ?(보행|이상)|첫 ?보행|조기 ?이상'
    cause = '장기간의 침상 안정으로 인한 체력 저하'
    long = '대상자는 퇴원 시 활력징후가 정상 범위 내에서 유지되며 일상생활을 수행할 것이다.'
    short = @('대상자는 3일 내 활동 후 맥박이 안정 시보다 20회/분 이내로 유지될 것이다.','대상자는 2일 내 활동을 멈춰야 하는 징후를 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='활동 전·후 맥박, 혈압, 호흡수, SpO2를 측정한다.';why='활동에 대한 신체 반응을 미리 확인하면 활동 불내성을 조기에 발견할 수 있다.'},
        @{plan='활동 시 피로, 호흡곤란, 어지러움, 흉통 여부를 관찰한다.';why='초기 불내성 징후를 발견하면 활동 수준을 조절하여 악화를 막을 수 있다.'},
        @{plan='기저 질환(심장·호흡기 질환, 빈혈)과 최근 활동량, 침상 안정 기간을 확인한다.';why='위험 요인을 알아야 대상자에게 안전한 활동 계획을 세울 수 있다.'})
    ther = @(
        @{plan='금기가 아닐 시 조기 이상을 격려하고 활동량을 단계적으로 늘린다.';why='점진적인 활동은 근력과 심폐 지구력이 떨어지는 것을 예방한다.'},
        @{plan='활동과 휴식을 번갈아 계획한다.';why='적절한 휴식은 에너지를 회복시켜 과도한 피로를 예방한다.'},
        @{plan='침상에서 할 수 있는 관절범위운동과 발목 펌프 운동을 시행한다.';why='침상 운동은 근위축과 체력 저하를 줄여 이후 활동 지속성을 유지한다.'},
        @{plan='균형 잡힌 영양과 충분한 수면을 제공한다.';why='영양과 수면은 활동에 필요한 에너지를 공급한다.'})
    edu = @(
        @{plan='대상자에게 활동 중 호흡곤란, 흉통, 어지러움이 생기면 멈추고 알리도록 교육한다.';why='스스로 위험 징후를 알아차리면 과도한 활동으로 인한 합병증을 예방한다.'},
        @{plan='대상자와 보호자에게 퇴원 후 걷기 등 활동량을 조금씩 늘리는 방법을 교육한다.';why='단계적 활동 계획은 체력을 안전하게 회복시킨다.'})
}
$script:Templates['심박출량 감소'] = @{
    en = 'Decreased cardiac output'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '심박출량 감소'
    priority = 2
    reason = '심장이 신체 요구를 충족할 만큼 혈액을 내보내지 못해 조직 관류가 떨어지는 ABC 중 순환 문제이므로 우선순위가 높다'
    evalData = '혈압·맥박·리듬(ECG), 소변량(시간당 0.5mL/kg 이상), 말초 맥박과 모세혈관 재충전 시간, 폐 수포음, 체중, 의식 수준, BNP'
    keywords = '심부전|heart failure|CHF|HFrEF|EF ?[:=]? ?[1-3]\d ?%|박출률 ?저하|심박출량|cardiac output|BNP|NT-?proBNP|심근경색|\bMI\b|STEMI|NSTEMI|심인성 ?쇼크|cardiogenic|부정맥|arrhythmia|심방세동|\bAF\b|a-?fib|S3|경정맥 ?팽대|JVD|수포음|crackle|라식스|furosemide|디곡신|digoxin'
    cause = '심근 수축력 저하'
    long = '대상자는 퇴원 시 적절한 심박출량을 유지하여 활력징후가 안정될 것이다.'
    short = @('대상자는 2일 내 수축기 혈압 90mmHg 이상, 맥박 60~100회/분을 유지할 것이다.','대상자는 3일 내 시간당 소변량이 0.5mL/kg 이상 유지될 것이다.')
    diag = @(
        @{plan='매 1~4시간마다 혈압, 맥박(심첨맥박 1분), 호흡수, SpO2를 측정하고 심전도 리듬을 관찰한다.';why='심박출량 감소는 저혈압, 빈맥, 부정맥으로 나타나므로 지속적 관찰로 악화를 조기에 발견한다.'},
        @{plan='매 듀티마다 I/O와 매일 아침 같은 조건에서 체중을 측정한다.';why='소변량 감소는 신장 관류 저하를, 하루 1kg 이상의 체중 증가는 체액 정체를 의미한다.'},
        @{plan='폐 수포음, 경정맥 팽대, 말초 부종, 말초 맥박, 모세혈관 재충전 시간, 의식 수준을 사정한다.';why='폐울혈과 말초 관류 저하 징후는 심부전 악화와 조직 관류 상태를 반영한다.'})
    ther = @(
        @{plan='금기가 아닐 시 반좌위를 취하게 하고 처방에 따라 산소를 투여한다.';why='반좌위는 정맥 환류를 줄여 심장 부담과 폐울혈을 감소시키고, 산소는 심근과 조직의 산소 공급을 늘린다.'},
        @{plan='처방에 따라 이뇨제를 투여하고 소변량, 혈청 칼륨, 혈압을 관찰한다.';why='이뇨제는 체액 과부하를 줄여 전부하를 낮추지만 저칼륨혈증과 저혈압이 생길 수 있다.'},
        @{plan='처방에 따라 강심제나 혈관확장제를 투여하고 투여 전 심첨맥박(디곡신 시 60회/분 미만이면 보류 후 보고)과 혈압을 확인한다.';why='강심제는 심근 수축력을 높이고 혈관확장제는 후부하를 줄여 심박출량을 개선하지만, 서맥·저혈압·디곡신 독성에 주의해야 한다.'},
        @{plan='처방에 따라 수분과 나트륨 섭취를 제한하고 정확히 기록한다.';why='수분과 나트륨 제한은 체액 정체를 줄여 심장의 부담을 덜어준다.'},
        @{plan='활동과 휴식을 조절하고 조용한 환경을 제공하여 심장의 산소 요구를 줄인다.';why='신체적·정서적 스트레스를 줄이면 심근 산소 소모량이 감소한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 매일 같은 시간에 체중을 재고 하루 1kg 또는 1주 2kg 이상 증가하면 알리도록 교육한다.';why='체중 증가는 체액 정체의 초기 징후이므로 조기에 알리면 입원을 예방할 수 있다.'},
        @{plan='대상자에게 저염식, 처방 약물의 규칙적 복용, 호흡곤란·부종 악화 시 즉시 병원 방문을 교육한다.';why='자가관리 능력을 높이면 심부전 악화와 재입원을 줄일 수 있다.'})
}
$script:Templates['심박출량 감소의 위험'] = @{
    en = 'Risk for decreased cardiac output'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '심박출량 감소 위험'
    priority = 5
    reason = '아직 심박출량 감소가 나타나지 않은 위험 진단이지만, 발생 시 순환 문제로 빠르게 악화될 수 있어 예방과 관찰이 필요하다'
    evalData = '혈압·맥박·리듬(ECG), 소변량, 말초 순환 상태, 폐 수포음, 체중, 혈청 전해질(K, Mg)'
    keywords = '심근경색|\bMI\b|협심증|angina|부정맥|arrhythmia|심방세동|a-?fib|판막 ?질환|valve|대동맥 ?판막|심장 ?수술|CABG|PCI|고혈압 ?위기|베타 ?차단제|beta ?blocker|저칼륨|hypokalemia|패혈증|sepsis|심근병증|cardiomyopathy'
    cause = '심근 허혈'
    long = '대상자는 퇴원 시까지 심박출량 감소 징후 없이 활력징후를 정상 범위로 유지할 것이다.'
    short = @('대상자는 2일 내 혈압과 맥박이 정상 범위(수축기 90~140mmHg, 맥박 60~100회/분)를 유지할 것이다.','대상자는 3일 내 심박출량 감소 징후(호흡곤란, 어지러움, 소변량 감소)를 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매 4시간마다 혈압, 맥박, 호흡수, SpO2를 측정하고 필요 시 심전도 리듬을 관찰한다.';why='활력징후와 리듬 변화는 심박출량 감소를 조기에 알려준다.'},
        @{plan='매 듀티마다 I/O, 말초 맥박, 피부색과 온도, 의식 수준을 사정한다.';why='소변량 감소와 차가운 피부, 의식 변화는 조직 관류 저하의 초기 징후이다.'},
        @{plan='혈청 전해질(K, Mg), 심근효소, BNP 등 검사 결과를 확인한다.';why='전해질 불균형은 부정맥을 유발하고 심근효소·BNP는 심근 손상과 심부전을 반영한다.'})
    ther = @(
        @{plan='처방에 따라 항부정맥제, 항고혈압제 등을 투여하고 투여 전 맥박과 혈압을 확인한다.';why='약물은 심장 리듬과 부하를 조절하지만 서맥·저혈압이 생길 수 있어 투여 전 확인이 필요하다.'},
        @{plan='처방에 따라 전해질 이상을 교정하고 수액 속도를 정확히 유지한다.';why='적정 전해질과 체액량은 심근 수축과 리듬을 안정시킨다.'},
        @{plan='활동과 휴식을 조절하고 정서적 안정을 돕는다.';why='스트레스와 과도한 활동은 심근 산소 요구를 증가시킨다.'},
        @{plan='변비 예방을 위해 수분·섬유질 섭취를 격려하고 배변 시 힘주지 않게 한다.';why='배변 시 힘주기(발살바 수기)는 미주신경을 자극하여 서맥과 혈압 변동을 일으킨다.'})
    edu = @(
        @{plan='대상자에게 가슴 답답함, 두근거림, 어지러움, 호흡곤란이 생기면 즉시 알리도록 교육한다.';why='증상을 빨리 알리면 심박출량 감소를 조기에 치료할 수 있다.'},
        @{plan='대상자와 보호자에게 처방 약물의 복용 방법과 맥박 측정 방법을 교육한다.';why='약물을 규칙적으로 복용하고 맥박 변화를 확인하면 합병증을 예방할 수 있다.'})
}
$script:Templates['자발적 환기 장애'] = @{
    en = 'Impaired spontaneous ventilation'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '자발적 환기 장애'
    priority = 1
    reason = '스스로 충분한 호흡을 유지하지 못해 생명이 위협되는 ABC 중 호흡 문제이므로 최우선이다'
    evalData = '호흡수와 일회호흡량, SpO2, ABGA(PaCO2, pH), 보조근 사용, 의식 수준, 인공호흡기 설정과 경보'
    keywords = '인공호흡기|ventilator|기계환기|mechanical ventilation|기관 ?내 ?삽관|intubat|E-?tube|\bETT\b|기관절개|tracheostomy|호흡 ?근 ?(약화|피로)|호흡부전|respiratory failure|PaCO2 ?[:=]? ?[5-9]\d|고탄산|hypercapnia|길랭-?바레|guillain|중증 ?근무력증|myasthenia|\bALS\b|BiPAP|\bNIV\b|앰부|ambu'
    cause = '호흡근 피로'
    long = '대상자는 퇴원 시까지 적절한 환기를 유지하여 정상 범위의 ABGA를 유지할 것이다.'
    short = @('대상자는 1일 내 인공호흡기 또는 보조 환기로 SpO2를 92% 이상 유지할 것이다.','대상자는 3일 내 PaCO2가 35~45mmHg, pH가 7.35~7.45 범위로 회복될 것이다.')
    diag = @(
        @{plan='매 1시간마다 호흡수, 호흡 양상, 흉곽 움직임의 대칭성, 보조근 사용, SpO2를 사정한다.';why='자발 호흡의 악화는 빈호흡과 보조근 사용으로 먼저 나타나므로 지속적 관찰이 필요하다.'},
        @{plan='처방에 따라 ABGA를 확인하고 PaCO2와 pH 변화를 관찰한다.';why='PaCO2 상승과 산증은 환기 부전의 객관적 지표이다.'},
        @{plan='의식 수준과 인공호흡기 설정(모드, FiO2, PEEP, 일회호흡량)과 경보를 매 듀티마다 확인한다.';why='의식 저하는 고탄산혈증을 의미할 수 있고, 설정과 경보 확인은 환기 오류를 빠르게 발견하게 한다.'})
    ther = @(
        @{plan='처방에 따라 산소와 기계환기(또는 비침습적 환기)를 적용하고 기관 내관 위치와 고정을 확인한다.';why='기계환기는 피로한 호흡근을 대신하여 적절한 환기를 유지하며, 관이 빠지거나 밀리면 환기가 중단된다.'},
        @{plan='필요 시 무균적으로 기관 흡인을 시행하고 흡인 전후 100% 산소를 공급한다.';why='분비물 제거는 기도 개방성을 유지하며, 흡인 전후 산소 공급은 흡인으로 인한 저산소증을 예방한다.'},
        @{plan='금기가 아닐 시 침상머리를 30~45도 올린다.';why='상체 거상은 횡격막 움직임을 도와 환기를 개선하고 인공호흡기 관련 폐렴을 예방한다.'},
        @{plan='앰부백과 흡인 기구를 침상 옆에 항상 준비한다.';why='기계 오작동이나 관 이탈 시 즉시 수동 환기를 할 수 있어야 생명을 지킬 수 있다.'},
        @{plan='처방에 따라 진정제를 투여하고 진정 척도(RASS)로 진정 정도를 평가한다.';why='적절한 진정은 기계와의 비동조를 줄이지만 과진정은 호흡 억제와 이탈 지연을 일으킨다.'})
    edu = @(
        @{plan='대상자에게 말을 할 수 없을 때 사용할 의사소통 방법(글자판, 눈 깜빡임, 호출벨)을 교육한다.';why='의사소통 수단이 있으면 불편감을 알릴 수 있어 불안이 줄고 협조가 높아진다.'},
        @{plan='보호자에게 인공호흡기와 관의 목적, 경보음의 의미를 설명하고 관을 만지지 않도록 교육한다.';why='치료에 대한 이해는 보호자의 불안을 줄이고 관 이탈 사고를 예방한다.'})
}
$script:Templates['인공호흡기 이탈 반응 장애'] = @{
    en = 'Dysfunctional ventilatory weaning response'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '인공호흡기 이탈 곤란'
    priority = 1
    reason = '인공호흡기 지지를 줄이는 과정에서 자발 호흡을 유지하지 못하는 호흡 문제로, ABC 중 호흡과 직결되어 최우선이다'
    evalData = '자발호흡시험(SBT) 중 호흡수·일회호흡량·RSBI, SpO2, 맥박과 혈압 변화, 보조근 사용, 불안·발한, ABGA'
    keywords = '이탈|weaning|wean|자발호흡시험|\bSBT\b|T-?piece|CPAP ?trial|RSBI|발관|extubat|재삽관|reintubat|PSV|압력 ?보조|장기 ?(인공호흡기|기계환기)|prolonged ventilation'
    cause = '호흡근 약화와 장기간의 기계환기'
    long = '대상자는 퇴원 시까지 인공호흡기 없이 자발 호흡을 유지할 것이다.'
    short = @('대상자는 2일 내 30분 이상의 자발호흡시험 동안 호흡수 35회/분 미만, SpO2 90% 이상을 유지할 것이다.','대상자는 1주일 내 인공호흡기를 이탈하여 발관 후 48시간 동안 재삽관 없이 지낼 것이다.')
    diag = @(
        @{plan='매일 이탈 준비 상태(원인 질환 호전, FiO2 0.4 이하, PEEP 8 이하, 혈역학적 안정, 의식 수준)를 확인한다.';why='이탈 기준을 충족할 때 시도해야 이탈 실패와 재삽관 위험을 줄일 수 있다.'},
        @{plan='이탈 시도 중 호흡수, 일회호흡량, SpO2, 맥박, 혈압, 보조근 사용, 발한·불안을 지속적으로 관찰한다.';why='빈호흡, 빈맥, 혈압 변화, 보조근 사용은 호흡근 피로와 이탈 실패의 초기 징후이다.'},
        @{plan='이탈 전후 ABGA, 영양 상태(알부민), 전해질(K, Mg, P)을 확인한다.';why='영양 부족과 전해질 이상은 호흡근 힘을 약화시켜 이탈을 어렵게 한다.'})
    ther = @(
        @{plan='이탈 실패 징후(호흡수 35회/분 이상, SpO2 90% 미만, 맥박 20% 이상 증가 등)가 나타나면 이전 환기 설정으로 되돌리고 보고한다.';why='무리한 이탈 지속은 호흡근을 탈진시키므로 즉시 휴식을 주어 회복을 돕는다.'},
        @{plan='이탈 시도는 대상자가 충분히 쉰 오전 시간에 계획하고 그 시간에는 다른 처치를 피한다.';why='휴식 후에는 호흡근 에너지가 충분하고, 다른 처치를 피하면 산소 소모를 줄일 수 있다.'},
        @{plan='금기가 아닐 시 침상머리를 30~45도 이상 올리거나 앉은 자세를 취하게 한다.';why='상체를 올리면 횡격막 움직임이 쉬워져 자발 호흡의 효율이 높아진다.'},
        @{plan='처방에 따라 매일 진정제를 중단하거나 줄이고 진정 정도를 평가한다.';why='매일 진정 중단은 호흡 동기를 회복시켜 기계환기 기간을 줄인다.'},
        @{plan='이탈 중 곁에 머물며 호흡을 코칭하고 안심시킨다.';why='불안은 호흡수와 산소 소모를 늘리므로 정서적 지지가 이탈 성공을 돕는다.'})
    edu = @(
        @{plan='대상자에게 이탈 과정과 기대되는 느낌을 설명하고 천천히 깊게 숨 쉬는 방법을 교육한다.';why='과정을 이해하고 호흡 방법을 알면 불안이 줄고 이탈에 적극적으로 참여할 수 있다.'},
        @{plan='대상자와 보호자에게 발관 후 심호흡, 기침, 강화폐활량계 사용 방법을 교육한다.';why='발관 후 폐 확장과 분비물 배출을 유지하면 재삽관 위험이 줄어든다.'})
}
$script:Templates['비효과적 말초조직관류'] = @{
    en = 'Ineffective peripheral tissue perfusion'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '말초조직관류 저하'
    priority = 2
    reason = '말초로 가는 혈류가 감소하여 조직 손상과 괴사로 이어질 수 있는 순환 문제이므로 우선순위가 높다'
    evalData = '말초 맥박(족배·후경골 동맥), 피부색과 온도, 모세혈관 재충전 시간, 하지 통증(간헐적 파행), 상처 치유 상태, ABI 수치'
    keywords = '말초 ?동맥 ?질환|\bPAD\b|PAOD|폐색성 ?동맥|간헐적 ?파행|claudication|족배 ?동맥 ?(약|촉지 ?안)|dorsalis pedis|맥박 ?촉지 ?(안|불가)|\bABI\b|발목상완지수|하지 ?(냉감|창백)|cold extremit|청색증|당뇨발|diabetic foot|괴저|gangrene|궤양|ulcer|레이노|raynaud|CRT ?[:=]? ?[3-9]'
    cause = '동맥 혈류 감소'
    long = '대상자는 퇴원 시 적절한 말초 순환을 유지하여 조직 손상 없이 지낼 것이다.'
    short = @('대상자는 3일 내 양측 족배동맥 맥박이 촉지되고 모세혈관 재충전 시간이 3초 이내로 유지될 것이다.','대상자는 1주일 내 말초 순환을 돕는 생활 방법을 세 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매 4시간마다 양측 말초 맥박, 피부색, 온도, 모세혈관 재충전 시간을 비교하여 사정한다.';why='양측을 비교하면 혈류 저하 부위와 진행 정도를 객관적으로 알 수 있다.'},
        @{plan='하지 통증의 양상(걸을 때 아프고 쉬면 나아지는 통증, 안정 시 통증)과 감각 변화를 사정한다.';why='안정 시 통증과 감각 저하는 심한 허혈을 의미하여 즉각적인 보고가 필요하다.'},
        @{plan='발과 다리의 피부 상태(건조, 털 소실, 궤양, 색 변화)와 ABI 결과를 확인한다.';why='만성 허혈은 피부 영양 변화와 궤양을 일으키며 ABI는 동맥 폐색 정도를 반영한다.'})
    ther = @(
        @{plan='동맥 질환 시 하지를 심장보다 높이지 말고 약간 낮게 두거나 수평으로 유지한다.';why='동맥 혈류는 중력의 도움을 받으므로 다리를 높이면 혈류가 더 감소한다.'},
        @{plan='다리를 꼬거나 무릎 아래에 베개를 받치지 않게 하고 꽉 끼는 옷을 피한다.';why='외부 압박은 혈관을 눌러 혈류를 감소시킨다.'},
        @{plan='직접적인 열 적용(핫팩, 전기장판)을 피하고 양말과 담요로 보온한다.';why='허혈 조직은 감각이 둔해 화상 위험이 크며, 열은 조직 대사를 높여 산소 요구를 증가시킨다.'},
        @{plan='처방에 따라 항혈소판제나 혈관확장제를 투여하고 출혈 징후를 관찰한다.';why='항혈소판제는 혈전 형성을 막아 혈류를 유지하지만 출혈 위험이 있다.'},
        @{plan='금기가 아닐 시 통증이 생기기 전까지 걷고 쉬기를 반복하는 운동을 격려한다.';why='규칙적인 걷기 운동은 측부 순환을 발달시켜 보행 거리를 늘린다.'})
    edu = @(
        @{plan='대상자에게 금연, 혈당·혈압·콜레스테롤 조절의 중요성을 교육한다.';why='흡연과 대사 질환은 동맥경화를 악화시키는 주요 위험 요인이다.'},
        @{plan='대상자와 보호자에게 매일 발을 관찰하고 깨끗이 씻어 말리며 맨발로 다니지 않도록 교육한다.';why='순환이 나쁜 발은 작은 상처도 낫기 어려우므로 예방적 발 관리가 중요하다.'})
}
$script:Templates['비효과적 말초조직관류의 위험'] = @{
    en = 'Risk for ineffective peripheral tissue perfusion'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '말초조직관류 저하 위험'
    priority = 5
    reason = '아직 말초 혈류 저하가 나타나지 않은 위험 진단이므로 실제적 문제보다 우선순위가 낮지만, 진행 시 조직 손상이 생길 수 있어 예방이 필요하다'
    evalData = '말초 맥박, 피부색과 온도, 모세혈관 재충전 시간, 부종, 감각 변화, 혈당·혈압 조절 상태'
    keywords = '당뇨|diabetes|\bDM\b|흡연|smok|고지혈증|이상지질|dyslipidemia|동맥경화|atherosclero|깁스|cast|부목|splint|석고붕대|구획 ?증후군|compartment|대퇴 ?동맥 ?천자|femoral|시술 ?부위 ?압박|sand ?bag|모래주머니'
    cause = '당뇨병과 흡연'
    long = '대상자는 퇴원 시까지 말초 순환 저하 징후 없이 지낼 것이다.'
    short = @('대상자는 2일 내 양측 말초 맥박이 촉지되고 피부가 따뜻하게 유지될 것이다.','대상자는 3일 내 말초 순환 저하 징후를 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매 4시간마다 양측 말초 맥박, 피부색, 온도, 모세혈관 재충전 시간을 비교하여 사정한다.';why='순환 변화를 조기에 발견하면 조직 손상 전에 중재할 수 있다.'},
        @{plan='깁스나 압박 부위가 있으면 원위부의 6P(통증, 창백, 맥박 소실, 감각 이상, 마비, 냉감)를 확인한다.';why='외부 압박과 부종은 구획증후군을 일으킬 수 있으며 6P는 그 초기 징후이다.'},
        @{plan='혈당, 혈압, 지질 검사 결과와 흡연 여부를 확인한다.';why='이러한 위험 요인을 파악해야 예방 교육과 관리 목표를 세울 수 있다.'})
    ther = @(
        @{plan='다리를 꼬지 않게 하고 꽉 끼는 옷이나 붕대를 피하며 필요 시 깁스·붕대를 느슨하게 조정하도록 보고한다.';why='외부 압박을 줄이면 혈관 압박에 의한 혈류 감소를 예방할 수 있다.'},
        @{plan='금기가 아닐 시 발목 펌프 운동과 걷기를 격려한다.';why='근육 수축은 혈액순환을 돕고 정맥 정체를 예방한다.'},
        @{plan='직접적인 열 적용을 피하고 보온을 유지한다.';why='감각이 둔한 대상자는 화상 위험이 있으며 적절한 보온은 혈관 수축을 막는다.'},
        @{plan='처방에 따라 혈당 조절 약물과 항혈소판제 등을 투여하고 효과를 관찰한다.';why='혈당과 혈소판 응집을 조절하면 미세혈관과 대혈관 손상을 늦출 수 있다.'})
    edu = @(
        @{plan='대상자에게 금연과 혈당·혈압 관리의 중요성을 교육한다.';why='흡연은 혈관을 수축시키고 고혈당은 혈관벽을 손상시켜 말초 순환을 악화시킨다.'},
        @{plan='대상자와 보호자에게 손발이 차갑거나 저리고 색이 변하면 즉시 알리도록 교육한다.';why='순환 저하 징후를 빨리 알리면 조직 손상을 예방할 수 있다.'})
}
$script:Templates['비효과적 뇌조직관류의 위험'] = @{
    en = 'Risk for ineffective cerebral tissue perfusion'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '뇌조직관류 저하 위험'
    priority = 5
    reason = '아직 뇌 관류 저하가 나타나지 않은 위험 진단이지만, 발생 시 영구적 신경 손상으로 이어질 수 있어 예방과 집중 관찰이 필요하다'
    evalData = '의식 수준(GCS), 동공 크기와 반응, 사지 근력, 언어 기능, 혈압, 두통·구토 여부, 신경학적 변화'
    keywords = '뇌졸중|stroke|CVA|뇌경색|cerebral infarction|뇌출혈|\bICH\b|\bSAH\b|지주막하|\bTIA\b|일과성 ?허혈|뇌동맥류|aneurysm|두부 ?손상|head injury|TBI|뇌부종|\bICP\b|두개내압|GCS|경동맥 ?협착|carotid|심방세동|a-?fib|tPA|혈전용해'
    cause = '뇌혈관 질환'
    long = '대상자는 퇴원 시까지 신경학적 악화 없이 의식 수준을 유지할 것이다.'
    short = @('대상자는 2일 내 GCS 점수가 입원 시보다 감소하지 않을 것이다.','대상자는 3일 내 혈압이 처방된 목표 범위 내로 유지될 것이다.')
    diag = @(
        @{plan='매 1~4시간마다 GCS, 동공 크기와 대광 반사, 사지 근력, 언어 기능을 사정한다.';why='신경학적 사정을 반복하면 뇌 관류 저하나 두개내압 상승을 조기에 발견할 수 있다.'},
        @{plan='혈압, 맥박, 호흡 양상을 측정하고 쿠싱 3징후(수축기 혈압 상승, 서맥, 불규칙 호흡)를 관찰한다.';why='뇌 관류압은 혈압에 따라 달라지며, 쿠싱 3징후는 두개내압 상승의 후기 징후이다.'},
        @{plan='두통, 구토, 시야 변화, 경련, 안절부절 여부를 관찰한다.';why='이러한 증상은 뇌압 상승이나 새로운 뇌혈관 사건의 신호일 수 있다.'})
    ther = @(
        @{plan='금기가 아닐 시 침상머리를 30도 올리고 머리와 목을 일직선으로 유지한다.';why='머리를 올리고 목을 꺾지 않으면 뇌정맥 배출이 원활해져 두개내압이 낮아진다.'},
        @{plan='기침, 배변 시 힘주기, 고개 굽히기 등 두개내압을 높이는 행동을 피하게 하고 처치를 몰아서 하지 않는다.';why='복압과 흉곽 내압 상승은 두개내압을 높이고 연속 처치는 뇌압 상승을 누적시킨다.'},
        @{plan='처방에 따라 혈압을 목표 범위로 조절하는 약물이나 항혈전제를 투여하고 출혈 징후를 관찰한다.';why='적정 혈압은 뇌 관류압을 유지하고, 항혈전제는 뇌경색 재발을 막지만 출혈 위험이 있다.'},
        @{plan='처방에 따라 산소를 공급하여 SpO2를 94% 이상 유지하고 체온을 정상으로 유지한다.';why='저산소증과 발열은 뇌 손상을 악화시킨다.'},
        @{plan='조용하고 자극이 적은 환경을 제공하고 경련에 대비한 안전 조치를 한다.';why='과도한 자극은 뇌의 산소 요구와 두개내압을 높일 수 있다.'})
    edu = @(
        @{plan='대상자와 보호자에게 뇌졸중 경고 증상(한쪽 얼굴·팔다리 마비, 말이 어눌함, 갑작스러운 두통, 시야 이상)을 교육한다.';why='증상을 빨리 알아차리면 골든타임 내 치료를 받을 수 있다.'},
        @{plan='대상자에게 혈압 관리, 금연, 처방 약물의 규칙적 복용을 교육한다.';why='고혈압과 흡연은 뇌혈관 질환의 가장 중요한 조절 가능한 위험 요인이다.'})
}
$script:Templates['심장조직관류 감소의 위험'] = @{
    en = 'Risk for decreased cardiac tissue perfusion'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '심장조직관류 감소 위험'
    priority = 5
    reason = '아직 심근 허혈이 나타나지 않은 위험 진단이지만, 발생 시 심근경색 등 생명을 위협하는 순환 문제로 진행할 수 있어 예방이 필요하다'
    evalData = '흉통 유무와 양상, 12유도 심전도(ST 변화), 심근효소(트로포닌), 혈압·맥박, SpO2, 위험 요인 관리 상태'
    keywords = '협심증|angina|흉통|chest pain|가슴이 ?(답답|조이|쥐어짜)|관상동맥|coronary|\bCAD\b|심근경색|\bMI\b|\bACS\b|트로포닌|troponin|CK-?MB|ST ?(분절|상승|하강|elevation|depression)|니트로글리세린|nitroglycerin|NTG|PCI|스텐트|stent|CABG'
    cause = '관상동맥 질환'
    long = '대상자는 퇴원 시까지 흉통 없이 심근 허혈 징후 없이 지낼 것이다.'
    short = @('대상자는 2일 내 흉통을 호소하지 않고 심전도에서 새로운 ST 변화가 없을 것이다.','대상자는 3일 내 흉통 발생 시 대처 방법을 순서대로 말로 표현할 것이다.')
    diag = @(
        @{plan='매 4시간마다 혈압, 맥박, SpO2를 측정하고 흉통 유무와 양상(부위, 강도, 방사, 지속시간)을 사정한다.';why='흉통과 활력징후 변화는 심근 허혈의 가장 중요한 초기 지표이다.'},
        @{plan='흉통 발생 시 즉시 12유도 심전도를 시행하여 ST 분절 변화를 확인한다.';why='통증 중 심전도는 허혈과 심근경색을 빠르게 구분하는 데 필요하다.'},
        @{plan='심근효소(트로포닌, CK-MB)와 지질, 혈당 검사 결과를 확인한다.';why='심근효소는 심근 손상을, 지질과 혈당은 관상동맥 질환 위험 요인을 반영한다.'})
    ther = @(
        @{plan='흉통 시 활동을 중단하고 안정시키며 처방에 따라 산소(SpO2 90% 미만 시)와 니트로글리세린을 투여하고 투여 전후 혈압을 확인한다.';why='니트로글리세린은 관상동맥을 확장시켜 허혈을 줄이지만 저혈압을 유발할 수 있어 수축기 혈압 90mmHg 미만이면 투여하지 않는다.'},
        @{plan='처방에 따라 항혈소판제, 베타차단제, 스타틴 등을 투여하고 출혈, 서맥, 저혈압을 관찰한다.';why='이 약물들은 혈전 형성과 심근 산소 요구를 줄여 관상동맥 사건을 예방한다.'},
        @{plan='활동과 휴식을 조절하고 과식을 피하며 소량씩 자주 식사하게 한다.';why='과도한 활동과 과식은 심근의 산소 요구를 증가시킨다.'},
        @{plan='조용한 환경과 정서적 지지를 제공한다.';why='불안과 스트레스는 교감신경을 자극하여 심박수와 심근 산소 소모를 늘린다.'})
    edu = @(
        @{plan='대상자에게 흉통 시 즉시 활동을 멈추고 알리며, 처방된 니트로글리세린 사용법(5분 간격 최대 3회, 호전 없으면 119)을 교육한다.';why='올바른 대처는 심근 손상을 최소화하고 심근경색을 빠르게 치료받게 한다.'},
        @{plan='대상자와 보호자에게 금연, 저염·저지방 식이, 규칙적 운동, 혈압·혈당 관리를 교육한다.';why='생활습관 개선은 관상동맥 질환의 진행과 재발을 줄인다.'})
}
$script:Templates['비효과적 신장관류의 위험'] = @{
    en = 'Risk for ineffective renal perfusion'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '신장관류 저하 위험'
    priority = 5
    reason = '아직 나타나지 않은 위험 진단이지만 신장 손상은 회복이 어려울 수 있어 생리적 안전 요구로서 예방이 필요하다'
    evalData = '시간당 소변량, 섭취량·배설량(I/O), BUN·Cr·eGFR 추이, 혈압, 체중 변화, 부종 여부'
    keywords = 'BUN|creatinine|크레아티닌|\bCr\b|e?GFR|핍뇨|oliguria|소변량 감소|소변이 적|\bAKI\b|급성 신손상|신부전|renal failure|조영제|contrast|신독성|nephrotox|반코마이신|vancomycin|gentamicin|겐타마이신|\bNSAIDs?\b'
    cause = '순환혈액량 감소'
    long = '대상자는 퇴원 시까지 신기능 저하 없이 정상 범위의 소변량을 유지할 것이다.'
    short = @('대상자는 입원 기간 동안 시간당 소변량을 0.5mL/kg 이상으로 유지할 것이다.','대상자는 3일 내 BUN과 Cr이 기준치 이상으로 상승하지 않을 것이다.')
    diag = @(
        @{plan='매 시간 또는 매 듀티마다 소변량과 섭취량·배설량(I/O)을 측정한다.';why='시간당 소변량이 0.5mL/kg 미만으로 감소하는 것은 신장관류 저하의 초기 지표이므로 조기 발견에 중요하다.'},
        @{plan='BUN, Cr, eGFR, 전해질(K⁺, Na⁺) 검사 결과를 확인한다.';why='신기능 지표의 상승과 고칼륨혈증은 사구체 여과 기능의 저하를 객관적으로 나타낸다.'},
        @{plan='매 4시간마다 혈압과 맥박을 측정하고 매일 같은 시간에 체중을 측정한다.';why='저혈압은 신혈류를 감소시키고, 급격한 체중 증가는 체액 정체를 의미하므로 신장 상태 평가에 도움이 된다.'})
    ther = @(
        @{plan='처방에 따라 수액을 투여하고 투여 속도와 폐울혈 징후(수포음, 호흡곤란)를 관찰한다.';why='적절한 수액 공급은 순환혈액량을 유지하여 신혈류를 보존하지만, 과다 투여 시 폐부종이 생길 수 있다.'},
        @{plan='신독성 약물(아미노글리코사이드, 반코마이신, NSAIDs, 조영제 등) 투여 시 처방과 혈중 약물 농도를 확인한다.';why='신독성 약물은 세뇨관을 직접 손상시킬 수 있으므로 용량과 농도를 관리하여 신손상을 예방한다.'},
        @{plan='금기가 아닐 시 수분 섭취를 격려한다.';why='충분한 수분 섭취는 신혈류와 소변 생성을 유지하여 노폐물 배설을 돕는다.'},
        @{plan='평균동맥압(MAP)이 65mmHg 미만이거나 소변량이 감소하면 즉시 보고한다.';why='신장은 일정 수준 이상의 관류압이 유지되어야 여과 기능을 할 수 있으므로 빠른 보고로 손상을 막을 수 있다.'})
    edu = @(
        @{plan='대상자와 보호자에게 소변량 감소, 부종, 갑작스러운 체중 증가가 있으면 알리도록 교육한다.';why='신장관류 저하의 징후를 대상자가 알면 조기에 발견하고 대처할 수 있다.'},
        @{plan='의사와 상의 없이 진통소염제(NSAIDs)나 한약 등을 복용하지 않도록 교육한다.';why='일부 약물과 성분은 신혈류를 감소시키거나 신장에 독성을 일으킬 수 있다.'})
}
$script:Templates['혈전증의 위험'] = @{
    en = 'Risk for thrombosis'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '혈전 위험'
    priority = 5
    reason = '아직 나타나지 않은 위험 진단이지만 혈전이 폐색전으로 진행하면 생명을 위협하므로 안전 요구로서 예방이 필요하다'
    evalData = '양측 하지 둘레 차이, 종아리 통증·발적·열감, D-dimer, 조기 보행 여부, 항응고제 투여 및 출혈 징후, 예방법 설명 여부'
    keywords = 'DVT|심부정맥|혈전|thromb|D-dimer|폐색전|pulmonary embol|Wells|헤파린|heparin|enoxaparin|에녹사파린|클렉산|와파린|warfarin|리바록사반|rivaroxaban|압박스타킹|\bIPC\b|고관절|슬관절 치환|\bTKR\b|\bTHR\b|\bTKA\b|심방세동|atrial fib|\bAF\b|장기 침상'
    cause = '장기간의 부동'
    long = '대상자는 퇴원 시까지 혈전 증상 없이 지낼 것이다.'
    short = @('대상자는 입원 기간 동안 양측 하지 둘레 차이가 2cm 미만으로 유지될 것이다.','대상자는 2일 내 혈전 예방 방법(하지 운동, 수분 섭취 등)을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매 듀티마다 하지의 부종, 통증, 발적, 열감을 사정하고 매일 양측 종아리 둘레를 측정한다.';why='심부정맥혈전은 한쪽 하지의 부종과 통증으로 나타나는 경우가 많아 양측을 비교하면 조기 발견에 도움이 된다.'},
        @{plan='호흡곤란, 흉통, 빈맥, SpO₂ 저하 등 폐색전 징후를 관찰한다.';why='하지 혈전이 떨어져 폐동맥을 막으면 갑작스러운 호흡곤란과 저산소증이 나타나므로 즉각적인 발견이 필요하다.'},
        @{plan='D-dimer, 혈소판, aPTT·PT(INR) 검사 결과를 확인한다.';why='D-dimer 상승은 혈전 형성을 시사하고, 응고 검사는 항응고 치료의 효과와 출혈 위험을 평가하는 데 쓰인다.'})
    ther = @(
        @{plan='금기가 아닐 시 조기 보행과 침상에서의 발목 펌프 운동을 격려한다.';why='종아리 근육의 수축은 정맥혈을 심장 쪽으로 밀어 올려 정맥 정체를 줄인다.'},
        @{plan='처방에 따라 압박스타킹이나 간헐적 공기압박기(IPC)를 적용하고 피부 상태를 확인한다.';why='외부 압박은 정맥 환류를 촉진하여 혈전 형성을 예방하며, 압박에 의한 피부 손상 여부를 함께 관찰해야 한다.'},
        @{plan='처방에 따라 항응고제(헤파린, 에녹사파린 등)를 투여하고 출혈 징후(잇몸 출혈, 혈뇨, 흑변, 멍)를 관찰한다.';why='항응고제는 응고 과정을 억제하여 혈전 형성을 예방하지만 출혈 위험을 높이므로 부작용 관찰이 필요하다.'},
        @{plan='금기가 아닐 시 하루 1,500~2,000mL의 수분 섭취를 격려한다.';why='탈수는 혈액 점도를 높여 혈전 형성을 촉진하므로 적절한 수분 공급이 필요하다.'},
        @{plan='무릎 밑에 베개를 받치거나 다리를 꼬지 않도록 한다.';why='슬와부 압박은 정맥 흐름을 방해하여 혈액 정체를 일으킨다.'})
    edu = @(
        @{plan='대상자와 보호자에게 한쪽 다리의 부종·통증, 갑작스러운 호흡곤란이나 흉통이 있으면 즉시 알리도록 교육한다.';why='혈전과 폐색전의 증상을 알면 빠르게 보고하여 치료를 받을 수 있다.'},
        @{plan='퇴원 후에도 장시간 앉아 있지 않고 1~2시간마다 걷거나 다리 운동을 하도록 교육한다.';why='지속적인 움직임은 정맥 정체를 줄여 퇴원 후 혈전 발생을 예방한다.'})
}
$script:Templates['쇼크의 위험'] = @{
    en = 'Risk for shock'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '4. 심혈관/호흡기계 반응 Cardiovascular/Pulmonary responses'
    page = $null
    problem = '쇼크 위험'
    priority = 2
    reason = '위험 진단이지만 쇼크로 진행하면 조직 관류가 급격히 저하되어 생명을 위협하므로 순환(ABC의 C) 문제로 우선 관리가 필요하다'
    evalData = '혈압·MAP·맥박, 소변량, 의식 수준, 피부색·온도·모세혈관 재충전 시간, 젖산(lactate)·Hb 추이'
    keywords = 'shock|쇼크|저혈압|hypotension|패혈|sepsis|septic|lactate|젖산|hemorrhage|대량 출혈|실혈|탈수|dehydration|\bMAP\b|빈맥|tachycardia|아나필락시스|anaphyla|모세혈관 재충전|\bCRT\b|식은땀|창백|qSOFA'
    cause = '체액 손실로 인한 순환혈액량 감소'
    long = '대상자는 퇴원 시까지 쇼크 증상 없이 안정된 활력징후를 유지할 것이다.'
    short = @('대상자는 입원 기간 동안 수축기 혈압 90mmHg 이상, MAP 65mmHg 이상을 유지할 것이다.','대상자는 입원 기간 동안 시간당 소변량을 0.5mL/kg 이상으로 유지할 것이다.')
    diag = @(
        @{plan='매 1~4시간마다 혈압, 맥박, 호흡, 체온, SpO₂와 의식 수준을 사정한다.';why='빈맥, 맥압 감소, 저혈압, 의식 변화는 보상기전이 한계에 이르고 있다는 쇼크의 초기 징후이다.'},
        @{plan='피부색, 피부 온도, 모세혈관 재충전 시간(2초 이내)과 시간당 소변량을 확인한다.';why='말초 순환과 신장 관류는 쇼크 시 가장 먼저 감소하므로 조직 관류 상태를 평가하는 지표가 된다.'},
        @{plan='Hb·Hct, 젖산, 전해질, 혈액배양 등 검사 결과를 확인한다.';why='Hb 감소는 출혈을, 젖산 상승은 조직 저산소증을 의미하여 쇼크의 원인과 진행을 파악할 수 있다.'})
    ther = @(
        @{plan='굵은 정맥 주사 경로를 확보하고 처방에 따라 수액이나 혈액을 투여한다.';why='빠른 수액·혈액 보충은 순환혈액량을 회복시켜 심박출량과 조직 관류를 유지한다.'},
        @{plan='처방에 따라 산소를 투여하여 SpO₂를 94% 이상으로 유지한다.';why='산소 공급을 늘리면 관류가 저하된 조직의 저산소 손상을 줄일 수 있다.'},
        @{plan='처방에 따라 승압제를 투여하고 혈압과 주사 부위의 혈관 외 유출을 관찰한다.';why='승압제는 혈관을 수축시켜 관류압을 높이지만, 혈관 외로 새면 조직 괴사가 생길 수 있다.'},
        @{plan='출혈 부위가 있으면 직접 압박하고 침습 부위의 출혈을 관찰한다.';why='출혈을 조기에 멈추면 순환혈액량 손실을 줄여 쇼크 진행을 예방한다.'},
        @{plan='혈압 저하, 의식 변화, 소변량 감소가 나타나면 즉시 보고한다.';why='쇼크는 짧은 시간에 진행하므로 신속한 보고와 처치가 예후를 좌우한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 어지러움, 식은땀, 가슴 두근거림, 의식 저하가 있으면 즉시 알리도록 교육한다.';why='대상자와 보호자가 쇼크의 초기 증상을 알면 빠르게 보고하여 조기 처치가 가능하다.'},
        @{plan='갑자기 일어나지 말고 천천히 체위를 바꾸도록 교육한다.';why='순환혈액량이 부족한 상태에서 급격한 체위 변경은 기립성 저혈압과 낙상을 일으킬 수 있다.'})
}
$script:Templates['목욕 자가간호 결핍'] = @{
    en = 'Bathing self-care deficit'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '5. 자가간호 Self-care'
    page = $null
    problem = '목욕 자가간호 결핍'
    priority = 4
    reason = '생명을 직접 위협하지는 않지만 개인위생은 피부 보호와 감염 예방에 필요한 기본 생리적 욕구이다'
    evalData = '목욕 시 스스로 할 수 있는 부분과 도움이 필요한 부분, 피부·구강 청결 상태, Barthel 지수(목욕 항목), 보조기구 사용 여부'
    keywords = '목욕|샤워|bath|씻지 못|씻기 힘|씻기 어려|씻을 수 없|세수|몸을 닦|머리를 감|체취|위생 상태 불량|개인위생'
    cause = '신체 기동성 저하'
    long = '대상자는 퇴원 시 보조기구나 최소한의 도움을 받아 스스로 목욕할 수 있을 것이다.'
    short = @('대상자는 3일 내 도움을 받아 세수와 상체 닦기를 스스로 수행할 것이다.','대상자는 1주일 내 목욕 보조기구를 사용하여 샤워에 참여할 것이다.')
    diag = @(
        @{plan='목욕 과정(물 조절, 몸 닦기, 헹구기, 말리기) 중 스스로 할 수 있는 부분과 도움이 필요한 부분을 사정한다.';why='대상자의 능력을 정확히 파악해야 필요한 부분만 도와 남은 기능을 유지할 수 있다.'},
        @{plan='근력, 관절가동범위, 균형, 피로 정도와 인지 상태를 사정한다.';why='목욕을 방해하는 신체적·인지적 원인을 알아야 알맞은 중재를 계획할 수 있다.'},
        @{plan='피부, 모발, 구강의 청결 상태와 피부 손상 여부를 관찰한다.';why='위생 상태는 자가간호 결핍의 정도를 보여주며 목욕 시간은 피부 문제를 발견하는 기회가 된다.'})
    ther = @(
        @{plan='목욕 전에 물품을 손이 닿는 곳에 준비하고 물 온도를 확인한다.';why='준비된 환경은 에너지 소모를 줄이고, 적절한 물 온도(약 40℃)는 화상을 예방한다.'},
        @{plan='대상자가 할 수 있는 부분은 스스로 하도록 하고 부족한 부분만 돕는다.';why='스스로 수행하는 경험은 남은 기능을 유지하고 독립성과 자존감을 높인다.'},
        @{plan='샤워 의자, 손잡이, 미끄럼 방지 매트 등 보조기구를 제공한다.';why='보조기구는 낙상 위험을 줄이고 대상자가 안전하게 목욕에 참여하도록 돕는다.'},
        @{plan='목욕 중 사생활을 보호하고 대상자가 원하는 시간에 맞추어 계획한다.';why='사생활 보호와 선호 존중은 수치심을 줄이고 협조를 높인다.'},
        @{plan='피로가 적은 시간에 목욕하도록 하고 중간에 휴식을 제공한다.';why='목욕은 에너지 소모가 큰 활동이므로 휴식을 주면 피로와 산소 요구 증가를 줄일 수 있다.'})
    edu = @(
        @{plan='대상자에게 보조기구를 이용한 안전한 목욕 방법을 교육한다.';why='올바른 보조기구 사용은 낙상을 예방하고 스스로 목욕할 수 있는 능력을 높인다.'},
        @{plan='보호자에게 대상자가 할 수 있는 부분은 스스로 하도록 기다려주는 방법을 교육한다.';why='과도한 도움은 의존성을 높이므로 보호자의 참여 방식이 독립성 회복에 중요하다.'})
}
$script:Templates['옷 입기 자가간호 결핍'] = @{
    en = 'Dressing self-care deficit'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '5. 자가간호 Self-care'
    page = $null
    problem = '옷 입기 자가간호 결핍'
    priority = 4
    reason = '생명을 직접 위협하지는 않지만 옷 입기는 체온 유지와 일상생활 수행에 필요한 기본 생리적 욕구이다'
    evalData = '옷 입고 벗기 시 스스로 할 수 있는 부분, 단추·지퍼 다루기 가능 여부, 보조기구 사용 여부, 옷 입기에 걸리는 시간'
    keywords = '옷 입|옷을 입|옷 갈아|옷을 갈아|옷을 벗|환의|단추|지퍼|양말|신발을 신|dressing self|self-care deficit'
    cause = '상지 근력 저하'
    long = '대상자는 퇴원 시 최소한의 도움으로 스스로 옷을 입고 벗을 수 있을 것이다.'
    short = @('대상자는 3일 내 도움을 받아 앞트임 상의를 스스로 입을 것이다.','대상자는 1주일 내 보조기구를 사용하여 하의와 양말을 스스로 입을 것이다.')
    diag = @(
        @{plan='옷 입기와 벗기 과정 중 스스로 할 수 있는 부분과 도움이 필요한 부분을 사정한다.';why='대상자의 능력을 정확히 알아야 필요한 부분만 도와 남은 기능을 유지할 수 있다.'},
        @{plan='상·하지 근력, 관절가동범위, 손의 미세운동 능력과 균형을 사정한다.';why='단추 채우기나 하의 입기는 손의 정교한 움직임과 균형이 필요하므로 이를 방해하는 원인을 파악해야 한다.'},
        @{plan='인지 상태와 옷 입는 순서를 이해하는지 확인한다.';why='인지 저하가 있으면 옷 입는 순서를 잊을 수 있어 단계별 지시가 필요한지 판단할 수 있다.'})
    ther = @(
        @{plan='앞트임, 고무줄 허리, 벨크로 등 입고 벗기 쉬운 옷을 준비한다.';why='간단한 옷은 손 기능이 떨어져도 스스로 입을 수 있게 하여 독립성을 높인다.'},
        @{plan='편마비가 있으면 옷을 입을 때는 마비된 쪽부터, 벗을 때는 건강한 쪽부터 하도록 돕는다.';why='마비 측부터 입히면 관절에 무리를 주지 않고 쉽게 옷을 입을 수 있다.'},
        @{plan='앉은 자세에서 옷을 입도록 하고 필요한 물품을 손이 닿는 곳에 둔다.';why='앉은 자세는 균형을 유지하기 쉬워 낙상을 예방하고 에너지 소모를 줄인다.'},
        @{plan='충분한 시간을 주고 대상자가 할 수 있는 부분은 스스로 하도록 격려한다.';why='서두르지 않는 환경과 격려는 성공 경험을 늘려 자신감과 독립성을 높인다.'})
    edu = @(
        @{plan='대상자에게 단추 고리, 긴 구둣주걱, 양말 보조기 등 보조기구 사용법을 교육한다.';why='보조기구는 부족한 손 기능과 관절 움직임을 보완하여 스스로 옷 입기를 가능하게 한다.'},
        @{plan='보호자에게 대상자가 스스로 옷을 입도록 기다려주고 필요한 부분만 돕는 방법을 교육한다.';why='보호자의 적절한 도움은 의존성을 줄이고 퇴원 후에도 자가간호 능력을 유지하게 한다.'})
}
$script:Templates['섭식 자가간호 결핍'] = @{
    en = 'Feeding self-care deficit'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '5. 자가간호 Self-care'
    page = $null
    problem = '섭식 자가간호 결핍'
    priority = 4
    reason = '스스로 먹지 못하면 영양과 수분 섭취가 부족해질 수 있어 기본 생리적 욕구 충족을 위해 관리가 필요하다'
    evalData = '스스로 섭취한 식사량, 식사 도구 사용 능력, 식사 시간, 사레 여부, 체중 변화'
    keywords = '식사 보조|식사를 도와|식사를 혼자|혼자 먹기|혼자 식사|혼자서 못 먹|숟가락|수저|젓가락|떠먹여|떠먹이|음식을 흘리|feeding|식사 시 도움|식이 보조'
    cause = '상지 근력 및 협응력 저하'
    long = '대상자는 퇴원 시 보조기구를 사용하여 스스로 식사할 수 있을 것이다.'
    short = @('대상자는 3일 내 도움을 받아 식사의 절반 이상을 스스로 섭취할 것이다.','대상자는 1주일 내 보조 식기를 사용하여 사레 없이 스스로 식사할 것이다.')
    diag = @(
        @{plan='식사 과정(음식 자르기, 도구 잡기, 입으로 가져가기, 씹기, 삼키기) 중 스스로 할 수 있는 부분을 사정한다.';why='어느 단계에 문제가 있는지 알아야 알맞은 도움과 보조기구를 제공할 수 있다.'},
        @{plan='손의 근력·떨림, 시력, 인지 상태와 연하 능력을 사정한다.';why='상지 기능과 연하 능력은 안전하게 스스로 먹을 수 있는지를 결정하며 연하 장애 시 흡인 위험이 있다.'},
        @{plan='매 식사 후 섭취량을 기록하고 주 1~2회 체중을 측정한다.';why='섭취량과 체중 변화는 자가간호 결핍이 영양 상태에 미치는 영향을 평가하는 지표가 된다.'})
    ther = @(
        @{plan='식사 전 손을 씻게 하고 상체를 60~90도로 세운 자세를 취하게 한다.';why='똑바로 앉은 자세는 음식이 기도로 넘어가는 것을 막아 흡인을 예방하고 스스로 먹기 쉽게 한다.'},
        @{plan='손잡이가 굵은 숟가락, 미끄럼 방지 매트, 테두리가 있는 접시 등 보조 식기를 제공한다.';why='보조 식기는 약한 손 힘과 떨림을 보완하여 대상자가 스스로 먹을 수 있게 한다.'},
        @{plan='음식을 한입 크기로 준비하고 식판의 위치를 대상자에게 알려준다.';why='준비된 음식과 위치 안내는 에너지 소모를 줄이고 시력이 약한 대상자도 스스로 먹도록 돕는다.'},
        @{plan='충분한 식사 시간을 주고 대상자가 할 수 있는 부분은 스스로 하도록 격려한다.';why='서두르지 않는 환경은 사레를 줄이고 성공 경험을 통해 독립성을 높인다.'},
        @{plan='식사 후 30분 정도 앉은 자세를 유지하고 구강 간호를 제공한다.';why='식후 앉은 자세는 역류와 흡인을 예방하고 구강 간호는 남은 음식물로 인한 감염을 막는다.'})
    edu = @(
        @{plan='대상자에게 보조 식기 사용법과 천천히 작게 먹는 방법을 교육한다.';why='올바른 식사 방법은 사레를 예방하고 스스로 먹는 능력을 높인다.'},
        @{plan='보호자에게 식사 시 바른 자세와 사레 징후(기침, 목소리 변화)를 관찰하는 방법을 교육한다.';why='보호자가 안전한 식사 보조 방법을 알면 퇴원 후에도 흡인을 예방할 수 있다.'})
}
$script:Templates['용변 자가간호 결핍'] = @{
    en = 'Toileting self-care deficit'
    domain = '4. 활동/휴식 Activity/Rest'
    cls = '5. 자가간호 Self-care'
    page = $null
    problem = '용변 자가간호 결핍'
    priority = 4
    reason = '배설은 기본 생리적 욕구이며 스스로 하지 못하면 실금, 피부 손상, 낙상으로 이어질 수 있다'
    evalData = '화장실 이동·옷 내리기·뒤처리 등 스스로 할 수 있는 부분, 실금 횟수, 배뇨·배변 양상, 회음부 피부 상태'
    keywords = '화장실|변기|이동식 변기|이동변기|기저귀|diaper|bedpan|변기 사용|용변|소변통|urinal|toileting|뒤처리|실금'
    cause = '이동 능력 저하'
    long = '대상자는 퇴원 시 최소한의 도움으로 안전하게 용변을 볼 수 있을 것이다.'
    short = @('대상자는 3일 내 도움을 받아 이동식 변기나 화장실을 사용할 것이다.','대상자는 1주일 내 실금 없이 배설 요구를 미리 표현할 것이다.')
    diag = @(
        @{plan='화장실 이동, 옷 내리고 올리기, 변기에 앉고 일어나기, 뒤처리 중 스스로 할 수 있는 부분을 사정한다.';why='어느 단계에 도움이 필요한지 알아야 대상자의 기능을 유지하면서 안전하게 도울 수 있다.'},
        @{plan='배뇨·배변 횟수, 시간, 양상과 실금 여부를 기록한다.';why='배설 양상을 알면 규칙적인 배설 시간을 계획하여 실금을 줄일 수 있다.'},
        @{plan='근력, 균형, 인지 상태와 회음부 피부 상태를 사정한다.';why='이동 능력과 인지 저하는 낙상과 실금의 원인이 되고, 실금은 회음부 피부 손상을 일으킬 수 있다.'})
    ther = @(
        @{plan='호출벨과 소변기, 이동식 변기를 손이 닿는 곳에 둔다.';why='배설 요구가 있을 때 바로 도움을 요청하거나 사용할 수 있어 실금과 낙상을 예방한다.'},
        @{plan='대상자의 배설 양상에 맞추어 2~3시간마다 또는 식후에 화장실 이용을 돕는다.';why='규칙적인 배설 시간은 방광과 장의 습관을 만들어 실금을 줄인다.'},
        @{plan='화장실에 손잡이와 높은 변기 시트를 설치하고 이동 시 함께한다.';why='보조 설비와 동행은 앉고 일어설 때의 낙상 위험을 줄인다.'},
        @{plan='용변 시 사생활을 보호하고 충분한 시간을 준다.';why='사생활 보호는 수치심을 줄여 배설을 참지 않게 하고 원활한 배설을 돕는다.'},
        @{plan='배설 후 회음부를 깨끗이 닦고 건조하게 유지한다.';why='습기와 배설물은 피부를 자극하여 실금 관련 피부염을 일으킬 수 있다.'})
    edu = @(
        @{plan='대상자에게 배설 요구가 있으면 참지 말고 바로 호출벨을 누르도록 교육한다.';why='도움 없이 급하게 이동하면 낙상 위험이 높고 참으면 실금이 생길 수 있다.'},
        @{plan='보호자에게 안전한 이동 보조 방법과 이동식 변기 사용법을 교육한다.';why='보호자가 올바른 보조 방법을 알면 퇴원 후에도 안전하게 배설을 도울 수 있다.'})
}
$script:Templates['편측 무시'] = @{
    en = 'Unilateral neglect'
    domain = '5. 지각/인지 Perception/Cognition'
    cls = '1. 주의 Attention'
    page = $null
    problem = '편측 무시'
    priority = 5
    reason = '한쪽 공간과 신체를 인식하지 못해 낙상과 손상의 위험이 높으므로 안전 요구로서 관리가 필요하다'
    evalData = '무시 측에 대한 인식 정도(선 나누기·그림 그리기 검사), 무시 측 신체 손상 여부, 고개를 돌려 주변을 살피는지, 낙상 발생 여부'
    keywords = '편측 ?무시|unilateral neglect|hemi-?neglect|한쪽을 인식|왼쪽을 인식|왼쪽을 못 보|왼쪽 음식을 남|우측 두정엽|right parietal|두정엽|parietal|반맹|hemianopia|좌측 편마비|left hemipleg'
    cause = '우측 대뇌반구 손상'
    long = '대상자는 퇴원 시 무시 측을 살피는 방법을 사용하여 손상 없이 일상생활을 할 수 있을 것이다.'
    short = @('대상자는 3일 내 간호사의 지시에 따라 고개를 돌려 무시 측을 살필 것이다.','대상자는 1주일 내 식사 시 식판의 양쪽 음식을 모두 섭취할 것이다.')
    diag = @(
        @{plan='매 듀티마다 무시 측 신체와 공간에 대한 인식 정도(식사 시 한쪽 음식 남김, 한쪽만 옷 입기 등)를 관찰한다.';why='편측 무시의 정도를 파악해야 알맞은 중재를 계획하고 호전 여부를 평가할 수 있다.'},
        @{plan='무시 측 팔다리의 위치, 피부 손상, 부종 여부를 확인한다.';why='대상자는 무시 측 팔다리가 눌리거나 다쳐도 알아차리지 못하므로 간호사가 직접 확인해야 한다.'},
        @{plan='시야 결손(반맹)과 감각 저하 여부를 사정한다.';why='시야 결손은 편측 무시와 함께 나타나기 쉬우며 이를 구분해야 알맞은 환경 조정이 가능하다.'})
    ther = @(
        @{plan='급성기에는 호출벨, 물, 자주 쓰는 물건을 인식하는 쪽에 둔다.';why='인식하는 쪽에 물건을 두면 필요할 때 쉽게 찾을 수 있어 안전과 독립성을 높인다.'},
        @{plan='상태가 안정되면 무시 측에서 말을 걸고 무시 측으로 고개를 돌려 살피도록(스캐닝) 반복 격려한다.';why='무시 측으로 주의를 유도하는 반복 훈련은 공간 인식을 높이는 데 도움이 된다.'},
        @{plan='무시 측 팔다리를 베개로 지지하여 바른 위치에 두고 침대 난간 등에 끼지 않도록 한다.';why='무시 측 사지는 잘못된 자세로 방치되기 쉬워 탈구, 부종, 압박 손상을 일으킬 수 있다.'},
        @{plan='침상 주변 장애물을 치우고 침대를 낮게 유지하며 이동 시 무시 측에서 보조한다.';why='대상자는 무시 측 장애물을 인식하지 못하므로 환경 정리와 보조로 낙상을 예방한다.'},
        @{plan='식사 시 식판을 돌려주거나 무시 측 음식의 위치를 알려준다.';why='무시 측 음식을 인식하지 못해 섭취량이 줄어드는 것을 막아 영양을 유지한다.'})
    edu = @(
        @{plan='대상자에게 고개를 돌려 양쪽을 확인하는 습관과 거울을 이용한 확인 방법을 교육한다.';why='스스로 무시 측을 살피는 방법을 익히면 일상생활 중 손상을 줄일 수 있다.'},
        @{plan='보호자에게 무시 측 팔다리의 위치를 확인하고 무시 측으로 주의를 유도하는 방법을 교육한다.';why='보호자의 참여로 퇴원 후에도 손상을 예방하고 재활 효과를 높일 수 있다.'})
}
$script:Templates['급성 혼돈'] = @{
    en = 'Acute confusion'
    domain = '5. 지각/인지 Perception/Cognition'
    cls = '4. 인지 Cognition'
    page = $null
    problem = '급성 혼돈(섬망)'
    priority = 5
    reason = '갑작스러운 의식·주의력 변화로 낙상, 라인 제거 등 손상 위험이 높아 안전 요구로서 신속한 관리가 필요하다'
    evalData = 'CAM(또는 CAM-ICU) 결과, 시간·장소·사람에 대한 지남력, 수면-각성 양상, 초조 행동, 라인·튜브 유지 여부'
    keywords = '섬망|delirium|CAM-ICU|\bCAM\b|지남력 ?저하|disorient|혼돈|confus|횡설수설|헛것|환시|hallucinat|안절부절|라인을 뽑|수액줄을 뽑|억제대|restrain|할로페리돌|haloperidol|쿠에티아핀|quetiapine|\bRASS\b'
    cause = '수술 및 급성 질환으로 인한 생리적 변화'
    long = '대상자는 퇴원 시 시간, 장소, 사람에 대한 지남력을 회복할 것이다.'
    short = @('대상자는 3일 내 CAM 결과가 음성으로 확인될 것이다.','대상자는 입원 기간 동안 라인과 튜브를 스스로 제거하지 않을 것이다.')
    diag = @(
        @{plan='매 듀티마다 CAM(또는 CAM-ICU)을 이용해 섬망 여부와 의식 수준, 지남력을 사정한다.';why='섬망은 하루 중에도 증상이 변하므로 표준화된 도구로 반복 사정해야 조기에 발견할 수 있다.'},
        @{plan='SpO₂, 혈당, 전해질, 감염 지표, 통증, 배뇨·배변 상태 등 섬망의 원인 요인을 확인한다.';why='섬망은 저산소증, 대사 이상, 감염, 통증, 요정체 등 신체적 원인으로 생기므로 원인을 찾아 교정해야 한다.'},
        @{plan='투약 목록에서 진정제, 항콜린제, 마약성 진통제 등 섬망을 일으킬 수 있는 약물을 확인한다.';why='일부 약물은 중추신경계에 작용하여 섬망을 일으키거나 악화시킬 수 있다.'})
    ther = @(
        @{plan='시계, 달력을 보이는 곳에 두고 대화할 때마다 날짜, 장소, 간호사 이름을 자연스럽게 알려준다.';why='반복적인 현실 감각 제공은 지남력 회복을 돕고 혼란으로 인한 불안을 줄인다.'},
        @{plan='낮에는 커튼을 열어 밝게 하고 밤에는 소음과 조명을 줄여 수면을 돕는다.';why='낮과 밤의 구분은 수면-각성 주기를 회복시켜 섬망을 완화한다.'},
        @{plan='안경, 보청기를 착용하게 하고 가족의 방문과 익숙한 물건을 두도록 한다.';why='감각 결손을 보완하고 친숙한 자극을 주면 환경을 정확히 인식하는 데 도움이 된다.'},
        @{plan='침대를 낮추고 호출벨을 가까이 두며 라인과 튜브는 보이지 않게 고정한다.';why='혼돈 상태에서는 낙상과 기구 자가 제거 위험이 높으므로 환경을 안전하게 조성한다.'},
        @{plan='처방에 따라 항정신병 약물을 투여하고 과진정, 추체외로 증상, QT 연장을 관찰한다.';why='약물은 심한 초조 증상을 줄이지만 부작용이 있어 최소 용량 사용과 관찰이 필요하다.'})
    edu = @(
        @{plan='보호자에게 섬망은 대부분 원인이 치료되면 회복되는 일시적인 상태임을 설명한다.';why='정확한 정보는 보호자의 불안을 줄이고 대상자를 안정시키는 데 협력하게 한다.'},
        @{plan='보호자에게 차분한 목소리로 짧게 말하고 지남력을 알려주는 방법을 교육한다.';why='익숙한 사람의 안정된 의사소통은 대상자의 혼란과 초조를 줄인다.'})
}
$script:Templates['급성 혼돈의 위험'] = @{
    en = 'Risk for acute confusion'
    domain = '5. 지각/인지 Perception/Cognition'
    cls = '4. 인지 Cognition'
    page = $null
    problem = '급성 혼돈 위험'
    priority = 5
    reason = '아직 나타나지 않은 위험 진단이지만 섬망이 생기면 낙상, 입원 기간 연장 등으로 이어지므로 안전 요구로서 예방이 필요하다'
    evalData = 'CAM 결과, 지남력, 수면 시간과 양상, 통증 조절 정도, 전해질·SpO₂ 등 위험 요인 교정 여부'
    keywords = '고령|치매|dementia|중환자실|\bICU\b|수면 박탈|잠을 못|진정제|벤조디아제핀|benzodiazepine|로라제팜|lorazepam|미다졸람|midazolam|마약성|opioid|알코올|alcohol|금단|withdrawal|저나트륨|hyponatremia|탈수|고관절 골절'
    cause = '고령 및 낯선 입원 환경'
    long = '대상자는 퇴원 시까지 급성 혼돈 없이 지남력을 유지할 것이다.'
    short = @('대상자는 입원 기간 동안 매 듀티 CAM 결과가 음성으로 유지될 것이다.','대상자는 3일 내 밤에 5시간 이상 잠을 잘 것이다.')
    diag = @(
        @{plan='매 듀티마다 CAM을 이용해 의식 수준, 주의력, 지남력을 사정한다.';why='섬망의 초기 변화를 빨리 발견하면 원인을 교정하여 진행을 막을 수 있다.'},
        @{plan='고령, 인지 저하, 감각 결손, 탈수, 통증, 수면 부족 등 위험 요인을 확인한다.';why='위험 요인이 많을수록 섬망 발생 가능성이 높아 예방 중재의 대상을 정할 수 있다.'},
        @{plan='전해질, 혈당, SpO₂ 검사 결과와 투약 목록(진정제, 항콜린제 등)을 확인한다.';why='대사 이상과 특정 약물은 섬망의 흔한 유발 요인이므로 미리 확인하여 교정한다.'})
    ther = @(
        @{plan='시계와 달력을 보이는 곳에 두고 하루 일정과 장소를 자주 알려준다.';why='현실 감각을 유지하면 낯선 환경에서 생기는 혼란을 예방한다.'},
        @{plan='밤에는 조명과 소음을 줄이고 야간 처치를 가능한 한 묶어서 시행한다.';why='수면 방해를 줄이면 수면-각성 주기가 유지되어 섬망 발생 위험이 낮아진다.'},
        @{plan='안경, 보청기를 착용하게 하고 금기가 아닐 시 낮 동안 조기 보행을 격려한다.';why='감각 보완과 신체 활동은 환경 인식을 높이고 섬망 예방에 효과적이다.'},
        @{plan='금기가 아닐 시 충분한 수분 섭취를 격려하고 통증을 적절히 조절한다.';why='탈수와 조절되지 않는 통증은 섬망의 주요 유발 요인이다.'})
    edu = @(
        @{plan='보호자에게 대상자의 말이나 행동이 갑자기 달라지면 바로 알리도록 교육한다.';why='보호자는 평소 모습을 잘 알기 때문에 작은 변화를 빨리 발견할 수 있다.'},
        @{plan='보호자에게 자주 방문하여 익숙한 대화와 물건으로 안정감을 주도록 교육한다.';why='친숙한 사람과 물건은 낯선 환경에서의 불안을 줄이고 지남력 유지를 돕는다.'})
}
$script:Templates['만성 혼돈'] = @{
    en = 'Chronic confusion'
    domain = '5. 지각/인지 Perception/Cognition'
    cls = '4. 인지 Cognition'
    page = $null
    problem = '만성 혼돈'
    priority = 5
    reason = '지속적인 인지 저하로 배회, 낙상, 투약 오류 등 손상 위험이 높아 안전 요구로서 관리가 필요하다'
    evalData = 'K-MMSE 등 인지 기능 점수, 지남력, 일상생활 수행 정도, 배회·초조 행동 빈도, 손상 발생 여부'
    keywords = '치매|dementia|알츠하이머|Alzheimer|K-?MMSE|MMSE|인지 ?저하|인지장애|cognitive impair|혈관성 치매|배회|wandering|도네페질|donepezil|아리셉트|메만틴|memantine|리바스티그민|rivastigmine'
    cause = '진행성 신경인지장애'
    long = '대상자는 퇴원 시 손상 없이 현재의 인지 기능 수준에서 일상생활을 유지할 것이다.'
    short = @('대상자는 입원 기간 동안 배회나 낙상으로 인한 손상 없이 지낼 것이다.','대상자는 1주일 내 도움을 받아 정해진 일과(식사, 세면)를 일정한 시간에 수행할 것이다.')
    diag = @(
        @{plan='K-MMSE 등을 이용해 인지 기능과 지남력을 사정하고 평소 상태와 비교한다.';why='기저 인지 수준을 알아야 갑작스러운 악화(섬망 동반)를 구별하고 중재 효과를 평가할 수 있다.'},
        @{plan='일상생활 수행 능력과 배회, 초조, 공격 행동의 빈도와 유발 요인을 관찰한다.';why='행동 증상의 유발 요인을 알면 이를 줄이는 환경과 중재를 계획할 수 있다.'},
        @{plan='통증, 배고픔, 배설 요구 등 표현하지 못하는 불편감을 사정한다.';why='인지 저하 대상자는 불편감을 말로 표현하기 어려워 초조 행동으로 나타나는 경우가 많다.'})
    ther = @(
        @{plan='일정한 일과와 같은 간호사가 돌보도록 하여 환경 변화를 최소화한다.';why='예측 가능한 일과와 익숙한 사람은 혼란과 불안을 줄인다.'},
        @{plan='짧고 쉬운 문장으로 한 번에 한 가지씩 말하고 충분히 기다린다.';why='정보 처리 능력이 떨어진 대상자도 이해하고 따라 할 수 있게 한다.'},
        @{plan='침대를 낮추고 이름표와 사진 등으로 병실과 화장실을 쉽게 찾도록 표시한다.';why='시각적 단서와 안전한 환경은 배회와 낙상으로 인한 손상을 예방한다.'},
        @{plan='대상자가 할 수 있는 일상 활동은 스스로 하도록 격려한다.';why='남은 기능을 사용하게 하면 기능 저하 속도를 늦추고 자존감을 유지한다.'},
        @{plan='처방에 따라 인지기능 개선제(도네페질 등)를 투여하고 오심, 설사, 서맥을 관찰한다.';why='콜린에스테라아제 억제제는 인지 저하 진행을 늦추는 데 도움을 주지만 위장관·심장 부작용이 생길 수 있다.'})
    edu = @(
        @{plan='보호자에게 집 안의 위험 요소를 줄이고 배회에 대비하는 방법(인식표, 문 잠금장치)을 교육한다.';why='안전한 환경을 만들면 퇴원 후 손상과 실종을 예방할 수 있다.'},
        @{plan='보호자에게 치매안심센터 등 지역사회 지원 자원을 안내한다.';why='장기적인 돌봄에는 보호자 혼자 감당하기 어려우므로 공적 지원 연계가 필요하다.'})
}
$script:Templates['기억력 장애'] = @{
    en = 'Impaired memory'
    domain = '5. 지각/인지 Perception/Cognition'
    cls = '4. 인지 Cognition'
    page = $null
    problem = '기억력 장애'
    priority = 7
    reason = '생명을 직접 위협하지는 않지만 투약과 자가관리를 잊게 하여 건강관리에 영향을 주므로 생리적·안전 문제 다음으로 다룬다'
    evalData = '최근 사건·정보 회상 정도, 투약 및 일정 수행 여부, 기억 보조 도구 사용 여부, 인지 기능 검사 결과'
    keywords = '기억력|기억이 안|기억 못|기억하지 못|잊어버|깜빡|건망|memory|amnesia|기억상실|\bMCI\b|경도인지장애|약 먹은 걸 잊|약을 잊'
    cause = '신경학적 손상'
    long = '대상자는 퇴원 시 기억 보조 도구를 사용하여 일상생활과 투약을 스스로 관리할 것이다.'
    short = @('대상자는 3일 내 메모나 알람을 사용하여 정해진 시간에 약을 복용할 것이다.','대상자는 1주일 내 기억을 돕는 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='최근 기억과 과거 기억, 일상생활에서 잊는 일의 종류와 빈도를 사정한다.';why='기억 장애의 양상을 알아야 어떤 부분을 보조해야 하는지 계획할 수 있다.'},
        @{plan='기억력에 영향을 주는 요인(수면 부족, 우울, 약물, 갑상선 기능, 비타민 B12 등)을 확인한다.';why='일부 기억력 저하는 교정 가능한 원인으로 생기므로 이를 찾으면 회복이 가능하다.'},
        @{plan='투약, 식사, 진료 일정 등을 스스로 수행하고 있는지 확인한다.';why='기억력 장애가 자가관리에 미치는 영향을 파악해야 안전을 지킬 수 있다.'})
    ther = @(
        @{plan='달력, 메모장, 알람, 약 정리함 등 기억 보조 도구를 제공한다.';why='외부 기억 보조 도구는 부족한 기억을 보완하여 독립적인 생활을 돕는다.'},
        @{plan='새로운 정보는 짧게 나누어 반복 설명하고 대상자가 다시 말해보게 한다.';why='반복과 되말하기는 정보를 장기 기억으로 옮기는 데 도움이 된다.'},
        @{plan='일정한 일과를 유지하고 물건은 정해진 자리에 두도록 한다.';why='규칙적인 생활과 정리된 환경은 기억에 의존하는 부담을 줄인다.'},
        @{plan='기억하지 못하는 일에 대해 질책하지 않고 성공한 경험을 칭찬한다.';why='부정적 반응은 불안을 높여 기억력을 더 떨어뜨리고, 칭찬은 참여 동기를 높인다.'})
    edu = @(
        @{plan='대상자에게 메모, 알람, 약 정리함 등 기억 보조 도구 사용법을 교육한다.';why='스스로 보조 도구를 사용하면 퇴원 후에도 투약과 일정 관리를 할 수 있다.'},
        @{plan='보호자에게 투약 여부를 함께 확인하고 기억 변화가 심해지면 진료받도록 교육한다.';why='보호자의 확인은 투약 오류를 막고 인지 저하의 진행을 조기에 발견하게 한다.'})
}
$script:Templates['언어적 의사소통 장애'] = @{
    en = 'Impaired verbal communication'
    domain = '5. 지각/인지 Perception/Cognition'
    cls = '5. 의사소통 Communication'
    page = $null
    problem = '의사소통 장애'
    priority = 6
    reason = '생리적 문제는 아니지만 요구를 전달하지 못하면 고립감과 좌절이 커지고 안전에도 영향을 주므로 사회적 욕구로서 관리가 필요하다'
    evalData = '이해 능력과 표현 능력, 대체 의사소통 수단 사용 여부, 요구 전달 성공 정도, 좌절 표현 여부'
    keywords = '실어증|aphasia|구음장애|dysarthria|발음이 어눌|말이 어눌|말을 못|말하기 어려|말이 안 나|기관절개|tracheostomy|기관 ?내관|intubat|브로카|Broca|베르니케|Wernicke|통역|청력 저하|보청기'
    cause = '뇌의 언어 중추 손상'
    long = '대상자는 퇴원 시 효과적인 의사소통 방법을 사용하여 자신의 요구를 전달할 수 있을 것이다.'
    short = @('대상자는 3일 내 그림판이나 손짓 등 대체 방법으로 기본 요구(물, 화장실, 통증)를 표현할 것이다.','대상자는 1주일 내 간호사와의 의사소통에서 좌절감이 줄었다고 표현할 것이다.')
    diag = @(
        @{plan='말을 이해하는 능력과 표현하는 능력, 읽기·쓰기 능력을 사정한다.';why='실어증의 유형(이해 장애, 표현 장애)을 알아야 알맞은 의사소통 방법을 선택할 수 있다.'},
        @{plan='청력, 시력, 구강·인두 근육 기능과 인공기도 여부를 확인한다.';why='감각 결손이나 구음 기관 문제, 인공기도는 의사소통을 방해하는 원인이 된다.'},
        @{plan='의사소통 시 대상자의 비언어적 표현(표정, 몸짓)과 좌절 반응을 관찰한다.';why='비언어적 신호는 대상자의 요구와 감정을 이해하는 중요한 단서가 된다.'})
    ther = @(
        @{plan='조용한 환경에서 대상자를 마주 보고 천천히 짧은 문장으로 말한다.';why='방해 자극을 줄이고 얼굴을 보며 말하면 입 모양과 표정을 함께 이해할 수 있다.'},
        @{plan='예/아니오로 답할 수 있는 질문을 사용하고 충분히 기다린다.';why='간단한 질문과 기다림은 대상자의 표현 부담을 줄이고 의사소통 성공을 높인다.'},
        @{plan='그림판, 글자판, 필기도구 등 대체 의사소통 도구를 제공한다.';why='대체 수단은 말로 표현하기 어려운 요구를 전달할 수 있게 한다.'},
        @{plan='호출벨을 손이 닿는 곳에 두고 자주 방문하여 요구를 확인한다.';why='도움을 요청하기 어려운 대상자의 안전을 지키고 고립감을 줄인다.'},
        @{plan='처방에 따라 언어치료를 연계하고 치료 내용을 일상 대화에서 연습하게 한다.';why='전문적인 언어치료와 반복 연습은 언어 기능 회복을 돕는다.'})
    edu = @(
        @{plan='보호자에게 천천히 말하기, 예/아니오 질문, 그림판 사용 등 의사소통 방법을 교육한다.';why='보호자가 효과적인 방법을 알면 대상자와의 의사소통이 원활해지고 좌절이 줄어든다.'},
        @{plan='대상자에게 말하기 연습을 서두르지 않고 꾸준히 하도록 격려한다.';why='꾸준한 연습은 언어 기능 회복을 돕고 성공 경험은 자신감을 높인다.'})
}
$script:Templates['절망감'] = @{
    en = 'Hopelessness'
    domain = '6. 자기지각 Self-perception'
    cls = '1. 자아개념 Self-concept'
    page = $null
    problem = '절망감'
    priority = 6
    reason = '생리적·안전 요구는 아니지만 절망감은 치료 참여를 떨어뜨리고 자해 위험과 연결될 수 있어 심리사회적 문제로 관리가 필요하다'
    evalData = '희망 관련 표현, 치료·일상 활동 참여 정도, 식사·수면 양상, 우울 척도 점수, 자살 사고 유무'
    keywords = '절망|희망이 없|희망이 안|소용없|살 이유|살고 싶지|의미가 없|나아질 것 같지|hopeless|무기력|체념|\bPHQ|말기|terminal|재발'
    cause = '장기간의 질병으로 인한 신체 상태 악화'
    long = '대상자는 퇴원 시 미래에 대한 희망과 현실적인 목표를 말로 표현할 것이다.'
    short = @('대상자는 3일 내 자신의 감정을 간호사에게 말로 표현할 것이다.','대상자는 1주일 내 스스로 정한 작은 목표를 한 가지 이상 달성할 것이다.')
    diag = @(
        @{plan='대상자의 언어적·비언어적 절망 표현(체념하는 말, 눈 맞춤 회피, 무관심)을 관찰한다.';why='절망감의 표현을 파악해야 정서 상태를 이해하고 중재의 필요성을 판단할 수 있다.'},
        @{plan='식사, 수면, 활동 참여 정도와 PHQ-9 등 우울 척도로 우울 정도를 사정한다.';why='절망감은 우울과 함께 나타나기 쉬우며 신체 기능에도 영향을 준다.'},
        @{plan='자해나 자살에 대한 생각이 있는지 직접적으로 질문한다.';why='절망감은 자살의 주요 위험 요인이므로 직접 질문하여 위험을 조기에 파악해야 한다.'})
    ther = @(
        @{plan='치료적 관계를 형성하고 대상자가 감정을 표현할 수 있도록 경청한다.';why='공감적 경청은 대상자가 이해받고 있다고 느끼게 하여 정서적 부담을 줄인다.'},
        @{plan='대상자와 함께 실현 가능한 작은 목표를 정하고 달성하면 칭찬한다.';why='작은 성공 경험은 통제감과 자신감을 회복시켜 희망을 키운다.'},
        @{plan='대상자가 과거에 어려움을 이겨냈던 경험과 강점을 떠올리게 한다.';why='자신의 강점과 대처 경험을 인식하면 현재 상황에 대처할 수 있다는 믿음이 생긴다.'},
        @{plan='가족, 종교, 의미 있는 사람과의 만남을 격려한다.';why='지지 체계와 영적 자원은 삶의 의미와 희망을 찾는 데 도움이 된다.'},
        @{plan='자살 위험이 확인되면 즉시 보고하고 주변의 위험한 물건을 치운다.';why='자살 위험은 안전을 직접 위협하므로 신속한 보고와 환경 관리가 필요하다.'})
    edu = @(
        @{plan='대상자에게 질병과 치료 과정에 대해 정확하고 이해하기 쉬운 정보를 제공한다.';why='정확한 정보는 막연한 두려움을 줄이고 현실적인 기대를 갖게 한다.'},
        @{plan='보호자에게 대상자의 감정을 비난 없이 들어주고 자해 신호가 보이면 알리도록 교육한다.';why='보호자의 지지는 정서 회복을 돕고 위험 신호를 조기에 발견하게 한다.'})
}
$script:Templates['상황적 자존감 저하'] = @{
    en = 'Situational low self-esteem'
    domain = '6. 자기지각 Self-perception'
    cls = '2. 자존감 Self-esteem'
    page = $null
    problem = '자존감 저하'
    priority = 6
    reason = '생리적·안전 요구는 아니지만 현재 상황으로 생긴 부정적 자기평가는 회복 의지와 치료 참여에 영향을 주므로 심리사회적 문제로 관리가 필요하다'
    evalData = '자신에 대한 긍정적·부정적 표현, 눈 맞춤과 자세, 자가간호와 의사결정 참여 정도, 자신의 강점 표현 여부'
    keywords = '자존감|자존심|쓸모없|짐이 되|짐만 되|부끄러|창피|실직|해고|자신감이 없|자신이 없|무능|한심|self-esteem'
    cause = '질병으로 인한 기능 및 역할 상실'
    long = '대상자는 퇴원 시 자신에 대해 긍정적으로 표현할 것이다.'
    short = @('대상자는 3일 내 자신의 감정과 걱정을 간호사에게 말로 표현할 것이다.','대상자는 1주일 내 자신의 강점을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='대상자가 자신에 대해 말하는 내용(부정적 표현, 자기비하)과 비언어적 행동(눈 맞춤 회피, 구부정한 자세)을 관찰한다.';why='자기평가의 내용과 행동을 파악하면 자존감 저하의 정도를 알 수 있다.'},
        @{plan='자존감 저하를 일으킨 최근 상황(질병, 기능 상실, 역할 변화 등)을 확인한다.';why='상황적 요인을 알아야 대상자가 받아들이고 적응하도록 도울 방향을 정할 수 있다.'},
        @{plan='대상자의 대처 방식과 지지 체계를 사정한다.';why='효과적인 대처 자원은 자존감 회복을 돕는 기반이 된다.'})
    ther = @(
        @{plan='대상자의 감정을 있는 그대로 받아들이고 비판 없이 경청한다.';why='수용적인 태도는 대상자가 존중받는다고 느끼게 하여 자기 가치를 회복하게 돕는다.'},
        @{plan='대상자가 자신의 강점과 잘한 일을 찾도록 돕고 구체적으로 칭찬한다.';why='긍정적 피드백은 부정적 자기평가를 바꾸는 데 도움이 된다.'},
        @{plan='간호 계획과 일상 활동에 대상자가 스스로 선택하고 참여하게 한다.';why='스스로 결정하고 해내는 경험은 통제감과 자신감을 높인다.'},
        @{plan='부정적인 생각을 현실적인 생각으로 바꾸어 보도록 함께 이야기한다.';why='왜곡된 자기평가를 현실적으로 바라보면 자존감 회복에 도움이 된다.'})
    edu = @(
        @{plan='대상자에게 현재 상황에 적응하는 대처 방법(문제 해결, 도움 요청, 이완)을 교육한다.';why='효과적인 대처 기술은 상황 변화로 인한 스트레스를 줄이고 자신감을 높인다.'},
        @{plan='보호자에게 대상자의 작은 변화와 노력을 인정하고 칭찬하도록 교육한다.';why='가족의 지지와 인정은 대상자의 자존감 회복에 중요한 역할을 한다.'})
}
$script:Templates['만성적 자존감 저하'] = @{
    en = 'Chronic low self-esteem'
    domain = '6. 자기지각 Self-perception'
    cls = '2. 자존감 Self-esteem'
    page = $null
    problem = '만성적 자존감 저하'
    priority = 6
    reason = '생리적·안전 요구는 아니지만 오랫동안 지속된 부정적 자기평가는 대인관계와 건강행위 전반에 영향을 주므로 심리사회적 문제로 관리가 필요하다'
    evalData = '자신에 대한 표현 내용, 자기비하 빈도, 대인관계·활동 참여 정도, 자신의 강점 표현 여부'
    keywords = '열등감|늘 실패|항상 실패|나는 안 돼|난 안 돼|가치 없|무가치|쓸모없|자기비하|자존감|self-esteem|worthless|칭찬을 거부|남의 눈치'
    cause = '반복된 실패 경험'
    long = '대상자는 퇴원 시 자신의 가치를 인정하는 말을 표현할 것이다.'
    short = @('대상자는 1주일 내 자신의 강점을 두 가지 이상 말로 표현할 것이다.','대상자는 1주일 내 하루 한 가지 이상의 활동에 스스로 참여할 것이다.')
    diag = @(
        @{plan='대상자가 자신에 대해 말하는 내용과 자기비하 표현의 빈도를 관찰한다.';why='부정적 자기평가의 정도와 지속성을 알면 중재의 필요성과 효과를 평가할 수 있다.'},
        @{plan='과거 경험, 성장 환경, 지지 체계 등 자존감 저하와 관련된 배경을 사정한다.';why='오랜 기간 형성된 자기평가는 과거 경험과 관련이 깊어 이를 이해해야 중재 방향을 정할 수 있다.'},
        @{plan='우울 증상과 자해 생각이 있는지 확인한다.';why='만성적 자존감 저하는 우울과 함께 나타나는 경우가 많아 안전 확인이 필요하다.'})
    ther = @(
        @{plan='일관되고 수용적인 태도로 치료적 관계를 형성한다.';why='일관된 수용 경험은 대상자가 자신을 가치 있는 존재로 느끼는 기반이 된다.'},
        @{plan='대상자의 강점과 성취를 구체적으로 찾아 말해준다.';why='구체적인 긍정적 피드백은 부정적 자기 인식에 대한 반증이 된다.'},
        @{plan='성공할 수 있는 작은 과제를 함께 정하고 달성하도록 돕는다.';why='작은 성공 경험이 쌓이면 자기효능감과 자존감이 높아진다.'},
        @{plan='부정적인 자기 대화를 알아차리고 긍정적인 표현으로 바꾸는 연습을 한다.';why='자동적으로 떠오르는 부정적 생각을 바꾸는 연습은 자기 인식 개선에 도움이 된다.'},
        @{plan='필요 시 정신건강 전문가 상담이나 집단 프로그램을 연계한다.';why='오래 지속된 자존감 저하는 전문적인 심리 중재가 효과적일 수 있다.'})
    edu = @(
        @{plan='대상자에게 자기주장 훈련과 긍정적인 자기 대화 방법을 교육한다.';why='자신의 의견을 표현하고 긍정적으로 생각하는 기술은 자존감 향상에 도움이 된다.'},
        @{plan='보호자에게 비난을 피하고 대상자의 노력을 인정하는 대화 방법을 교육한다.';why='가족의 지지적인 의사소통은 대상자의 긍정적 자기 인식을 강화한다.'})
}
$script:Templates['신체상 장애'] = @{
    en = 'Disturbed body image'
    domain = '6. 자기지각 Self-perception'
    cls = '3. 신체상 Body image'
    page = $null
    problem = '신체상 장애'
    priority = 6
    reason = '생리적·안전 요구는 아니지만 변화된 신체를 받아들이지 못하면 자가간호와 사회생활 참여가 어려워지므로 심리사회적 문제로 관리가 필요하다'
    evalData = '변화된 신체 부위를 보거나 만지는지, 신체에 대한 표현 내용, 자가간호 참여 정도, 사회적 활동 참여 여부'
    keywords = '신체상|body image|외모|흉터|scar|절단|amputat|유방절제|mastectomy|장루|stoma|colostomy|ileostomy|탈모|alopecia|화상|거울을 보지|보기 싫|보기 흉|모습이 싫'
    cause = '수술로 인한 신체 구조 변화'
    long = '대상자는 퇴원 시 변화된 신체를 받아들이는 말을 표현할 것이다.'
    short = @('대상자는 3일 내 변화된 신체 부위를 직접 볼 것이다.','대상자는 1주일 내 변화된 신체 부위의 자가간호에 참여할 것이다.')
    diag = @(
        @{plan='대상자가 변화된 신체 부위를 보거나 만지는지, 숨기거나 피하는 행동이 있는지 관찰한다.';why='변화된 신체에 대한 행동 반응은 신체상 수용 정도를 보여주는 지표가 된다.'},
        @{plan='신체 변화에 대한 대상자의 생각과 감정, 의미를 말하도록 하여 사정한다.';why='같은 신체 변화라도 대상자에게 주는 의미가 다르므로 개별적으로 파악해야 한다.'},
        @{plan='지지 체계와 사회 활동, 성생활에 대한 걱정을 사정한다.';why='신체상 변화는 대인관계와 역할에도 영향을 주므로 함께 확인해야 한다.'})
    ther = @(
        @{plan='대상자가 슬픔, 분노 등 감정을 표현하도록 격려하고 경청한다.';why='신체 변화는 상실 경험이므로 감정을 표현하는 것이 적응 과정에 도움이 된다.'},
        @{plan='준비가 되면 변화된 부위를 보고 만지도록 단계적으로 격려한다.';why='단계적인 노출은 변화된 신체에 대한 거부감을 줄이고 수용을 돕는다.'},
        @{plan='변화된 부위의 자가간호(장루 관리, 상처 관리 등)에 점차 참여하게 한다.';why='자가간호 참여는 통제감을 높이고 변화된 신체를 자신의 일부로 받아들이게 한다.'},
        @{plan='의복, 보형물, 가발 등 외모를 보완하는 방법을 안내한다.';why='외모 보완 방법은 사회생활에 대한 자신감을 높인다.'},
        @{plan='비슷한 경험을 가진 사람이나 자조 모임을 연결한다.';why='같은 경험을 가진 사람과의 교류는 적응의 모델이 되고 고립감을 줄인다.'})
    edu = @(
        @{plan='대상자에게 신체 변화 후 일상생활, 운동, 성생활에 대한 정확한 정보를 교육한다.';why='정확한 정보는 막연한 걱정을 줄이고 현실적인 적응을 돕는다.'},
        @{plan='보호자에게 대상자의 변화된 모습을 자연스럽게 받아들이는 태도를 보이도록 교육한다.';why='가족의 수용적인 반응은 대상자의 신체상 회복에 큰 영향을 준다.'})
}
$script:Templates['돌봄제공자 역할 긴장'] = @{
    en = 'Caregiver role strain'
    domain = '7. 역할관계 Role relationship'
    cls = '1. 돌봄제공자 역할 Caregiving roles'
    page = $null
    problem = '돌봄제공자 역할 긴장'
    priority = 6
    reason = '대상자의 생리적 요구는 아니지만 돌봄제공자가 지치면 대상자 돌봄의 질과 가족 기능이 함께 떨어지므로 심리사회적 문제로 관리가 필요하다'
    evalData = '돌봄제공자의 피로·수면·건강 상태, 돌봄 부담 척도 점수, 휴식 시간 확보 여부, 지지 자원 활용 여부'
    keywords = '간병|돌봄 부담|caregiver|burden|간병인|간병하느라|혼자 돌보|혼자 간병|교대할 사람|보호자가 지쳐|보호자 피로|보호자가 피곤|지쳤|요양원|장기요양|Zarit'
    cause = '장기간의 지속적인 돌봄 요구'
    long = '돌봄제공자는 퇴원 시 돌봄 부담을 줄이는 방법과 이용할 수 있는 지원 자원을 말로 표현할 것이다.'
    short = @('돌봄제공자는 3일 내 돌봄과 관련된 감정과 어려움을 간호사에게 말로 표현할 것이다.','돌봄제공자는 1주일 내 하루 1시간 이상 휴식 시간을 확보할 것이다.')
    diag = @(
        @{plan='돌봄제공자의 피로, 수면, 식사, 건강 상태와 정서 상태를 사정한다.';why='돌봄제공자의 신체적·정서적 소진 정도를 알아야 알맞은 지원을 계획할 수 있다.'},
        @{plan='돌봄 부담 척도(예: Zarit 부담 척도)를 이용해 돌봄 부담 정도를 사정한다.';why='표준화된 도구는 돌봄 부담을 객관적으로 평가하고 변화를 비교할 수 있게 한다.'},
        @{plan='가족 내 역할 분담, 경제적 상황, 이용 가능한 지지 자원을 확인한다.';why='도움을 나눌 사람과 자원을 알아야 현실적인 부담 경감 방법을 찾을 수 있다.'})
    ther = @(
        @{plan='돌봄제공자가 감정과 어려움을 표현하도록 격려하고 수고를 인정한다.';why='감정 표현과 인정은 스트레스를 줄이고 돌봄제공자의 정서적 지지가 된다.'},
        @{plan='돌봄제공자가 정기적으로 휴식을 취할 수 있도록 다른 가족과 역할 분담을 함께 계획한다.';why='휴식과 역할 분담은 신체적·정서적 소진을 예방한다.'},
        @{plan='장기요양보험, 방문요양, 주간보호센터, 사회복지사 상담 등 지원 자원을 연계한다.';why='공적·사회적 지원은 돌봄제공자 혼자 감당하는 부담을 실제로 줄여준다.'},
        @{plan='돌봄 과정에서 잘하고 있는 점을 구체적으로 피드백한다.';why='긍정적 피드백은 돌봄에 대한 자신감을 높이고 부담감을 줄인다.'})
    edu = @(
        @{plan='돌봄제공자에게 체위 변경, 이동 보조 등 필요한 돌봄 기술을 교육한다.';why='올바른 돌봄 기술은 신체적 부담과 손상을 줄이고 돌봄에 대한 자신감을 높인다.'},
        @{plan='돌봄제공자에게 자신의 건강관리(수면, 식사, 운동)와 스트레스 관리 방법을 교육한다.';why='돌봄제공자가 건강해야 장기적으로 안정된 돌봄을 지속할 수 있다.'})
}
$script:Templates['양육 장애'] = @{
    en = 'Impaired parenting'
    domain = '7. 역할관계 Role relationship'
    cls = '1. 돌봄제공자 역할 Caregiving roles'
    page = $null
    problem = '양육 장애'
    priority = 6
    reason = '부모의 생리적 문제는 아니지만 양육이 적절하지 않으면 아동의 안전과 성장발달에 직접 영향을 주므로 심리사회적 문제로 관리가 필요하다'
    evalData = '부모-아동 상호작용, 아동의 성장발달·위생·영양 상태, 부모의 양육 지식과 기술, 지지 체계 활용 여부'
    keywords = '양육|육아|아이를 돌보|아기를 돌보|방임|아동 방임|child neglect|학대|child abuse|미혼모|청소년 산모|산후 ?우울|postpartum depress|아동보호|발달 지연|성장 지연|failure to thrive'
    cause = '양육 지식 부족과 지지 체계 부족'
    long = '부모는 퇴원 시 아동의 발달 단계에 맞는 양육 행동을 보일 것이다.'
    short = @('부모는 3일 내 아동 돌봄(수유, 목욕, 기저귀 교환 등)을 간호사의 시범에 따라 수행할 것이다.','부모는 1주일 내 양육에 도움을 받을 수 있는 자원을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='부모와 아동의 상호작용(눈 맞춤, 반응, 접촉, 말 걸기)을 관찰한다.';why='부모-아동 상호작용은 양육의 질과 애착 상태를 보여주는 중요한 지표이다.'},
        @{plan='아동의 성장발달, 영양, 위생 상태와 손상 흔적을 확인한다.';why='아동의 상태는 양육이 적절한지를 객관적으로 나타내며 학대·방임의 징후를 발견할 수 있다.'},
        @{plan='부모의 양육 지식, 정서 상태(산후 우울 등), 경제적 상황과 지지 체계를 사정한다.';why='양육 장애의 원인을 파악해야 부모에게 필요한 지원을 계획할 수 있다.'})
    ther = @(
        @{plan='부모가 양육에 대한 걱정과 감정을 표현하도록 격려하고 비난 없이 경청한다.';why='비판하지 않는 태도는 부모의 방어를 줄이고 도움을 받아들이게 한다.'},
        @{plan='수유, 목욕, 달래기 등 양육 기술을 시범 보이고 부모가 직접 해보게 한다.';why='직접 수행하는 경험은 양육 기술을 익히고 자신감을 높인다.'},
        @{plan='부모가 잘하는 양육 행동을 구체적으로 칭찬한다.';why='긍정적 강화는 바람직한 양육 행동을 지속하게 한다.'},
        @{plan='필요 시 사회복지사, 육아 지원 서비스, 정신건강 상담을 연계한다.';why='경제적·정서적 문제는 전문 자원의 도움이 필요하며 지지 체계를 넓혀준다.'},
        @{plan='학대나 방임이 의심되면 기관 지침에 따라 즉시 보고한다.';why='아동의 안전이 가장 우선이며 의료인은 아동학대 신고 의무자이다.'})
    edu = @(
        @{plan='부모에게 아동의 발달 단계별 특성과 알맞은 양육 방법을 교육한다.';why='발달에 맞는 기대와 양육 방법을 알면 부모-아동 갈등이 줄어든다.'},
        @{plan='부모에게 양육 스트레스 관리 방법과 도움을 요청할 수 있는 기관을 안내한다.';why='스트레스 관리와 도움 요청은 부적절한 양육 행동을 예방한다.'})
}
$script:Templates['애착 장애의 위험'] = @{
