    reason = '아직 나타나지 않은 위험 진단이며 생리적 문제는 아니지만 초기 애착은 영아의 정서·사회 발달의 기초가 되므로 예방이 필요하다'
    evalData = '부모의 면회 빈도와 시간, 영아와의 눈 맞춤·접촉·말 걸기, 돌봄 참여 정도, 영아에 대한 부모의 표현'
    keywords = '애착|bonding|attachment|모아 분리|모자 분리|부모-영아 분리|\bNICU\b|신생아 중환자실|미숙아|조산|premature|preterm|인큐베이터|incubator|캥거루 ?케어|kangaroo|모아 상호작용|산후 ?우울'
    cause = '신생아 중환자실 입원으로 인한 부모-영아 분리'
    long = '부모는 퇴원 시 영아와 따뜻한 상호작용을 하며 돌봄에 자신감을 보일 것이다.'
    short = @('부모는 3일 내 면회 시 영아를 만지고 말을 거는 행동을 보일 것이다.','부모는 1주일 내 기저귀 교환이나 수유 등 영아 돌봄에 직접 참여할 것이다.')
    diag = @(
        @{plan='면회 시 부모와 영아의 상호작용(눈 맞춤, 접촉, 말 걸기, 이름 부르기)을 관찰한다.';why='부모-영아 상호작용은 애착 형성 정도를 보여주는 지표가 된다.'},
        @{plan='부모의 면회 빈도, 영아에 대한 표현, 불안이나 죄책감 정도를 사정한다.';why='부모의 정서 상태와 면회 양상은 애착 형성을 방해하는 요인을 파악하는 데 도움이 된다.'},
        @{plan='부모의 산후 우울 증상과 지지 체계를 확인한다.';why='산후 우울은 영아에 대한 반응을 줄여 애착 형성을 방해할 수 있다.'})
    ther = @(
        @{plan='부모가 자주 면회하도록 격려하고 영아의 상태를 쉬운 말로 설명한다.';why='영아에 대한 정보와 잦은 만남은 부모의 불안을 줄이고 애착 형성 기회를 늘린다.'},
        @{plan='영아의 상태가 안정되면 캥거루 케어(피부 접촉)를 할 수 있도록 돕는다.';why='피부 접촉은 부모와 영아의 정서적 유대를 높이고 영아의 체온과 호흡 안정에도 도움이 된다.'},
        @{plan='기저귀 교환, 수유, 목욕 등 돌봄에 부모가 직접 참여하도록 한다.';why='돌봄 참여는 부모 역할에 대한 자신감을 높이고 애착 형성을 촉진한다.'},
        @{plan='모유 수유를 원하면 유축과 모유 전달 방법을 돕는다.';why='모유 수유 참여는 부모의 역할감을 높이고 영아와의 유대를 강화한다.'})
    edu = @(
        @{plan='부모에게 영아의 신호(배고픔, 피로, 스트레스 신호)를 알아보고 반응하는 방법을 교육한다.';why='영아의 신호에 적절히 반응하는 것은 안정 애착 형성의 핵심이다.'},
        @{plan='부모에게 산후 우울 증상과 도움을 받을 수 있는 곳을 교육한다.';why='부모의 정서 건강은 영아와의 상호작용에 영향을 주므로 조기 발견과 도움이 필요하다.'})
}
$script:Templates['가족과정 중단'] = @{
    en = 'Interrupted family processes'
    domain = '7. 역할관계 Role relationship'
    cls = '2. 가족관계 Family relationships'
    page = $null
    problem = '가족과정 중단'
    priority = 6
    reason = '생리적 문제는 아니지만 가족의 기능이 흔들리면 대상자의 회복과 지지에 영향을 주므로 심리사회적 문제로 관리가 필요하다'
    evalData = '가족 구성원 간 의사소통과 역할 분담, 가족의 감정 표현, 문제 해결 참여 정도, 지지 자원 활용 여부'
    keywords = '가족 갈등|가족 역할|가족 기능|가족 위기|가족이 흩어|가족 간 의사소통|가족 간 대화|가족 지지 부족|생계|가장이 입원|가장으로|아이들을 돌볼 사람|이혼|별거|가족 구조 변화'
    cause = '가족 구성원의 입원으로 인한 역할 변화'
    long = '가족은 퇴원 시 변화된 상황에 맞게 역할을 조정하여 가족 기능을 유지할 것이다.'
    short = @('가족은 3일 내 현재 상황에 대한 감정과 걱정을 간호사에게 말로 표현할 것이다.','가족은 1주일 내 구성원 간 역할 분담 계획을 세울 것이다.')
    diag = @(
        @{plan='가족 구성원 간 의사소통 방식, 역할 분담, 의사결정 과정을 사정한다.';why='가족 기능의 변화를 파악해야 어떤 부분에 지원이 필요한지 알 수 있다.'},
        @{plan='입원이나 질병으로 생긴 가족의 변화(경제, 돌봄, 일상생활)를 확인한다.';why='가족과정 중단을 일으킨 구체적 상황을 알아야 현실적인 해결 방법을 찾을 수 있다.'},
        @{plan='가족의 대처 방식과 이용 가능한 지지 자원을 사정한다.';why='가족의 강점과 자원은 위기를 극복하는 데 활용할 수 있다.'})
    ther = @(
        @{plan='가족이 감정과 걱정을 표현할 수 있는 시간과 장소를 제공한다.';why='감정 표현은 가족의 스트레스를 줄이고 서로를 이해하는 계기가 된다.'},
        @{plan='대상자의 상태와 치료 계획을 가족에게 정기적으로 설명한다.';why='정확한 정보는 불확실성으로 인한 불안을 줄이고 가족이 계획을 세울 수 있게 한다.'},
        @{plan='가족회의를 통해 구성원 간 역할 분담과 문제 해결 방법을 함께 계획하도록 돕는다.';why='함께 계획하면 부담이 한 사람에게 몰리지 않고 가족의 결속이 강해진다.'},
        @{plan='가족이 대상자 돌봄과 의사결정에 참여하도록 격려한다.';why='가족의 참여는 통제감을 높이고 가족 기능의 회복을 돕는다.'},
        @{plan='필요 시 사회복지사 상담이나 경제적 지원 제도를 연계한다.';why='경제적·사회적 문제는 전문 자원의 도움으로 해결 가능성이 높아진다.'})
    edu = @(
        @{plan='가족에게 서로의 감정을 존중하며 대화하는 방법을 교육한다.';why='효과적인 의사소통은 가족 갈등을 줄이고 협력을 높인다.'},
        @{plan='가족에게 퇴원 후 필요한 돌봄 내용과 이용할 수 있는 지역사회 자원을 교육한다.';why='미리 준비하면 퇴원 후 가족의 변화된 상황에 대한 적응이 쉬워진다.'})
}
$script:Templates['비효과적 역할수행'] = @{
    en = 'Ineffective role performance'
    domain = '7. 역할관계 Role relationship'
    cls = '3. 역할수행 Role performance'
    page = $null
    problem = '역할수행 장애'
    priority = 6
    reason = '생리적·안전 요구는 아니지만 사회적·가족 내 역할을 하지 못하면 자존감과 가족 기능에 영향을 주므로 심리사회적 문제로 관리가 필요하다'
    evalData = '역할 변화에 대한 표현, 현재 수행 가능한 역할 범위, 역할 조정 계획 여부, 가족 내 역할 분담 상태'
    keywords = '역할을 못|역할 변화|역할 갈등|\brole\b|직장 복귀|직장에 못|일을 못|일을 할 수 없|휴직|실직|휴학|학업 중단|가장으로서|엄마로서|아빠로서|엄마 노릇|아빠 노릇|집안일을 못'
    cause = '질병으로 인한 신체 기능 저하'
    long = '대상자는 퇴원 시 현재 상태에 맞게 조정한 역할을 수행할 수 있다고 말로 표현할 것이다.'
    short = @('대상자는 3일 내 역할 변화에 대한 감정을 간호사에게 말로 표현할 것이다.','대상자는 1주일 내 현재 상태에서 수행할 수 있는 역할을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='대상자가 가정, 직장, 사회에서 맡았던 역할과 현재 수행하지 못하는 역할을 사정한다.';why='역할 변화의 범위를 알아야 적응을 돕는 구체적인 계획을 세울 수 있다.'},
        @{plan='역할 변화에 대한 대상자의 감정(죄책감, 상실감, 좌절)과 인식을 사정한다.';why='역할 상실에 대한 감정 반응을 파악해야 정서적 지지와 중재 방향을 정할 수 있다.'},
        @{plan='신체 기능 상태와 가족 및 직장의 지지 정도를 확인한다.';why='신체 능력과 지지 체계는 대상자가 수행할 수 있는 역할의 범위를 결정한다.'})
    ther = @(
        @{plan='대상자가 역할 변화에 대한 감정을 표현하도록 격려하고 경청한다.';why='감정 표현은 상실감을 줄이고 변화된 상황을 받아들이는 데 도움이 된다.'},
        @{plan='현재 상태에서 할 수 있는 역할을 대상자와 함께 찾아 실천하게 한다.';why='가능한 역할을 수행하는 경험은 자존감과 역할에 대한 통제감을 회복시킨다.'},
        @{plan='가족과 함께 역할을 일시적으로 나누는 방법을 계획하도록 돕는다.';why='역할 분담은 대상자의 부담과 죄책감을 줄이고 가족 기능을 유지하게 한다.'},
        @{plan='필요 시 재활치료, 직업 재활, 사회복지 상담을 연계한다.';why='전문 자원은 기능 회복과 사회 복귀를 돕는다.'})
    edu = @(
        @{plan='대상자에게 질병의 경과와 회복에 따라 역할을 단계적으로 늘려가는 방법을 교육한다.';why='현실적인 기대와 단계적 계획은 무리한 역할 수행으로 인한 좌절과 건강 악화를 예방한다.'},
        @{plan='보호자에게 대상자의 역할 변화를 이해하고 대상자가 할 수 있는 역할을 인정해주도록 교육한다.';why='가족의 이해와 인정은 대상자가 변화된 역할에 적응하는 데 큰 도움이 된다.'})
}
$script:Templates['사회적 상호작용 장애'] = @{
    en = 'Impaired social interaction'
    domain = '7. 역할관계 Role relationship'
    cls = '3. 역할수행 Role performance'
    page = $null
    problem = '사회적 상호작용 장애'
    priority = 6
    reason = '생리적·안전 욕구가 충족된 뒤 다루는 사랑과 소속의 욕구에 해당하는 심리사회적 문제이다'
    evalData = '타인과의 대화 빈도와 시간, 집단 활동 참여 여부, 눈맞춤·표정 등 비언어적 반응, 대인관계에 대한 대상자의 표현'
    keywords = '위축|철수|고립|혼자 지내|어울리지|대인관계|사회성|눈을 피|눈맞춤|말수가 적|withdraw|isolat|social interaction|자폐|autism|조현병|schizophreni|사회불안|social anxiety'
    cause = '사회적 기술 부족'
    long = '대상자는 퇴원 시 타인과 편안하게 상호작용하는 모습을 보일 것이다.'
    short = @('대상자는 3일 내 간호사와 10분 이상 대화를 유지할 것이다.','대상자는 1주일 내 병동 집단 활동에 1회 이상 참여할 것이다.')
    diag = @(
        @{plan='매 듀티마다 대상자의 대인관계 양상(대화 빈도, 눈맞춤, 표정, 위축 행동)을 관찰한다.';why='상호작용의 양상을 객관적으로 파악해야 문제의 정도를 알고 중재 효과를 평가할 수 있다.'},
        @{plan='대상자가 타인과의 관계에서 느끼는 감정과 어려움을 사정한다.';why='불안, 두려움, 낮은 자존감 등 상호작용을 방해하는 원인을 알아야 개별화된 중재를 계획할 수 있다.'},
        @{plan='대상자의 사회적 지지 체계(가족, 친구, 지역사회 자원)를 사정한다.';why='지지 체계가 부족하면 고립이 심해지므로 활용 가능한 자원을 파악해야 한다.'})
    ther = @(
        @{plan='일관된 간호사가 짧고 규칙적인 만남을 통해 신뢰 관계를 형성한다.';why='예측 가능한 일대일 관계는 대상자의 불안을 줄이고 다른 관계로 넓혀 가는 출발점이 된다.'},
        @{plan='대상자가 감정과 생각을 표현하도록 경청하고 수용적인 태도를 보인다.';why='비판 없는 수용은 대상자가 안전하다고 느끼게 하여 자기표현을 늘린다.'},
        @{plan='부담이 적은 소규모 활동부터 시작해 점차 집단 활동 참여를 격려한다.';why='단계적 노출은 성공 경험을 쌓게 하여 사회적 상호작용에 대한 자신감을 높인다.'},
        @{plan='적절한 사회적 행동을 보였을 때 즉시 긍정적 피드백을 제공한다.';why='긍정적 강화는 바람직한 행동이 반복되도록 돕는다.'},
        @{plan='역할극을 통해 인사하기, 대화 시작하기 등 사회적 기술을 연습하게 한다.';why='안전한 환경에서의 반복 연습은 실제 상황에서 기술을 사용할 수 있게 한다.'})
    edu = @(
        @{plan='대상자에게 대화를 시작하고 유지하는 방법, 거절 표현 방법을 교육한다.';why='구체적인 사회적 기술을 익히면 대인관계에서의 불안이 줄고 상호작용이 늘어난다.'},
        @{plan='보호자에게 대상자의 작은 변화를 지지하고 함께 활동하도록 교육한다.';why='가족의 지지와 참여는 퇴원 후에도 사회적 관계를 유지하는 힘이 된다.'})
}
$script:Templates['성기능 장애'] = @{
    en = 'Sexual dysfunction'
    domain = '8. 성 Sexuality'
    cls = '2. 성기능 Sexual function'
    page = $null
    problem = '성기능 장애'
    priority = 6
    reason = '생명을 위협하지는 않으나 자존감과 부부·연인 관계에 영향을 주는 심리사회적 문제로 생리적 문제 해결 후 다룬다'
    evalData = '성기능 관련 호소 내용과 변화, 복용 약물, 배우자와의 관계에 대한 표현, 성 문제에 대해 질문하거나 상담을 요청하는지'
    keywords = '성기능|성욕|성관계|성생활|발기|erectile|\bED\b|사정 장애|조루|불감|성교통|dyspareunia|libido|sexual|전립선 절제|prostatectomy|자궁 절제|hysterectomy|유방 절제|mastectomy|폐경|menopaus'
    cause = '질병과 치료로 인한 신체 구조와 기능의 변화'
    long = '대상자는 퇴원 시 만족스러운 성생활을 위한 방법을 알고 표현할 것이다.'
    short = @('대상자는 3일 내 성기능 변화에 대한 감정을 말로 표현할 것이다.','대상자는 1주일 내 성기능 문제에 도움이 되는 방법을 두 가지 이상 말할 것이다.')
    diag = @(
        @{plan='사생활이 보장된 환경에서 대상자의 성기능 변화(시작 시기, 양상, 정도)를 사정한다.';why='성 문제는 말하기 어려운 주제이므로 사생활을 보장해야 정확한 정보를 얻을 수 있다.'},
        @{plan='성기능에 영향을 줄 수 있는 약물(항고혈압제, 항우울제 등), 질환, 수술력을 확인한다.';why='약물과 질환은 성욕·발기·윤활 등에 직접 영향을 주므로 원인 확인이 중재 방향을 정한다.'},
        @{plan='성기능 변화가 자아상, 배우자 관계, 정서 상태에 미치는 영향을 사정한다.';why='성기능 장애는 우울, 자존감 저하, 관계 갈등으로 이어질 수 있어 심리사회적 영향을 함께 파악해야 한다.'})
    ther = @(
        @{plan='판단하지 않는 태도로 대상자가 성 관련 걱정을 표현하도록 격려한다.';why='수용적인 분위기는 대상자의 수치심을 줄이고 문제를 드러내어 해결하도록 돕는다.'},
        @{plan='PLISSIT 모델에 따라 허용, 제한된 정보 제공, 구체적 제안 순으로 접근한다.';why='단계적 접근은 대상자의 요구 수준에 맞추어 부담 없이 도움을 제공하는 체계적 방법이다.'},
        @{plan='약물 부작용이 의심되면 의사에게 보고하여 약물 조정 가능성을 확인한다.';why='원인 약물을 조정하면 성기능이 회복될 수 있으며, 대상자가 임의로 약을 끊지 않도록 예방한다.'},
        @{plan='대상자와 배우자가 함께 이야기할 수 있는 기회를 마련한다.';why='부부 간 솔직한 의사소통은 오해를 줄이고 서로에게 맞는 해결책을 찾게 한다.'},
        @{plan='필요시 비뇨의학과, 산부인과, 성 상담 전문가에게 의뢰한다.';why='전문적인 치료와 상담이 필요한 경우 적절한 의뢰로 문제 해결을 도울 수 있다.'})
    edu = @(
        @{plan='대상자와 배우자에게 질병·치료가 성기능에 미치는 영향과 대처 방법(편안한 체위, 윤활제 사용, 친밀감 표현 방법)을 교육한다.';why='정확한 정보는 막연한 두려움을 줄이고 현실적인 대안을 선택하게 한다.'},
        @{plan='처방된 약물을 임의로 중단하지 말고 부작용이 있으면 의료진과 상의하도록 교육한다.';why='임의 중단은 원래 질환을 악화시킬 수 있으므로 안전하게 조정해야 한다.'})
}
$script:Templates['비효과적 출산 과정'] = @{
    en = 'Ineffective childbearing process'
    domain = '8. 성 Sexuality'
    cls = '3. 생식 Reproduction'
    page = $null
    problem = '출산 과정 문제'
    priority = 7
    reason = '즉각적인 생명 위협보다는 산전 관리와 건강행위 실천의 문제로, 생리적·안전 문제를 해결한 뒤 교육과 관리로 다룬다'
    evalData = '산전 진찰 방문 횟수, 체중 증가와 영양 상태, 분만 준비 정도, 출산과 아기 돌봄에 대한 지식과 표현, 지지 체계'
    keywords = '산전 진찰|산전관리|산전 관리|prenatal care|임신|pregnan|미혼모|청소년 임신|계획하지 않은 임신|unplanned|분만 준비|출산 준비|흡연 임신|임신 중 음주|약물 남용|substance'
    cause = '산전 관리에 대한 지식 부족'
    long = '대상자는 퇴원 시 건강한 출산과 산후 회복을 위한 자가간호 방법을 실천할 것이다.'
    short = @('대상자는 2일 내 정기적인 산전 진찰의 필요성을 말로 표현할 것이다.','대상자는 1주일 내 분만 징후와 병원에 와야 할 때를 두 가지 이상 말할 것이다.')
    diag = @(
        @{plan='산전 진찰 이력, 임신 주수, 체중 증가, 활력징후를 확인한다.';why='산전 관리 정도와 신체 상태를 알면 모체와 태아의 위험을 조기에 파악할 수 있다.'},
        @{plan='임신·분만·신생아 돌봄에 대한 대상자의 지식과 준비 정도를 사정한다.';why='지식과 준비가 부족한 부분을 알아야 필요한 교육 내용을 정할 수 있다.'},
        @{plan='흡연, 음주, 약물 사용, 영양 상태와 사회경제적 지지 체계를 사정한다.';why='위해 건강행위와 지지 부족은 조산·저체중아 등 불량한 출산 결과의 주요 위험 요인이다.'})
    ther = @(
        @{plan='대상자가 임신과 출산에 대한 감정과 걱정을 표현하도록 격려한다.';why='정서적 지지는 불안을 줄이고 출산 과정에 능동적으로 참여하게 한다.'},
        @{plan='대상자와 함께 정기 산전 진찰 일정과 출산 계획을 세운다.';why='대상자가 계획에 참여하면 실천 가능성이 높아진다.'},
        @{plan='처방에 따라 엽산, 철분제 등 보충제를 투여하고 복용 여부를 확인한다.';why='엽산은 신경관 결손을, 철분은 임신성 빈혈을 예방한다.'},
        @{plan='분만 진행 시 호흡법과 이완법을 함께 연습하고 대상자 곁에서 지지한다.';why='호흡법과 지속적인 지지는 분만 통증과 두려움을 줄여 분만 과정에 효과적으로 대처하게 한다.'},
        @{plan='필요시 사회복지사, 지역 보건소의 모자보건 서비스와 연계한다.';why='경제적·사회적 지원은 산전·산후 관리를 지속하는 데 도움이 된다.'})
    edu = @(
        @{plan='대상자와 배우자에게 임신 중 영양, 금연·금주, 위험 징후(질 출혈, 양막 파수, 심한 두통, 태동 감소)를 교육한다.';why='위험 징후를 알면 즉시 병원을 찾아 모체와 태아의 합병증을 예방할 수 있다.'},
        @{plan='모유수유, 신생아 돌봄, 산후 자가간호 방법을 교육한다.';why='출산 후 필요한 기술을 미리 익히면 부모 역할에 대한 자신감이 높아진다.'})
}
$script:Templates['산모-태아 이원체 장애의 위험'] = @{
    en = 'Risk for disturbed maternal-fetal dyad'
    domain = '8. 성 Sexuality'
    cls = '3. 생식 Reproduction'
    page = $null
    problem = '산모-태아 위험'
    priority = 5
    reason = '아직 나타나지 않은 위험 진단이지만 모체와 태아 두 생명의 안전과 관련되어 예방이 필요하다'
    evalData = '태아심음(FHR)과 태동, 혈압·단백뇨, 혈당, 자궁저부 높이, 질 출혈·자궁수축 여부, 위험 징후 설명 여부'
    keywords = '임신성 고혈압|전자간증|자간전증|preeclampsia|임신성 당뇨|\bGDM\b|gestational|태아심음|\bFHR\b|태동|fetal|전치태반|태반 조기박리|placenta|조기진통|preterm labor|자궁내 성장지연|IUGR|NST|양수'
    cause = '임신 합병증(임신성 고혈압, 임신성 당뇨)'
    long = '대상자는 분만 시까지 모체와 태아 모두 합병증 없이 임신을 유지할 것이다.'
    short = @('대상자는 1주일 내 혈압이 140/90 mmHg 미만으로 유지될 것이다.','대상자는 2일 내 태동 감소 등 즉시 알려야 할 위험 징후를 세 가지 이상 말할 것이다.')
    diag = @(
        @{plan='매 4시간마다 활력징후를 측정하고 혈압 상승, 두통, 시야 장애, 부종, 단백뇨를 사정한다.';why='혈압 상승과 단백뇨는 전자간증의 징후로 태반 혈류를 감소시켜 태아에게 위험하므로 조기 발견이 필요하다.'},
        @{plan='처방에 따라 태아심음(정상 110~160회/분)과 NST 결과, 태동을 확인한다.';why='태아심음과 태동은 태아의 산소화와 안녕 상태를 반영하는 지표이다.'},
        @{plan='혈당, 자궁수축, 질 출혈·양수 누출 여부를 확인한다.';why='혈당 조절 실패와 조기 진통, 출혈은 태아 성장 이상과 조산의 원인이 된다.'})
    ther = @(
        @{plan='휴식 시 좌측위를 취하도록 한다.';why='좌측위는 하대정맥 압박을 줄여 정맥 환류와 태반 혈류를 증가시킨다.'},
        @{plan='처방에 따라 항고혈압제, 인슐린 등을 투여하고 혈압·혈당 변화를 확인한다.';why='모체의 혈압과 혈당을 조절하면 태반 기능을 유지하여 태아를 보호할 수 있다.'},
        @{plan='처방된 식이(당뇨식, 적절한 단백질 섭취)를 제공하고 섭취량을 확인한다.';why='적절한 영양은 태아 성장을 돕고 혈당 변동을 줄인다.'},
        @{plan='조용하고 자극이 적은 환경을 제공하고 정서적 지지를 한다.';why='스트레스와 과도한 자극은 혈압을 높이고 자궁수축을 유발할 수 있다.'})
    edu = @(
        @{plan='대상자에게 하루 태동 횟수 세는 방법과 태동이 줄면 즉시 알리도록 교육한다.';why='태동 감소는 태아 곤란의 초기 신호일 수 있어 빠른 평가가 필요하다.'},
        @{plan='대상자와 보호자에게 위험 징후(심한 두통, 시야 흐림, 상복부 통증, 질 출혈, 규칙적인 자궁수축)와 정기 산전 진찰의 중요성을 교육한다.';why='위험 징후를 알고 즉시 병원을 찾으면 모체와 태아의 심각한 합병증을 예방할 수 있다.'})
}
$script:Templates['외상후 증후군의 위험'] = @{
    en = 'Risk for post-trauma syndrome'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '1. 외상후 반응 Post-trauma responses'
    page = $null
    problem = '외상후 증후군 위험'
    priority = 6
    reason = '아직 증상이 나타나지 않은 심리사회적 위험 진단으로 생리적·안전 요구를 충족한 뒤 예방적으로 다룬다'
    evalData = '수면 상태, 악몽·플래시백 여부, 사건 회피 행동, 사건에 대한 감정 표현 정도, 대처 방법 사용 여부'
    keywords = '교통사고|사고 후|폭행|assault|성폭력|성폭행|학대|abuse|재난|화재|전쟁|외상 경험|trauma|플래시백|flashback|악몽|nightmare|PTSD|외상후|목격|사망 목격'
    cause = '생명을 위협하는 외상 사건 경험'
    long = '대상자는 퇴원 시 외상 사건에 대한 감정을 표현하고 효과적인 대처 방법을 사용할 것이다.'
    short = @('대상자는 3일 내 사건과 관련된 감정을 간호사에게 말로 표현할 것이다.','대상자는 1주일 내 스트레스 시 사용할 수 있는 대처 방법을 두 가지 이상 말할 것이다.')
    diag = @(
        @{plan='매 듀티마다 수면 양상, 악몽, 과각성(깜짝 놀람, 예민함), 회피 행동을 관찰한다.';why='이러한 증상은 외상후 스트레스 반응의 초기 징후로, 조기 발견하면 증후군으로의 진행을 막을 수 있다.'},
        @{plan='대상자가 사건을 어떻게 받아들이고 있는지와 평소 대처 방식을 사정한다.';why='사건에 대한 해석과 대처 능력은 외상후 증상 발생 위험을 예측하는 중요한 요인이다.'},
        @{plan='가족, 친구 등 사회적 지지 체계와 이용 가능한 자원을 사정한다.';why='충분한 사회적 지지는 외상 후 회복을 돕는 대표적 보호 요인이다.'})
    ther = @(
        @{plan='안전하고 조용한 환경을 제공하고 일관된 간호사가 돌본다.';why='안전감과 예측 가능성은 과각성을 줄이고 신뢰 관계 형성을 돕는다.'},
        @{plan='대상자가 원할 때 사건과 감정을 표현하도록 격려하되 강요하지 않는다.';why='준비되지 않은 상태에서 상세한 회상을 강요하면 오히려 고통이 커질 수 있다.'},
        @{plan='심호흡, 근육이완법 등 이완 기법을 함께 연습한다.';why='이완 기법은 교감신경 항진을 줄여 불안과 신체 긴장을 완화한다.'},
        @{plan='대상자의 반응이 비정상적인 사건에 대한 정상적인 반응임을 알려 준다.';why='반응을 정상화하면 죄책감과 자책을 줄이고 도움을 구하는 것을 쉽게 한다.'},
        @{plan='필요시 정신건강의학과 또는 심리 상담 전문가에게 의뢰한다.';why='전문적 상담은 외상후 스트레스 장애로 진행하는 것을 예방하는 데 효과적이다.'})
    edu = @(
        @{plan='대상자와 보호자에게 외상 후 나타날 수 있는 반응(수면 장애, 악몽, 예민함)과 도움이 필요한 시점을 교육한다.';why='증상을 미리 알면 당황하지 않고 조기에 도움을 요청할 수 있다.'},
        @{plan='규칙적인 생활, 수면 위생, 음주를 피하는 방법 등 건강한 대처 방법을 교육한다.';why='음주 등 부적절한 대처는 증상을 악화시키며, 규칙적인 생활은 회복을 돕는다.'})
}
$script:Templates['비효과적 대처'] = @{
    en = 'Ineffective coping'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '2. 대처반응 Coping responses'
    page = $null
    problem = '비효과적 대처'
    priority = 6
    reason = '생리적·안전 요구가 충족된 뒤 다루는 심리사회적 문제로, 해결되지 않으면 치료 참여와 회복을 방해한다'
    evalData = '스트레스 상황에서의 반응과 행동, 사용하는 대처 방법의 종류, 문제 해결 시도 여부, 음주·흡연 증가 여부, 지지 요청 여부'
    keywords = '대처|coping|감당이 안|어떻게 해야 할지|스트레스|stress|술을 마|음주 증가|화를 내|짜증|감정 기복|문제 해결|포기하고|감당하기|버티기 힘'
    cause = '스트레스 상황에 대한 대처 자원의 부족'
    long = '대상자는 퇴원 시 스트레스 상황에서 효과적인 대처 방법을 사용할 것이다.'
    short = @('대상자는 3일 내 현재의 스트레스 요인과 그에 대한 감정을 말로 표현할 것이다.','대상자는 1주일 내 새로운 대처 방법을 한 가지 이상 실제로 사용할 것이다.')
    diag = @(
        @{plan='대상자가 인식하는 스트레스 요인과 그 의미를 사정한다.';why='같은 상황이라도 받아들이는 의미에 따라 반응이 달라지므로 대상자의 관점을 알아야 한다.'},
        @{plan='현재 사용하는 대처 방법(회피, 음주, 공격성 등)과 그 효과를 사정한다.';why='비효과적인 대처 방식을 파악해야 이를 대신할 건강한 대처 방법을 계획할 수 있다.'},
        @{plan='수면, 식욕, 집중력 변화와 자해·자살 생각 여부를 사정한다.';why='대처 실패는 우울과 자해 위험으로 이어질 수 있어 안전 확인이 우선 필요하다.'})
    ther = @(
        @{plan='대상자가 감정을 표현할 수 있도록 시간을 내어 경청한다.';why='감정 표현은 긴장을 해소하고 문제를 객관적으로 바라보는 데 도움을 준다.'},
        @{plan='대상자의 과거 성공적인 대처 경험과 강점을 찾도록 돕는다.';why='자신의 강점을 인식하면 자기효능감이 높아져 새로운 대처를 시도하게 된다.'},
        @{plan='문제를 작은 단계로 나누어 해결 방법을 함께 찾고 실천하도록 한다.';why='단계적 문제 해결은 압도되는 느낌을 줄이고 성취감을 준다.'},
        @{plan='치료 계획과 일상 활동에서 대상자가 선택할 기회를 제공한다.';why='선택권은 통제감을 높여 능동적인 대처를 촉진한다.'},
        @{plan='필요시 상담 전문가, 자조 모임 등 지지 자원과 연결한다.';why='외부 지지 자원은 대처 능력을 보완하고 퇴원 후에도 도움을 준다.'})
    edu = @(
        @{plan='대상자에게 이완요법, 운동, 일기 쓰기 등 건강한 스트레스 관리 방법을 교육한다.';why='건강한 대처 방법을 익히면 음주·회피 같은 부적절한 대처를 대신할 수 있다.'},
        @{plan='보호자에게 대상자의 감정을 비판 없이 들어주고 지지하는 방법을 교육한다.';why='가족의 지지는 대상자의 대처 자원을 강화한다.'})
}
$script:Templates['가족 대처 손상'] = @{
    en = 'Compromised family coping'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '2. 대처반응 Coping responses'
    page = $null
    problem = '가족 대처 손상'
    priority = 6
    reason = '대상자를 돌보는 가족의 심리사회적 문제로 생리적·안전 문제 해결 후 다루지만 대상자의 회복과 퇴원 계획에 영향을 준다'
    evalData = '가족의 질병 이해 정도, 돌봄 참여 정도, 피로·스트레스 표현, 가족 간 의사소통 양상, 지원 자원 이용 여부'
    keywords = '보호자|간병|caregiver|돌봄 부담|가족이 지쳐|가족 갈등|면회가 없|가족 지지|family|보호자 피로|간병 부담|부양'
    cause = '장기간의 돌봄으로 인한 가족의 피로와 정보 부족'
    long = '대상자의 가족은 퇴원 시 대상자를 지지하고 돌보는 방법을 효과적으로 실천할 것이다.'
    short = @('가족은 3일 내 대상자의 상태와 치료 계획에 대해 이해한 내용을 말로 표현할 것이다.','가족은 1주일 내 돌봄 부담을 줄이기 위한 지원 방법을 한 가지 이상 활용할 것이다.')
    diag = @(
        @{plan='가족이 대상자의 질병과 치료를 어떻게 이해하고 있는지 사정한다.';why='잘못된 이해나 정보 부족은 불안과 비효과적인 돌봄으로 이어진다.'},
        @{plan='주 돌봄 제공자의 피로, 수면, 스트레스와 정서 상태를 사정한다.';why='돌봄 제공자의 소진은 가족 대처 능력을 떨어뜨리고 대상자에 대한 지지를 감소시킨다.'},
        @{plan='가족 구성원 간의 역할 분담, 의사소통 양상과 이용 가능한 자원을 사정한다.';why='가족 체계의 강점과 약점을 알아야 현실적인 지원 계획을 세울 수 있다.'})
    ther = @(
        @{plan='가족이 감정과 걱정을 표현할 수 있는 시간과 장소를 마련한다.';why='감정 표현은 가족의 긴장을 줄이고 문제를 함께 해결할 준비를 하게 한다.'},
        @{plan='대상자의 상태와 치료 계획에 대한 정보를 가족의 눈높이에 맞게 정기적으로 제공한다.';why='정확한 정보는 불확실성으로 인한 불안을 줄인다.'},
        @{plan='가족이 할 수 있는 범위에서 대상자의 돌봄에 참여하도록 격려한다.';why='돌봄 참여는 가족의 무력감을 줄이고 대상자와의 유대를 강화한다.'},
        @{plan='가족 구성원 간 역할 분담과 휴식 시간을 확보하도록 돕는다.';why='돌봄 부담을 나누면 주 돌봄 제공자의 소진을 예방할 수 있다.'},
        @{plan='필요시 사회복지사, 간병 지원 서비스, 가족 지지 모임과 연계한다.';why='외부 자원은 가족의 경제적·정서적 부담을 덜어 준다.'})
    edu = @(
        @{plan='가족에게 퇴원 후 필요한 돌봄 기술(투약, 체위 변경, 이상 징후 관찰)을 시범과 재시범으로 교육한다.';why='돌봄 기술에 자신감이 생기면 가족의 불안이 줄고 대처 능력이 향상된다.'},
        @{plan='가족에게 돌봄 제공자 자신의 건강과 휴식을 챙기는 것의 중요성을 교육한다.';why='돌봄 제공자가 건강해야 장기간 안정적으로 대상자를 돌볼 수 있다.'})
}
$script:Templates['과도한 두려움'] = @{
    en = 'Excessive fear'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '2. 대처반응 Coping responses'
    page = $null
    problem = '두려움'
    priority = 6
    reason = '생리적·안전 요구가 충족된 뒤 다루는 심리사회적 문제지만 과도한 두려움은 치료 협조와 수면을 방해한다'
    evalData = '두려움의 대상과 정도에 대한 표현, 맥박·혈압·호흡수, 떨림·발한 등 신체 반응, 치료 협조 정도, 대처 방법 사용 여부'
    keywords = '무서|두려|겁이|겁나|fear|공포|phobia|수술이 무섭|죽을까|떨고|떨림|식은땀|회피|도망|panic|공황'
    cause = '낯선 치료 환경과 예상되는 침습적 처치'
    long = '대상자는 퇴원 시 두려움이 감소하여 편안한 모습을 보일 것이다.'
    short = @('대상자는 2일 내 두려움의 대상과 원인을 말로 표현할 것이다.','대상자는 3일 내 두려움을 줄이는 방법을 두 가지 이상 사용할 것이다.')
    diag = @(
        @{plan='두려움의 구체적인 대상, 정도, 신체 반응(빈맥, 혈압 상승, 떨림, 발한)을 사정한다.';why='두려움은 특정 대상에 대한 반응이므로 대상을 정확히 알아야 원인 중심의 중재가 가능하다.'},
        @{plan='대상자가 치료와 질병에 대해 알고 있는 내용과 오해를 사정한다.';why='잘못된 정보나 정보 부족은 두려움을 실제보다 크게 만든다.'},
        @{plan='수면, 식사, 치료 협조 정도 등 두려움이 일상생활에 미치는 영향을 관찰한다.';why='두려움으로 인한 기능 저하 정도를 파악하면 중재의 우선순위를 정할 수 있다.'})
    ther = @(
        @{plan='침착하고 일관된 태도로 대상자 곁에 머무르며 안전하다는 느낌을 준다.';why='간호사의 안정된 태도와 존재는 대상자의 안전감을 높여 두려움을 줄인다.'},
        @{plan='검사·처치 전에 절차, 소요 시간, 느낄 감각을 쉬운 말로 미리 설명한다.';why='예측 가능성은 미지의 상황에 대한 두려움을 줄인다.'},
        @{plan='대상자가 두려움을 말로 표현하도록 격려하고 감정을 수용한다.';why='감정을 인정받으면 긴장이 완화되고 현실적으로 상황을 바라볼 수 있다.'},
        @{plan='심호흡, 근육이완법, 심상요법 등 이완 기법을 함께 시행한다.';why='이완 기법은 교감신경 반응을 줄여 두려움의 신체 증상을 완화한다.'},
        @{plan='대상자가 원하면 보호자나 신뢰하는 사람이 함께 있도록 한다.';why='친숙한 사람의 존재는 정서적 안정을 준다.'})
    edu = @(
        @{plan='대상자에게 두려움을 느낄 때 사용할 수 있는 이완 기법과 도움을 요청하는 방법을 교육한다.';why='스스로 사용할 수 있는 대처 방법은 통제감을 높여 두려움을 줄인다.'},
        @{plan='보호자에게 대상자의 두려움을 비판하지 않고 지지하는 방법을 교육한다.';why='가족의 지지적인 반응은 대상자의 정서적 안정에 도움이 된다.'})
}
$script:Templates['무력감'] = @{
    en = 'Powerlessness'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '2. 대처반응 Coping responses'
    page = $null
    problem = '무력감'
    priority = 6
    reason = '생리적·안전 요구가 충족된 뒤 다루는 심리사회적 문제로, 해결되지 않으면 자가간호 참여와 치료 의지를 떨어뜨린다'
    evalData = '통제감에 대한 표현, 자가간호와 의사결정 참여 정도, 치료에 대한 관심과 질문 여부, 의존적 행동 변화'
    keywords = '무력|어쩔 수 없|아무것도 할 수 없|소용없|포기|powerless|통제할 수 없|내 마음대로 안|남에게 의존|의존적|시키는 대로|helpless|체념'
    cause = '질병으로 인한 일상생활 통제력 상실'
    long = '대상자는 퇴원 시 자신의 건강 관리에 대한 통제감을 표현할 것이다.'
    short = @('대상자는 3일 내 자신이 통제할 수 있는 일과 없는 일을 구분하여 말할 것이다.','대상자는 1주일 내 자가간호 활동 한 가지 이상을 스스로 결정하고 수행할 것이다.')
    diag = @(
        @{plan='대상자가 통제할 수 없다고 느끼는 상황과 그에 대한 감정을 사정한다.';why='무력감의 원인이 되는 상황을 알아야 통제감을 회복할 수 있는 부분을 찾을 수 있다.'},
        @{plan='자가간호와 치료 결정에 참여하는 정도를 관찰한다.';why='참여 정도는 무력감의 정도를 반영하며 중재 효과를 평가하는 지표가 된다.'},
        @{plan='우울 증상(흥미 상실, 수면·식욕 변화)과 절망감 여부를 사정한다.';why='지속적인 무력감은 우울과 절망감으로 진행할 수 있어 조기 확인이 필요하다.'})
    ther = @(
        @{plan='일과(식사 시간, 세면 시간, 활동 순서)에서 대상자가 선택할 수 있는 기회를 제공한다.';why='작은 선택이라도 스스로 결정하면 통제감이 회복된다.'},
        @{plan='치료 계획을 세울 때 대상자의 의견을 묻고 반영한다.';why='의사결정 참여는 치료에 대한 주인의식과 협조를 높인다.'},
        @{plan='대상자가 스스로 할 수 있는 일은 직접 하도록 격려하고 성취를 인정한다.';why='성공 경험과 긍정적 강화는 자기효능감을 높인다.'},
        @{plan='달성 가능한 작은 목표를 대상자와 함께 세운다.';why='현실적인 목표를 달성하면 변화가 가능하다는 믿음이 생긴다.'},
        @{plan='대상자가 질병과 치료에 대해 질문하고 감정을 표현하도록 격려한다.';why='정보와 감정 표현은 불확실성을 줄여 통제감을 높인다.'})
    edu = @(
        @{plan='대상자에게 질병과 치료 과정, 스스로 할 수 있는 자가관리 방법을 교육한다.';why='지식이 늘면 자신이 관리할 수 있는 부분을 인식하여 무력감이 줄어든다.'},
        @{plan='보호자에게 대상자가 할 수 있는 일을 대신하지 말고 스스로 하도록 지지하는 방법을 교육한다.';why='과도한 도움은 의존성과 무력감을 키우므로 자율성을 존중해야 한다.'})
}
$script:Templates['부적응적 비탄'] = @{
    en = 'Maladaptive grieving'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '2. 대처반응 Coping responses'
    page = $null
    problem = '비탄'
    priority = 6
    reason = '생리적·안전 요구가 충족된 뒤 다루는 심리사회적 문제이지만 장기화되면 우울과 자해 위험으로 이어질 수 있다'
    evalData = '상실에 대한 감정 표현, 수면·식사 등 일상 기능, 자책·죄책감 표현, 사회 활동 참여, 자해·자살 생각 여부'
    keywords = '사별|사망한|돌아가신|잃은|상실|loss|grief|bereave|비탄|애도|유산|사산|stillbirth|miscarriage|그리워|따라가고 싶|죄책감'
    cause = '의미 있는 사람의 죽음'
    long = '대상자는 퇴원 시 상실을 받아들이고 일상생활을 회복할 것이다.'
    short = @('대상자는 1주일 내 상실과 관련된 감정을 간호사에게 말로 표현할 것이다.','대상자는 2주일 내 하루 세 끼 식사와 기본 일상 활동을 수행할 것이다.')
    diag = @(
        @{plan='상실의 내용, 경과 기간, 현재의 감정(슬픔, 분노, 죄책감) 표현을 사정한다.';why='비탄 반응의 정도와 기간을 알아야 정상적 애도와 부적응적 비탄을 구분할 수 있다.'},
        @{plan='수면, 식사, 위생 등 일상생활 기능과 사회적 활동 수준을 관찰한다.';why='일상 기능의 지속적인 저하는 비탄이 부적응적으로 진행되고 있음을 나타낸다.'},
        @{plan='자해·자살 생각, 절망감 표현 여부를 직접 묻고 사정한다.';why='장기화된 비탄은 우울과 자살 위험을 높이므로 안전 확인이 가장 우선이다.'})
    ther = @(
        @{plan='대상자가 고인과의 추억과 상실에 대한 감정을 표현하도록 경청한다.';why='감정을 말로 표현하는 것은 애도 과정을 진행시키는 핵심 요소이다.'},
        @{plan='슬픔, 분노 등 대상자의 감정을 판단하지 않고 수용한다.';why='감정이 수용되면 억눌린 감정이 해소되어 애도가 진행된다.'},
        @{plan='규칙적인 식사, 수면, 가벼운 활동을 유지하도록 격려한다.';why='기본적인 신체 리듬을 유지하면 우울 증상을 줄이고 회복을 돕는다.'},
        @{plan='대상자의 문화와 종교에 맞는 애도 의식이나 추모 활동을 지지한다.';why='의미 있는 의식은 상실을 받아들이고 관계를 정리하는 데 도움을 준다.'},
        @{plan='필요시 애도 상담, 자조 모임, 정신건강 전문가에게 의뢰한다.';why='부적응적 비탄은 전문적인 상담과 치료로 회복을 도울 수 있다.'})
    edu = @(
        @{plan='대상자와 가족에게 비탄은 정상적인 과정이며 개인마다 속도가 다름을 교육한다.';why='애도 과정을 이해하면 자신의 반응을 받아들이고 서두르지 않게 된다.'},
        @{plan='보호자에게 자살 위험 징후(죽고 싶다는 말, 물건 정리, 갑작스런 평온)와 즉시 도움을 요청하는 방법을 교육한다.';why='위험 징후를 알면 응급 상황에 빠르게 대응할 수 있다.'})
}
$script:Templates['비효과적 부정'] = @{
    en = 'Ineffective denial'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '2. 대처반응 Coping responses'
    page = $null
    problem = '부정'
    priority = 6
    reason = '생리적·안전 요구가 충족된 뒤 다루는 심리사회적 문제지만 치료 거부와 지연으로 건강을 위협할 수 있다'
    evalData = '질병과 증상에 대한 인식 표현, 치료·검사 협조 여부, 증상 축소나 무시 행동, 감정 표현 정도'
    keywords = '부정|아무렇지 않|별거 아니|괜찮다고|믿을 수 없|오진|denial|치료 거부|검사 거부|퇴원 요구|증상을 축소|대수롭지|병이 아니'
    cause = '질병 진단으로 인한 위협감과 두려움'
    long = '대상자는 퇴원 시 자신의 건강 상태를 인정하고 치료 계획에 참여할 것이다.'
    short = @('대상자는 3일 내 자신의 질병과 관련된 감정을 말로 표현할 것이다.','대상자는 1주일 내 자신의 질병과 필요한 치료를 한 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='대상자가 자신의 질병과 증상을 어떻게 이해하고 표현하는지 사정한다.';why='부정의 정도와 내용을 알아야 대상자가 받아들일 수 있는 속도로 접근할 수 있다.'},
        @{plan='치료와 검사에 대한 협조 정도, 투약 이행 여부를 관찰한다.';why='부정이 치료 거부로 이어지면 건강에 직접적인 위험이 되므로 행동을 확인해야 한다.'},
        @{plan='부정의 바탕이 되는 두려움과 불안의 정도를 사정한다.';why='부정은 감당하기 어려운 불안에 대한 방어이므로 그 원인을 이해해야 한다.'})
    ther = @(
        @{plan='신뢰 관계를 형성하고 대상자의 방어를 직접적으로 공격하지 않는다.';why='부정을 정면으로 반박하면 방어가 더 강해지므로 수용적 태도가 필요하다.'},
        @{plan='대상자가 질병과 관련된 두려움과 감정을 표현하도록 격려한다.';why='감정이 표현되면 불안이 줄어 현실을 받아들일 준비가 된다.'},
        @{plan='대상자의 이해 수준에 맞추어 사실적인 정보를 조금씩 반복하여 제공한다.';why='점진적인 정보 제공은 대상자가 압도되지 않고 현실을 인식하도록 돕는다.'},
        @{plan='증상과 검사 결과를 대상자와 함께 확인하며 실제 상태를 인식하도록 돕는다.';why='객관적인 자료는 대상자가 현실을 직면하는 근거가 된다.'},
        @{plan='작은 치료 활동부터 참여하도록 격려하고 참여 시 긍정적 피드백을 준다.';why='단계적인 참여와 강화는 치료 이행을 높인다.'})
    edu = @(
        @{plan='대상자에게 치료를 미루거나 중단했을 때의 위험과 치료의 이점을 쉬운 말로 교육한다.';why='현실적인 결과를 이해하면 치료에 대한 동기가 생긴다.'},
        @{plan='보호자에게 대상자를 비난하지 않고 지지하면서 치료 참여를 격려하는 방법을 교육한다.';why='가족의 지지는 대상자가 방어 대신 대처를 선택하도록 돕는다.'})
}
$script:Templates['정서 조절 장애'] = @{
    en = 'Impaired mood regulation'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '2. 대처반응 Coping responses'
    page = $null
    problem = '정서 조절 장애'
    priority = 6
    reason = '생리적·안전 요구가 충족된 뒤 다루는 심리사회적 문제이지만 기분 변화가 심하면 자해 위험이 있어 안전 확인이 함께 필요하다'
    evalData = '기분 상태 표현과 기분 척도 점수, 수면·식욕 변화, 감정 폭발 빈도, 자해·자살 생각 여부, 약물 복용 이행'
    keywords = '우울|depress|조증|mania|manic|양극성|bipolar|기분 변화|기분이 오락가락|감정 기복|mood|과민|짜증이 심|눈물이 나|흥미가 없|무쾌감|PHQ|BDI|리튬|lithium'
    cause = '신경화학적 불균형과 스트레스'
    long = '대상자는 퇴원 시 안정된 기분 상태를 유지하고 기분 변화에 대처하는 방법을 사용할 것이다.'
    short = @('대상자는 3일 내 자신의 기분 상태를 0~10점 척도로 표현할 것이다.','대상자는 1주일 내 기분 변화 시 사용할 대처 방법을 두 가지 이상 말할 것이다.')
    diag = @(
        @{plan='매 듀티마다 기분 상태, 감정 표현, 행동 변화를 관찰하고 기분 척도로 사정한다.';why='기분의 변화 양상을 반복적으로 파악해야 중재 효과를 평가하고 악화를 조기에 발견할 수 있다.'},
        @{plan='자해·자살 생각과 계획 여부를 직접적으로 묻고 사정한다.';why='기분 장애는 자살 위험을 높이므로 안전 확인이 가장 우선적인 사정이다.'},
        @{plan='수면, 식욕, 체중, 에너지 수준과 집중력 변화를 사정한다.';why='신체 기능의 변화는 기분 장애의 중요한 지표이다.'})
    ther = @(
        @{plan='자해 위험 물품을 제거하고 위험이 있으면 관찰 빈도를 높이는 등 안전한 환경을 유지한다.';why='안전한 환경은 충동적인 자해 행동을 예방하는 기본 중재이다.'},
        @{plan='처방에 따라 항우울제, 기분안정제를 투여하고 효과와 부작용(리튬 투여 시 혈중농도, 진전, 오심)을 확인한다.';why='약물은 신경전달물질 균형을 회복시켜 기분을 안정시키며, 리튬은 치료 범위가 좁아 독성 확인이 필요하다.'},
        @{plan='규칙적인 수면, 식사, 활동 일과를 유지하도록 돕는다.';why='일정한 생활 리듬은 기분 변동을 줄이는 데 도움이 된다.'},
        @{plan='대상자가 감정을 언어로 표현하도록 격려하고 수용한다.';why='감정을 말로 표현하면 충동적인 행동 대신 건강한 감정 조절이 가능해진다.'},
        @{plan='자극이 적은 조용한 환경을 제공한다.';why='과도한 자극은 감정 반응을 증폭시키므로 환경 조절이 필요하다.'})
    edu = @(
        @{plan='대상자에게 기분 일기 쓰기, 이완법 등 감정 조절 방법과 처방 약물을 임의로 중단하지 않아야 함을 교육한다.';why='자기 감시와 약물 이행은 재발을 예방하는 핵심 요소이다.'},
        @{plan='보호자에게 재발 징후(수면 감소, 과도한 활동, 위축, 죽음에 대한 언급)와 응급 시 도움을 받는 방법을 교육한다.';why='가족이 조기 징후를 알아차리면 위기를 예방하고 빠르게 치료받을 수 있다.'})
}
$script:Templates['자율신경 반사부전'] = @{
    en = 'Autonomic dysreflexia'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '3. 신경행동 스트레스 Neurobehavioral stress'
    page = $null
    problem = '자율신경 반사부전'
    priority = 2
    reason = '갑작스러운 고혈압 위기로 뇌출혈과 경련을 일으킬 수 있는 생명을 위협하는 순환 문제이다'
    evalData = '혈압과 맥박(평소 대비 변화), 두통 호소, 손상 부위 위쪽의 홍조·발한, 방광 팽만·변 매복 여부, 유발 요인 설명 여부'
    keywords = '자율신경 반사부전|자율신경 반사이상|autonomic dysreflexia|dysreflexia|척수 손상|척수손상|spinal cord injury|\bSCI\b|사지마비|tetrapleg|quadripleg|하반신 마비|parapleg|T6|경수 손상|cervical cord'
    cause = '손상 부위 아래의 유해 자극(방광 팽만, 변 매복)'
    long = '대상자는 퇴원 시 자율신경 반사부전의 유발 요인과 대처 방법을 말하고 실천할 것이다.'
    short = @('대상자는 증상 발생 시 30분 내 혈압이 평소 수준으로 회복될 것이다.','대상자는 3일 내 자율신경 반사부전의 유발 요인을 세 가지 이상 말할 것이다.')
    diag = @(
        @{plan='증상 발생 시 2~5분마다 혈압과 맥박을 측정한다.';why='평소보다 수축기 혈압이 20~40 mmHg 이상 상승하면 위기 상태이며, 반사성 서맥이 동반될 수 있어 자주 확인해야 한다.'},
        @{plan='심한 두통, 시야 흐림, 손상 부위 위쪽의 홍조·발한, 코막힘을 사정한다.';why='T6 이상 척수 손상 시 하부의 자극이 교감신경을 과도하게 흥분시키고 상부에서 보상성 부교감 반응이 나타난다.'},
        @{plan='방광 팽만, 도뇨관 꼬임, 변 매복, 꽉 끼는 옷, 피부 압박 등 유발 요인을 신속히 확인한다.';why='유발 요인을 제거하는 것이 근본적인 치료이며 대부분 방광과 장 문제가 원인이다.'})
    ther = @(
        @{plan='즉시 침상머리를 올려 앉히고 다리를 내린다.';why='앉은 자세는 하지에 혈액을 저류시켜 혈압을 낮춘다.'},
        @{plan='꽉 끼는 옷, 복대, 압박 스타킹을 느슨하게 한다.';why='압박을 제거하면 유해 자극이 줄고 혈액이 하지로 분포한다.'},
        @{plan='방광 팽만이 있으면 도뇨를 시행하고, 도뇨관이 있으면 꼬임과 막힘을 확인한다.';why='방광 팽만은 가장 흔한 유발 요인으로 신속히 배뇨시키면 증상이 완화된다.'},
        @{plan='처방에 따라 리도카인 젤을 바른 후 직장 내 변 매복을 확인하고 제거한다.';why='국소 마취제는 직장 자극으로 인한 증상 악화를 예방한다.'},
        @{plan='유발 요인을 제거해도 혈압이 높으면 처방에 따라 속효성 항고혈압제를 투여하고 혈압 저하 정도를 확인한다.';why='빠른 혈압 조절은 뇌출혈, 경련 같은 합병증을 예방하며 과도한 저혈압이 생기지 않도록 관찰해야 한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 자율신경 반사부전의 증상(두통, 홍조, 발한)과 즉시 앉히고 원인을 찾는 응급 대처 방법을 교육한다.';why='가정에서도 발생할 수 있어 대상자와 가족이 즉시 대처할 수 있어야 한다.'},
        @{plan='규칙적인 배뇨·배변 프로그램과 피부 압박 예방 방법을 교육한다.';why='방광 팽만, 변비, 욕창 같은 유발 요인을 예방하면 재발을 줄일 수 있다.'})
}
$script:Templates['두개내압 적응능력 감소'] = @{
    en = 'Decreased intracranial adaptive capacity'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '3. 신경행동 스트레스 Neurobehavioral stress'
    page = $null
    problem = '두개내압 상승'
    priority = 2
    reason = '두개내압 상승은 뇌관류를 감소시켜 뇌탈출과 사망에 이를 수 있는 생명을 위협하는 순환 문제이다'
    evalData = 'GCS 점수, 동공 크기와 대광반사, 활력징후(쿠싱 3징후), ICP·CPP 수치, 두통·구토 여부, 운동 기능 변화'
    keywords = '두개내압|뇌압|\bICP\b|\bIICP\b|intracranial pressure|뇌부종|cerebral edema|뇌출혈|ICH|\bSAH\b|지주막하|subarachnoid|경막하|subdural|경막외|epidural hematoma|외상성 뇌손상|\bTBI\b|뇌종양|brain tumor|수두증|hydrocephalus|쿠싱|Cushing|만니톨|mannitol|GCS'
    cause = '뇌부종으로 인한 두개 내 용적 증가'
    long = '대상자는 퇴원 시까지 신경학적 악화 없이 두개내압이 정상 범위로 유지될 것이다.'
    short = @('대상자는 24시간 내 ICP가 20 mmHg 미만으로 유지될 것이다.','대상자는 3일 내 GCS 점수가 감소하지 않고 유지되거나 향상될 것이다.')
    diag = @(
        @{plan='매 1~2시간마다 GCS, 동공 크기와 대광반사, 사지 운동 기능을 사정한다.';why='의식 수준 저하와 동공 변화는 두개내압 상승의 가장 민감하고 초기 징후이다.'},
        @{plan='활력징후를 측정하고 수축기 혈압 상승, 맥압 증가, 서맥, 불규칙한 호흡(쿠싱 3징후)을 관찰한다.';why='쿠싱 3징후는 뇌간 압박을 의미하는 후기 징후로 즉시 보고해야 한다.'},
        @{plan='ICP 감시 장치가 있으면 ICP와 CPP(정상 60~70 mmHg 이상)를 확인하고 SpO2, 동맥혈가스를 확인한다.';why='저산소증과 고탄산혈증은 뇌혈관을 확장시켜 두개내압을 높이므로 산소화 상태를 함께 확인해야 한다.'})
    ther = @(
        @{plan='침상머리를 30° 올리고 머리와 목을 일직선(중립 위치)으로 유지하며 고관절의 과도한 굴곡을 피한다.';why='이 자세는 경정맥 배액을 원활하게 하여 두개내압을 낮춘다.'},
        @{plan='기침, 배변 시 힘주기 등 발살바 수기를 피하도록 하고 처방에 따라 대변 완화제를 투여한다.';why='발살바 수기는 흉강·복강 내압을 높여 정맥 환류를 막고 두개내압을 상승시킨다.'},
        @{plan='흡인이 필요하면 흡인 전 산소를 충분히 공급하고 1회 10초 이내로 짧게 시행한다.';why='장시간 흡인은 저산소증과 기침 반사를 일으켜 두개내압을 높인다.'},
        @{plan='처방에 따라 만니톨 등 삼투성 이뇨제를 투여하고 섭취량·배설량, 혈청 삼투질 농도, 전해질을 확인한다.';why='삼투성 이뇨제는 뇌조직의 수분을 혈관으로 끌어내어 뇌부종을 줄이며, 탈수와 전해질 불균형을 주의해야 한다.'},
        @{plan='조명과 소음을 줄이고 간호 활동을 몰아서 하지 않도록 분산하여 시행한다.';why='연속적인 자극과 처치는 두개내압을 누적적으로 상승시킨다.'})
    edu = @(
        @{plan='보호자에게 대상자의 머리 위치를 유지하고 갑작스러운 자극을 피해야 하는 이유를 교육한다.';why='보호자의 협조는 두개내압을 높이는 요인을 줄이는 데 도움이 된다.'},
        @{plan='보호자에게 의식 변화, 심한 두통, 분출성 구토, 경련 시 즉시 알리도록 교육한다.';why='신경학적 악화 징후를 빨리 발견하면 응급 처치를 신속히 할 수 있다.'})
}
$script:Templates['신생아 금단 증후군'] = @{
    en = 'Neonatal abstinence syndrome'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '3. 신경행동 스트레스 Neurobehavioral stress'
    page = $null
    problem = '신생아 금단 증상'
    priority = 4
    reason = '중추신경계 과민과 수유·수면 장애가 신생아의 성장과 생리적 안정을 위협하므로 우선적으로 다룬다'
    evalData = '금단 점수(Finnegan 등), 수유량과 체중 변화, 수면 시간, 울음과 진정 정도, 설사·구토 여부, 피부 손상 여부'
    keywords = '신생아 금단|금단 증후군|neonatal abstinence|\bNAS\b|\bNOWS\b|withdrawal|Finnegan|모체 약물|산모 약물|아편|opioid|메타돈|methadone|마약|고음의 울음|high.?pitched cry'
    cause = '자궁 내 약물 노출 후 출생으로 인한 약물 중단'
    long = '신생아는 퇴원 시 금단 증상 없이 적절한 수유와 수면을 유지하며 체중이 증가할 것이다.'
    short = @('신생아는 3일 내 금단 점수가 처방된 기준 이하로 유지될 것이다.','신생아는 1주일 내 출생 체중의 10% 이상 감소하지 않을 것이다.')
    diag = @(
        @{plan='매 3~4시간마다 수유 후 금단 점수 척도로 금단 증상(고음의 울음, 떨림, 근긴장도 증가, 수면 장애, 하품, 재채기)을 사정한다.';why='표준화된 척도로 반복 사정해야 증상의 정도를 객관적으로 평가하고 약물 치료 필요성을 판단할 수 있다.'},
        @{plan='매일 같은 시간에 체중을 측정하고 수유량, 구토, 설사, 섭취량·배설량을 확인한다.';why='빨기 곤란, 구토, 설사로 탈수와 체중 감소가 쉽게 생기므로 영양과 수분 상태를 확인해야 한다.'},
        @{plan='활력징후, 호흡 양상, 체온을 측정하고 경련 여부를 관찰한다.';why='금단 증상은 빈호흡, 발열, 경련으로 나타날 수 있어 생리적 안정을 확인해야 한다.'})
    ther = @(
        @{plan='조명과 소음을 줄인 조용한 환경을 제공하고 처치를 모아서 시행한다.';why='외부 자극을 줄이면 과민해진 중추신경계를 안정시킬 수 있다.'},
        @{plan='속싸개로 감싸고 안아서 부드럽게 흔들어 주며 비영양적 빨기를 제공한다.';why='감싸기와 빨기는 신생아를 진정시키고 자기 조절을 돕는다.'},
        @{plan='소량씩 자주 수유하고 수유 중 충분히 쉬게 한다.';why='빨기와 삼키기의 조화가 떨어진 신생아는 소량씩 자주 먹어야 섭취량을 늘리고 구토를 줄일 수 있다.'},
        @{plan='처방에 따라 모르핀 등 약물을 투여하고 투여 후 호흡수, 진정 정도를 확인한다.';why='약물은 심한 금단 증상을 조절하지만 호흡 억제가 생길 수 있어 관찰이 필요하다.'},
        @{plan='둔부와 무릎 등 마찰 부위의 피부를 관찰하고 깨끗하고 건조하게 유지한다.';why='과도한 움직임과 잦은 설사로 피부 손상이 생기기 쉽다.'})
    edu = @(
        @{plan='부모에게 신생아를 진정시키는 방법(감싸기, 안아주기, 조용한 환경)과 금단 증상을 교육한다.';why='부모가 직접 돌보며 진정 방법을 익히면 신생아의 안정과 부모-아기 애착에 도움이 된다.'},
        @{plan='부모에게 금기가 아닐 시 모유수유와 피부 접촉의 이점을 교육하고 산모의 약물 치료와 지원 프로그램 연계를 안내한다.';why='모유수유와 피부 접촉은 금단 증상을 줄이며, 산모의 회복 지원은 퇴원 후 안전한 양육 환경을 만든다.'})
}
$script:Templates['영아 행동 조직화 장애'] = @{
    en = 'Disorganized infant behavior'
    domain = '9. 대처/스트레스 내성 Coping/Stress tolerance'
    cls = '3. 신경행동 스트레스 Neurobehavioral stress'
    page = $null
    problem = '영아 행동 조직화 장애'
    priority = 4
    reason = '스트레스 반응으로 산소포화도·심박수 변화와 수면·수유 장애가 생겨 영아의 생리적 안정과 성장을 방해한다'
    evalData = '스트레스 신호(피부색 변화, 손가락 벌림, 하품, 몸을 젖힘), 처치 중 심박수와 SpO2 변화, 수면 시간, 수유 반응, 진정 소요 시간'
    keywords = '미숙아|조산아|premature|preterm|이른둥이|\bNICU\b|신생아 중환자|재태 주수|gestational age|저체중 출생|\bLBW\b|\bVLBW\b|스트레스 신호|과자극|overstimulat|무호흡|apnea|서맥|bradycardia'
    cause = '미숙한 신경계와 과도한 환경 자극'
    long = '영아는 퇴원 시 처치와 자극에 안정된 생리적·행동적 반응을 보일 것이다.'
    short = @('영아는 3일 내 처치 중 SpO2가 90% 이상, 심박수가 정상 범위로 유지될 것이다.','부모는 1주일 내 영아의 스트레스 신호와 안정 신호를 두 가지 이상 구분하여 말할 것이다.')
    diag = @(
        @{plan='처치 전·중·후 영아의 스트레스 신호(피부색 변화, 손가락 벌림, 딸꾹질, 하품, 몸을 젖힘, 사지 늘어짐)를 관찰한다.';why='행동 신호는 영아가 감당할 수 있는 자극의 한계를 알려 주므로 처치 속도와 방법을 조절하는 근거가 된다.'},
        @{plan='심박수, 호흡, SpO2를 지속적으로 모니터하고 무호흡·서맥 발생을 확인한다.';why='미숙한 자율신경계는 과자극 시 무호흡, 서맥, 산소포화도 저하로 반응한다.'},
        @{plan='수면-각성 상태, 수유 시 빨기·삼키기·호흡의 조화를 사정한다.';why='행동 조직화의 정도는 수면 주기와 수유 능력에 반영된다.'})
    ther = @(
        @{plan='조명을 낮추고 인큐베이터 덮개를 사용하며 소음을 줄인다.';why='빛과 소음 감소는 미숙한 감각 체계에 대한 과자극을 줄여 생리적 안정을 돕는다.'},
        @{plan='처치를 모아서 시행하되 영아의 수면 주기를 존중하고 처치 사이에 충분한 휴식을 준다.';why='불필요한 자극을 줄이면 에너지 소모가 감소하고 깊은 수면이 보장된다.'},
        @{plan='둥지 만들기(nesting)로 사지를 굴곡된 중앙 위치로 유지하고 감싸 안는다.';why='굴곡 자세와 경계 제공은 자궁 내 환경과 비슷하여 자기 진정을 돕는다.'},
        @{plan='처치 중 손으로 감싸기, 비영양적 빨기를 제공한다.';why='부드러운 접촉과 빨기는 스트레스 반응을 줄이고 진정을 돕는다.'},
        @{plan='영아 상태가 안정되면 캥거루 케어(피부 접촉)를 시행하도록 돕는다.';why='피부 접촉은 체온, 심박수, 호흡을 안정시키고 부모-영아 애착을 증진한다.'})
    edu = @(
        @{plan='부모에게 영아의 스트레스 신호와 안정 신호를 구분하는 방법을 교육한다.';why='부모가 영아의 신호를 읽을 수 있으면 영아에게 맞는 돌봄을 제공할 수 있다.'},
        @{plan='부모에게 캥거루 케어, 감싸기, 조용한 환경 만들기 방법을 시범을 통해 교육한다.';why='부모가 돌봄에 참여하면 영아의 안정과 부모의 양육 자신감이 함께 높아진다.'})
}
$script:Templates['영적 고뇌'] = @{
    en = 'Spiritual distress'
    domain = '10. 삶의 원칙 Life principles'
    cls = '3. 가치/신념/행동 일치 Value/Belief/Action congruence'
    page = $null
    problem = '영적 고뇌'
    priority = 7
    reason = '생리적·안전·심리사회적 요구를 충족한 뒤 다루는 삶의 의미와 가치에 관한 문제이다'
    evalData = '삶의 의미와 신념에 대한 표현, 신앙 활동이나 의식 참여 여부, 절망감·분노 표현, 영적 지지 요청 여부'
    keywords = '영적|spiritual|신앙|종교|religio|기도|pray|하나님|하느님|부처|신이 버|왜 나에게|벌을 받|삶의 의미|의미가 없|목사|신부|스님|채플|원목'
    cause = '질병으로 인한 삶의 의미와 신념에 대한 도전'
    long = '대상자는 퇴원 시 삶의 의미와 희망을 표현하고 영적 안녕감을 느낄 것이다.'
    short = @('대상자는 3일 내 자신의 영적 고민과 감정을 말로 표현할 것이다.','대상자는 1주일 내 원하는 영적 활동(기도, 명상, 성직자 면담)을 한 가지 이상 할 것이다.')
    diag = @(
        @{plan='대상자의 종교와 신념, 삶의 의미와 목적에 대한 생각을 사정한다.';why='대상자의 가치관을 이해해야 존중하는 태도로 영적 요구를 지지할 수 있다.'},
        @{plan='죄책감, 분노, 절망감, 신에 대한 원망 등 영적 고뇌의 표현을 관찰한다.';why='영적 고뇌의 표현을 파악하면 대상자의 내적 갈등의 정도를 알 수 있다.'},
        @{plan='대상자에게 의미 있는 영적 자원(종교 공동체, 의식, 성직자, 가족)을 사정한다.';why='활용 가능한 영적 자원을 알면 대상자에게 맞는 지지를 연결할 수 있다.'})
    ther = @(
        @{plan='대상자가 삶과 죽음, 고통의 의미에 대해 이야기하도록 경청한다.';why='판단하지 않는 경청은 대상자가 내면의 갈등을 정리하는 데 도움을 준다.'},
        @{plan='대상자의 신념과 가치를 존중하고 간호사의 신념을 강요하지 않는다.';why='영적 돌봄은 대상자의 신념 체계 안에서 이루어져야 한다.'},
        @{plan='기도, 명상, 경전 읽기 등 대상자가 원하는 영적 활동을 위한 시간과 조용한 공간을 제공한다.';why='익숙한 영적 활동은 위안과 평안을 준다.'},
        @{plan='대상자가 원하면 원목, 성직자, 종교 공동체와 연결한다.';why='전문적인 영적 지지는 깊은 영적 고뇌를 다루는 데 도움이 된다.'},
        @{plan='대상자의 삶에서 의미 있었던 경험과 관계를 회상하도록 돕는다.';why='삶의 회상은 의미를 재발견하고 희망을 갖게 한다.'})
    edu = @(
        @{plan='대상자에게 명상, 이완 등 마음의 평안을 찾는 방법을 교육한다.';why='스스로 사용할 수 있는 방법은 영적 안녕을 유지하는 데 도움이 된다.'},
        @{plan='보호자에게 대상자의 신앙 활동과 영적 요구를 지지하는 방법을 교육한다.';why='가족의 지지는 대상자가 영적 위안을 얻는 중요한 자원이다.'})
}
$script:Templates['의사결정 갈등'] = @{
    en = 'Decisional conflict'
    domain = '10. 삶의 원칙 Life principles'
    cls = '3. 가치/신념/행동 일치 Value/Belief/Action congruence'
    page = $null
    problem = '의사결정 갈등'
    priority = 7
    reason = '생명이나 안전을 즉시 위협하지 않는 정보·가치관과 관련된 문제로 다른 우선 문제 해결 후 다루지만 치료 시기를 놓치지 않도록 지지해야 한다'
    evalData = '선택에 대한 망설임과 불확실성 표현, 각 선택지의 장단점 이해 정도, 결정 지연 여부, 결정 후 만족감 표현'
    keywords = '결정을 못|결정하지 못|고민 중|망설|어떻게 해야|선택을 못|수술할지|치료를 받을지|동의서|informed consent|decision|결정 지연|확신이 없|후회할까'
    cause = '치료 선택지에 대한 정보 부족과 가치관의 충돌'
    long = '대상자는 퇴원 시 자신의 가치관에 맞는 결정을 내리고 그 결정에 만족감을 표현할 것이다.'
    short = @('대상자는 2일 내 각 선택지의 장점과 단점을 두 가지 이상 말할 것이다.','대상자는 3일 내 결정에 영향을 주는 자신의 가치와 우선순위를 말로 표현할 것이다.')
    diag = @(
        @{plan='대상자가 고민하고 있는 결정의 내용과 각 선택지에 대한 이해 정도를 사정한다.';why='잘못된 정보나 이해 부족을 확인해야 필요한 정보를 제공할 수 있다.'},
        @{plan='결정에 영향을 주는 대상자의 가치관, 신념, 두려움을 사정한다.';why='의사결정 갈등은 흔히 가치관 사이의 충돌에서 비롯되므로 이를 명확히 해야 한다.'},
        @{plan='가족 등 의사결정에 영향을 주는 사람과 그들의 의견을 사정한다.';why='주변 사람의 기대와 압력은 결정을 어렵게 만드는 요인이 될 수 있다.'})
    ther = @(
        @{plan='대상자가 고민과 감정을 표현할 수 있도록 충분한 시간을 제공하고 경청한다.';why='감정을 정리하면 결정 과정에서의 불안이 줄어든다.'},
        @{plan='각 선택지의 이점, 위험, 예상 결과를 쉬운 말로 정리하여 함께 비교한다.';why='구조화된 정보는 대상자가 합리적으로 선택지를 비교하도록 돕는다.'},
        @{plan='대상자가 자신의 가치와 우선순위를 명확히 하도록 돕는다.';why='가치관에 맞는 결정은 결정 후 후회를 줄이고 만족감을 높인다.'},
        @{plan='의료진과 충분히 상담할 수 있도록 면담 기회를 마련하고 질문을 미리 정리하도록 돕는다.';why='의료진과의 직접적인 소통은 정확한 정보를 얻고 신뢰를 높인다.'},
        @{plan='대상자의 결정을 존중하고 결정에 대한 지지를 표현한다.';why='결정이 존중받으면 자율성이 보장되고 치료에 대한 협조가 높아진다.'})
    edu = @(
        @{plan='대상자에게 장단점 목록 작성 등 단계적 의사결정 방법을 교육한다.';why='체계적인 방법은 복잡한 결정을 정리하는 데 도움이 된다.'},
        @{plan='대상자와 가족에게 결정에 필요한 정보를 얻을 수 있는 신뢰할 만한 자료와 상담 창구를 안내한다.';why='정확한 정보원은 잘못된 정보로 인한 혼란을 줄인다.'})
}
$script:Templates['수술부위 감염의 위험'] = @{
    en = 'Risk for surgical site infection'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '1. 감염 Infection'
    page = $null
    problem = '수술부위 감염 위험'
    priority = 5
    reason = '아직 나타나지 않은 위험 진단이므로 실제적 진단보다 우선순위가 낮지만 안전 요구로서 예방이 필요하다'
    evalData = '수술 부위의 발적·부종·열감·삼출물, 체온, WBC·CRP 추이, 혈당, 배액 양상, 상처 관리 방법 설명 여부'
    keywords = '수술 부위|수술부위|절개 부위|incision|surgical site|\bSSI\b|봉합|suture|staple|post ?op|POD|수술 후|드레싱|dressing|배액관|JP drain|hemovac|창상|wound'
    cause = '수술로 인한 피부 보호막 손상'
    long = '대상자는 퇴원 시까지 수술 부위 감염 없이 상처가 치유될 것이다.'
    short = @('대상자는 3일 내 수술 부위에 발적, 부종, 화농성 삼출물이 나타나지 않을 것이다.','대상자는 2일 내 수술 부위 감염 징후를 세 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매 듀티마다 수술 부위의 발적, 부종, 열감, 통증 증가, 삼출물의 양과 색, 봉합 상태를 사정한다.';why='수술 부위 감염은 대개 수술 후 수일~30일 내에 국소 증상으로 먼저 나타나므로 조기 발견이 중요하다.'},
        @{plan='매 4시간마다 체온을 측정하고 WBC, CRP, 상처 배양 결과를 확인한다.';why='발열과 염증 지표 상승은 감염의 전신 반응을 나타낸다.'},
        @{plan='혈당, 영양 상태(알부민), 흡연력 등 감염 위험 요인을 확인한다.';why='고혈당, 영양 불량, 흡연은 상처 치유를 늦추고 감염 위험을 높인다.'})
    ther = @(
        @{plan='드레싱 교환 시 손 위생과 무균술을 철저히 지키고 병원 지침에 따라 드레싱을 관리한다.';why='무균적 상처 관리는 외부 미생물의 침입을 막는 가장 기본적인 방법이다.'},
        @{plan='처방에 따라 예방적 항생제를 정해진 시간에 투여한다.';why='적절한 시점의 항생제 투여는 수술 부위의 세균 증식을 막는다.'},
        @{plan='배액관의 개방성과 배액 양상을 확인하고 배액 주머니를 삽입 부위보다 낮게 유지한다.';why='원활한 배액은 체액 고임을 막고, 역류를 방지하여 감염을 예방한다.'},
        @{plan='처방에 따라 혈당을 측정하고 목표 범위로 유지되도록 관리한다.';why='고혈당은 백혈구 기능을 떨어뜨려 감염 위험을 높인다.'},
        @{plan='금기가 아닐 시 단백질과 수분 섭취를 격려한다.';why='단백질은 조직 재생과 면역 기능에 필수적이다.'})
    edu = @(
        @{plan='대상자와 보호자에게 수술 부위를 만지지 않고 젖지 않게 관리하는 방법과 손 씻기를 교육한다.';why='손을 통한 오염과 습기는 상처 감염의 주요 원인이다.'},
        @{plan='퇴원 후 발열, 상처의 발적·부종·고름이 생기면 즉시 병원에 알리도록 교육하고 금연을 권장한다.';why='퇴원 후에도 감염이 생길 수 있어 조기 발견이 필요하며, 흡연은 조직 산소화를 떨어뜨려 치유를 늦춘다.'})
}
$script:Templates['흡인의 위험'] = @{
    en = 'Risk for aspiration'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '흡인 위험'
    priority = 1
    reason = '아직 발생하지 않은 위험 진단이지만 흡인은 기도를 막고 흡인성 폐렴을 일으켜 ABC 중 기도와 호흡을 직접 위협한다'
    evalData = '삼킴 기능 선별검사 결과, 식사 중 기침·사레·목소리 변화, 호흡음, SpO2, 체온, 비위관 위치 확인 결과'
    keywords = '연하곤란|삼킴 곤란|삼킴곤란|dysphagia|사레|기침하며 먹|흡인|aspirat|비위관|\bL-?tube\b|\bNG ?tube\b|nasogastric|경관 영양|tube feeding|의식 저하|\bGCS\b|뇌졸중|stroke|구토 반사|gag reflex|흡인성 폐렴'
    cause = '연하 장애와 기침·구토 반사 저하'
    long = '대상자는 퇴원 시까지 흡인 없이 안전하게 영양을 섭취할 것이다.'
    short = @('대상자는 3일 내 식사 중 기침, 사레, 청색증 없이 식사를 마칠 것이다.','대상자는 2일 내 흡인을 예방하는 식사 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='구강 섭취 전 의식 수준, 기침·구토 반사, 삼킴 기능 선별검사 결과를 확인한다.';why='의식 저하와 반사 저하가 있으면 음식물이 기도로 들어가기 쉬우므로 섭취 전 안전 여부를 판단해야 한다.'},
        @{plan='식사 중과 식후 기침, 사레, 목소리 변화(젖은 목소리), 호흡곤란을 관찰한다.';why='이러한 증상은 흡인이 일어나고 있다는 신호로 즉시 식사를 중단하고 평가해야 한다.'},
        @{plan='매 4시간마다 호흡음, 호흡수, SpO2, 체온을 사정한다.';why='수포음, SpO2 저하, 발열은 흡인성 폐렴의 징후이다.'})
    ther = @(
        @{plan='식사 중과 식후 30분 이상 좌위 또는 침상머리를 30~45° 이상 올린다.';why='상체를 세우면 중력에 의해 음식물이 식도로 내려가고 역류가 줄어든다.'},
        @{plan='처방이나 언어치료사 권고에 따라 점도 조절식(걸쭉한 음식)을 제공하고 소량씩 천천히 먹게 하며 턱을 당기고 삼키도록 한다.';why='묽은 액체는 흡인되기 쉬우며, 턱 당기기 자세는 기도 입구를 좁혀 흡인을 줄인다.'},
        @{plan='경관 영양 전 비위관 위치(흡인액 pH, 처방 시 X-선)와 위 잔류량을 확인한다.';why='비위관이 잘못 위치하거나 잔류량이 많으면 영양액이 기도로 흡인될 위험이 높다.'},
        @{plan='침상 옆에 흡인기를 준비하고 필요시 구강·기도 분비물을 흡인한다.';why='분비물이나 구토물을 즉시 제거하면 기도 흡인을 예방할 수 있다.'},
        @{plan='식후 구강 간호를 시행한다.';why='구강 내 잔여 음식물과 세균을 제거하면 흡인 시 폐렴 위험을 줄인다.'})
    edu = @(
        @{plan='대상자와 보호자에게 바른 식사 자세, 한 입 크기, 천천히 먹기, 식사 중 대화 피하기를 교육한다.';why='올바른 식사 방법은 흡인 위험을 줄인다.'},
        @{plan='보호자에게 사레, 기침, 호흡곤란 발생 시 즉시 식사를 중단하고 알리도록 교육한다.';why='빠른 대처는 기도 폐쇄와 흡인성 폐렴을 예방한다.'})
}
$script:Templates['출혈의 위험'] = @{
    en = 'Risk for bleeding'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '출혈 위험'
    priority = 5
    reason = '아직 출혈이 나타나지 않은 위험 진단이지만 발생하면 순환량 감소로 생명을 위협하므로 안전 요구로서 예방이 필요하다'
    evalData = 'Hb·Hct, 혈소판 수, PT/INR·aPTT, 활력징후, 잇몸·코·소변·대변의 출혈 징후, 점상출혈·멍, 출혈 예방 방법 설명 여부'
    keywords = '혈소판 감소|thrombocytopenia|\bPLT\b|platelet|\bINR\b|\bPT\b|aPTT|항응고|anticoagul|와파린|warfarin|헤파린|heparin|에녹사파린|enoxaparin|\bDOAC\b|리바록사반|아픽사반|아스피린|aspirin|클로피도그렐|clopidogrel|혈우병|hemophilia|\bDIC\b|점상출혈|petechia|멍|bruis|간경화|cirrhosis|식도정맥류|varice'
    cause = '응고 기능 저하'
    long = '대상자는 퇴원 시까지 출혈 없이 지낼 것이다.'
    short = @('대상자는 3일 내 점상출혈, 잇몸 출혈, 혈뇨, 흑색변 등 출혈 징후 없이 지낼 것이다.','대상자는 2일 내 출혈 예방 방법을 세 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매 4시간마다 활력징후를 측정하고 빈맥, 혈압 저하 등 출혈 징후를 관찰한다.';why='출혈로 순환 혈액량이 줄면 보상 기전으로 맥박이 빨라지고 혈압이 떨어진다.'},
        @{plan='혈소판 수, Hb·Hct, PT/INR, aPTT 결과를 확인한다.';why='응고 검사와 혈액 검사는 출혈 위험 정도와 항응고 치료의 적정성을 객관적으로 나타낸다.'},
        @{plan='매 듀티마다 피부(점상출혈, 멍), 잇몸, 코, 소변, 대변, 침습 부위의 출혈 여부를 사정한다.';why='눈에 보이는 작은 출혈 징후를 조기에 발견하면 큰 출혈을 예방할 수 있다.'})
    ther = @(
        @{plan='가능하면 근육주사와 불필요한 침습적 처치를 피하고, 천자 후에는 5~10분 이상 압박한다.';why='응고 기능이 떨어지면 천자 부위의 지혈이 늦어져 혈종과 출혈이 생기기 쉽다.'},
        @{plan='부드러운 칫솔과 전기면도기를 사용하게 하고 낙상 위험 요인을 제거한다.';why='작은 외상도 출혈로 이어질 수 있으므로 손상을 최소화해야 한다.'},
        @{plan='처방에 따라 항응고제를 정확한 용량과 시간에 투여하고 응고 검사 결과를 확인한다.';why='항응고제는 치료 범위가 좁아 과량 시 출혈 위험이 크므로 검사 결과에 따라 용량을 조절한다.'},
        @{plan='변비를 예방하고 배변 시 무리하게 힘주지 않도록 한다.';why='과도한 힘주기는 점막 손상과 출혈, 뇌압 상승을 일으킬 수 있다.'},
        @{plan='처방에 따라 혈소판, 신선동결혈장 등 혈액 제제를 수혈하고 수혈 반응을 관찰한다.';why='부족한 응고 인자와 혈소판을 보충하여 출혈을 예방한다.'})
    edu = @(
        @{plan='대상자에게 출혈 징후(잇몸 출혈, 코피, 멍, 붉거나 검은 소변·대변)를 관찰하고 즉시 알리도록 교육한다.';why='대상자가 스스로 이상을 발견하면 조기에 치료할 수 있다.'},
        @{plan='의사와 상의 없이 아스피린, 소염진통제 등을 복용하지 않도록 교육한다.';why='이러한 약물은 혈소판 기능을 억제하여 출혈 위험을 높인다.'})
}
$script:Templates['피부 통합성 손상'] = @{
    en = 'Impaired skin integrity'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '피부손상'
    priority = 4
    reason = '이미 발생한 실제적인 신체 손상으로, 방치하면 감염과 조직 손상 악화로 이어지므로 생리적 요구로 다룬다'
    evalData = '상처의 위치·크기·깊이·삼출물·상처 기저부 상태, Braden 점수, 주변 피부 상태, 알부민·영양 상태, 체위 변경 수행 여부'
    keywords = '욕창|pressure (ulcer|injury)|bedsore|피부 손상|피부손상|skin integrity|찰과상|abrasion|열상|laceration|화상|burn|발적|궤양|ulcer|Braden|실금 피부염|기저귀 발진|박리|skin tear|당뇨발|diabetic foot'
    cause = '지속적인 압력과 부동'
    long = '대상자는 퇴원 시 손상된 피부가 치유되고 추가 손상이 없을 것이다.'
    short = @('대상자는 1주일 내 상처의 크기가 감소하고 삼출물이 줄어들 것이다.','대상자는 3일 내 피부 손상 예방 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매일 상처의 위치, 크기(길이×너비×깊이), 단계, 삼출물의 양·색·냄새, 상처 기저부와 주변 피부를 사정한다.';why='상처를 일관된 방법으로 측정해야 치유 경과를 객관적으로 평가할 수 있다.'},
        @{plan='Braden 척도로 피부 손상 위험을 사정한다.';why='Braden 척도는 감각 인지, 습기, 활동, 기동성, 영양, 마찰과 응전력을 평가하여 위험 요인을 파악한다.'},
        @{plan='영양 상태(알부민, 단백질 섭취량)와 수분 상태를 확인한다.';why='단백질과 수분 부족은 상처 치유를 지연시킨다.'})
    ther = @(
        @{plan='최소 2시간마다 체위를 변경하고 뼈 돌출 부위에 압력 분산 도구를 적용한다.';why='압력을 분산시키면 조직의 허혈을 줄여 추가 손상을 예방하고 치유를 돕는다.'},
        @{plan='처방이나 병원 지침에 따라 무균적으로 상처를 세척하고 적절한 드레싱을 적용한다.';why='상처 상태에 맞는 드레싱은 적절한 습윤 환경을 유지하여 상처 치유를 촉진하고 감염을 막는다.'},
        @{plan='피부를 깨끗하고 건조하게 유지하고 실금 시 즉시 닦은 후 피부 보호제를 사용한다.';why='습기와 배설물은 피부를 약하게 만들어 손상을 악화시킨다.'},
        @{plan='체위 변경 시 침대 위에서 끌지 않고 들어 올려 옮기며 침상머리는 가능한 30° 이하로 유지한다.';why='마찰과 응전력은 피부와 피하조직 손상을 일으킨다.'},
        @{plan='금기가 아닐 시 단백질, 비타민 C, 아연이 풍부한 식이와 충분한 수분 섭취를 격려한다.';why='이 영양소들은 콜라겐 합성과 조직 재생에 필요하다.'})
    edu = @(
        @{plan='대상자와 보호자에게 체위 변경 방법과 피부 관찰 방법을 교육한다.';why='보호자의 참여는 퇴원 후에도 피부 손상을 예방하는 데 필수적이다.'},
        @{plan='상처 부위의 발적 증가, 고름, 악취, 발열이 있으면 즉시 알리도록 교육한다.';why='이러한 증상은 상처 감염의 징후로 조기 치료가 필요하다.'})
}
$script:Templates['피부 통합성 손상의 위험'] = @{
    en = 'Risk for impaired skin integrity'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '피부손상 위험'
    priority = 5
    reason = '아직 피부 손상이 나타나지 않은 위험 진단이지만, 피부는 일차 방어벽이므로 안전 요구로서 예방이 필요하다'
    evalData = '피부 상태(발적, 건조, 습윤, 찰과상), 부동·실금 여부, 영양 상태(알부민), 피부 관리 방법 설명 여부'
    keywords = '피부 ?손상|skin integrity|피부 ?건조|건조한 피부|소양감|가려움|itching|pruritus|요실금|변실금|incontinence|기저귀|부종|edema|방사선 ?치료|radiation|침상안정|bed ?rest|와상|부동'
    cause = '부동과 피부의 습기 노출'
    long = '대상자는 퇴원 시까지 피부 손상 없이 지낼 것이다.'
    short = @('대상자는 입원 기간 동안 매일 사정 시 발적이나 찰과상 없이 피부가 온전하게 유지될 것이다.','대상자는 2일 내 피부 손상 예방 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='매 듀티마다 피부 상태(색, 온도, 습도, 탄력성, 발적·찰과상 유무)를 사정한다.';why='피부 변화를 조기에 발견하면 손상으로 진행되기 전에 중재할 수 있다.'},
        @{plan='실금, 발한, 배액 등으로 피부가 습기에 노출되는지 확인한다.';why='지속적인 습기는 피부를 침연시켜 마찰과 자극에 쉽게 손상되게 한다.'},
        @{plan='영양 상태(체중, 식이 섭취량, 알부민·총단백)와 수분 섭취량을 확인한다.';why='영양과 수분이 부족하면 피부의 탄력과 재생 능력이 떨어져 손상 위험이 높아진다.'})
    ther = @(
        @{plan='피부를 깨끗하고 건조하게 유지하고, 약산성 세정제로 닦은 뒤 두드려 말린다.';why='강한 비누와 문지르기는 피부 보호막을 손상시키므로 순한 세정과 건조가 피부를 보호한다.'},
        @{plan='건조한 피부에는 보습제를, 실금 부위에는 피부 보호 크림을 바른다.';why='보습제는 각질층의 수분을 유지하고, 보호 크림은 소변·대변의 자극 물질로부터 피부를 차단한다.'},
        @{plan='금기가 아닐 시 2시간마다 체위를 변경하고 침상 시트를 주름 없이 유지한다.';why='지속적인 압력과 마찰·주름은 국소 혈류를 떨어뜨려 피부 손상을 일으킨다.'},
        @{plan='체위 변경이나 이동 시 끌지 말고 들어 올려 옮긴다.';why='끌어당기면 마찰력과 응전력이 생겨 피부가 벗겨질 수 있다.'},
        @{plan='단백질과 수분 섭취를 격려한다.';why='단백질과 수분은 피부 세포 재생과 탄력 유지에 필요하다.'})
    edu = @(
        @{plan='대상자와 보호자에게 피부 관찰 방법과 발적·가려움 등 이상 시 알리도록 교육한다.';why='보호자가 함께 관찰하면 피부 변화를 더 빨리 발견할 수 있다.'},
        @{plan='피부를 긁지 않고 손톱을 짧게 유지하며 면 소재 옷을 입도록 교육한다.';why='긁기와 거친 옷감은 피부에 미세한 상처를 만들어 손상과 감염의 원인이 된다.'})
}
$script:Templates['성인 압박손상의 위험'] = @{
    en = 'Risk for adult pressure injury'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '압박손상 위험'
    priority = 5
    reason = '아직 압박손상이 발생하지 않은 위험 진단이지만, 발생하면 치유가 어렵고 감염으로 이어지므로 안전 요구로서 예방이 우선된다'
    evalData = 'Braden 점수, 뼈 돌출 부위의 발적(손가락 압박 시 창백해지는지), 체위 변경 수행 여부, 알부민 수치'
    keywords = '욕창|압박 ?손상|pressure (injury|ulcer)|decubitus|bed ?sore|Braden|브레이든|와상|침상안정|bed ?rest|편마비|하지 ?마비|사지 ?마비|paraplegia|quadriplegia|hemiplegia|의식 ?저하|체위 ?변경'
    cause = '장기간의 부동과 뼈 돌출 부위의 지속적인 압박'
    long = '대상자는 퇴원 시까지 압박손상 없이 지낼 것이다.'
    short = @('대상자는 입원 기간 동안 천골·발뒤꿈치 등 뼈 돌출 부위에 지속되는 발적 없이 지낼 것이다.','대상자(보호자)는 3일 내 2시간마다 체위 변경을 스스로 수행할 것이다.')
    diag = @(
        @{plan='입원 시와 매일 Braden 척도로 압박손상 위험도를 사정한다.';why='Braden 척도는 감각, 습기, 활동, 움직임, 영양, 마찰·응전력을 평가하며 18점 이하이면 위험군으로 예방 중재를 시작한다.'},
        @{plan='매 듀티마다 뼈 돌출 부위(천골, 미골, 발뒤꿈치, 대전자, 후두부)의 피부를 관찰하고 손가락으로 눌러 창백해지는지 확인한다.';why='눌러도 창백해지지 않는 발적은 1단계 압박손상의 징후이므로 조기에 발견해야 진행을 막을 수 있다.'},
        @{plan='의료기기(산소 캐뉼라, 튜브, 보조기)가 닿는 피부를 확인한다.';why='의료기기에 의한 지속적 압박도 압박손상의 흔한 원인이다.'})
    ther = @(
        @{plan='금기가 아닐 시 최소 2시간마다 체위를 변경하고 30도 측위를 취해준다.';why='압력을 주기적으로 분산시켜 조직의 허혈을 예방하며, 30도 측위는 대전자에 직접 압력이 가는 것을 피한다.'},
        @{plan='압력 분산 매트리스를 적용하고 발뒤꿈치는 베개로 띄워준다.';why='압력 분산 용품은 체중을 넓게 분산시키고 발뒤꿈치를 띄우면 압력이 완전히 제거된다.'},
        @{plan='금기가 아닐 시 침상 머리를 30도 이하로 유지한다.';why='침상 머리를 높이면 몸이 아래로 미끄러져 천골 부위에 응전력이 커진다.'},
        @{plan='실금 시 즉시 닦고 피부 보호제를 적용하여 피부를 건조하게 유지한다.';why='습기는 피부를 약하게 만들어 압력과 마찰에 쉽게 손상된다.'},
        @{plan='영양 상태를 확인하고 단백질·열량 섭취를 격려하며 필요시 영양사와 협의한다.';why='단백질과 열량이 부족하면 조직이 압력에 견디는 힘과 회복력이 떨어진다.'})
    edu = @(
        @{plan='대상자와 보호자에게 체위 변경 방법과 시간 간격을 시범을 보이며 교육한다.';why='보호자가 직접 수행할 수 있으면 퇴원 후에도 압박손상 예방이 지속된다.'},
        @{plan='뼈 돌출 부위를 마사지하지 않고, 발적이 사라지지 않으면 즉시 알리도록 교육한다.';why='발적 부위의 마사지는 손상된 조직을 더 악화시킬 수 있다.'})
}
$script:Templates['아동 압박손상의 위험'] = @{
    en = 'Risk for child pressure injury'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '압박손상 위험'
    priority = 5
    reason = '아직 압박손상이 발생하지 않은 위험 진단이지만, 아동은 피부가 얇고 의료기기 사용이 많아 안전 요구로서 예방이 필요하다'
    evalData = 'Braden Q 점수, 후두부·귀·발뒤꿈치 및 의료기기 접촉 부위의 발적, 체위 변경 수행 여부, 기저귀 부위 피부 상태'
    keywords = 'Braden ?Q|소아 ?욕창|아동 ?욕창|pediatric pressure|소아 ?중환자|PICU|NICU|진정|sedation|깁스|cast|부목|splint|뇌성마비|cerebral palsy|척수수막류|spina bifida|기관 ?삽관|intubat|산소 ?마스크|NIV'
    cause = '의료기기의 지속적인 압박과 움직임 제한'
    long = '아동은 퇴원 시까지 압박손상 없이 지낼 것이다.'
    short = @('아동은 입원 기간 동안 후두부와 의료기기 접촉 부위에 지속되는 발적 없이 지낼 것이다.','보호자는 3일 내 아동의 체위 변경과 피부 관찰 방법을 직접 수행할 것이다.')
    diag = @(
        @{plan='입원 시와 매일 Braden Q 척도로 압박손상 위험도를 사정한다.';why='Braden Q는 아동의 발달 특성과 조직 관류를 포함해 평가하는 소아용 도구로, 위험 아동을 조기에 선별할 수 있다.'},
        @{plan='매 듀티마다 후두부, 귀, 천골, 발뒤꿈치의 피부를 관찰한다.';why='영아와 어린 아동은 머리가 몸에 비해 커서 후두부에 압력이 집중된다.'},
        @{plan='의료기기(산소 캐뉼라, 마스크, 산소포화도 센서, 튜브 고정 테이프, 부목)가 닿는 부위를 듀티마다 확인한다.';why='아동의 압박손상은 의료기기로 인한 경우가 많으므로 접촉 부위를 반복 확인해야 한다.'})
    ther = @(
        @{plan='금기가 아닐 시 최소 2시간마다 체위를 변경하고 머리 위치도 바꿔준다.';why='압력을 분산시켜 조직 허혈을 예방하고 후두부 압박을 줄인다.'},
        @{plan='산소포화도 센서는 2~4시간마다 부착 위치를 바꾼다.';why='같은 부위에 계속 부착하면 압박과 열로 피부 손상이 생길 수 있다.'},
        @{plan='의료기기 아래에 폼 드레싱 등 보호 패드를 적용하고 크기에 맞는 기기를 사용한다.';why='보호 패드와 적절한 크기의 기기는 피부에 가해지는 압력과 마찰을 줄인다.'},
        @{plan='기저귀를 자주 확인하여 젖은 즉시 교체하고 피부를 건조하게 유지한다.';why='소변과 대변의 습기는 피부를 약하게 하여 압력과 마찰에 쉽게 손상되게 한다.'},
        @{plan='연령에 맞는 영양과 수분 섭취를 격려한다.';why='충분한 영양과 수분은 피부 조직의 저항력과 회복력을 높인다.'})
    edu = @(
        @{plan='보호자에게 체위 변경 방법과 피부 관찰 부위를 시범을 보이며 교육한다.';why='보호자가 아동 곁에 가장 오래 있으므로 직접 관찰하고 수행하면 예방 효과가 커진다.'},
        @{plan='보호자에게 기기 주변 피부가 붉어지거나 벗겨지면 즉시 알리도록 교육한다.';why='조기 발견 시 기기 위치 조정만으로도 손상 진행을 막을 수 있다.'})
}
$script:Templates['조직 통합성 손상'] = @{
    en = 'Impaired tissue integrity'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '조직손상'
    priority = 5
    reason = '실제 조직 손상이 있어 감염과 합병증으로 진행할 수 있으므로 안전 요구로서 상처 치유 촉진이 필요하다'
    evalData = '상처 크기·깊이, 육아조직 형성, 삼출물의 양·색·냄새, 상처 주변 피부 상태, 감염 징후, 상처 관리 방법 설명 여부'
    keywords = '조직 ?손상|tissue integrity|궤양|ulcer|화상|burn|열상|laceration|괴사|necrosis|necrotic|당뇨발|diabetic foot|육아조직|granulation|삼출물|exudate|드레싱|dressing|점막염|mucositis|욕창 ?[2-4]단계|stage [2-4]'
    cause = '기계적 손상과 국소 혈액순환 저하'
    long = '대상자는 퇴원 시 상처가 감염 없이 치유 과정에 있을 것이다.'
    short = @('대상자는 1주일 내 상처의 크기가 감소하고 붉은 육아조직이 관찰될 것이다.','대상자는 3일 내 상처 관리 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='드레싱 교환 시마다 상처의 위치, 크기(길이·너비·깊이), 상처 바닥 조직의 색, 삼출물의 양·색·냄새를 사정하고 기록한다.';why='상처 상태를 체계적으로 반복 측정해야 치유 진행 정도를 평가하고 중재를 수정할 수 있다.'},
        @{plan='상처 주변 피부의 발적, 열감, 부종, 통증과 발열 여부를 확인한다.';why='감염은 상처 치유를 지연시키는 가장 흔한 원인이므로 조기 발견이 중요하다.'},
        @{plan='치유에 영향을 주는 요인(혈당, 알부민, Hb, 말초 순환, 흡연)을 확인한다.';why='고혈당, 저단백, 빈혈, 혈류 저하는 조직에 산소와 영양 공급을 줄여 치유를 늦춘다.'})
    ther = @(
        @{plan='처방에 따라 무균술로 상처를 세척하고 상처 상태에 맞는 드레싱을 적용한다.';why='적절한 세척과 습윤 드레싱은 괴사조직과 세균을 줄이고 상처 치유에 알맞은 환경을 만든다.'},
        @{plan='손상 부위에 압력이 가지 않도록 체위를 조정한다.';why='손상 부위의 압박은 혈류를 떨어뜨려 조직 손상을 악화시킨다.'},
        @{plan='처방에 따라 항생제나 국소 치료제를 투여하고 효과를 확인한다.';why='감염이 있거나 위험이 높을 때 항균 치료는 치유를 방해하는 세균 부담을 줄인다.'},
        @{plan='단백질, 비타민 C, 아연이 풍부한 식이와 충분한 수분 섭취를 격려한다.';why='단백질과 비타민 C는 콜라겐 합성에, 아연은 세포 증식에 필요하여 상처 치유를 촉진한다.'},
        @{plan='필요시 처방에 따라 진통제를 드레싱 30분 전에 투여한다.';why='드레싱 중 통증을 줄이면 대상자의 협조가 좋아지고 스트레스가 감소한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 상처 관리 방법과 감염 징후(발적, 열감, 고름, 발열)를 교육한다.';why='대상자가 이상 징후를 알면 합병증을 조기에 알릴 수 있다.'},
        @{plan='금연과 혈당 조절(당뇨 시)의 중요성을 교육한다.';why='흡연은 혈관을 수축시키고 고혈당은 면역 기능을 떨어뜨려 상처 치유를 늦춘다.'})
}
$script:Templates['수술 후 회복 지연'] = @{
    en = 'Delayed surgical recovery'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '수술 후 회복 지연'
    priority = 4
    reason = '수술 후 활동·식사·자가간호 등 기본적인 생리적 기능의 회복이 늦어지고 있어 다른 생리적 욕구 충족을 위해 중재가 필요하다'
    evalData = '보행 거리와 활동 수준, 식이 진행 정도, 장음·배변 여부, 수술 부위 치유 상태, 통증 점수, 자가간호 수행 정도'
    keywords = '회복 ?지연|delayed (surgical )?recovery|수술 후 [0-9]+ ?일|POD ?#?[0-9]+|post ?op(erative)? day|재원 ?기간|퇴원 ?지연|장 ?마비|ileus|창상 ?열개|dehiscence|조기 ?이상 ?지연'
    cause = '수술 후 통증과 활동 감소'
    long = '대상자는 퇴원 시 도움 없이 일상생활 활동을 수행할 것이다.'
    short = @('대상자는 3일 내 하루 3회 이상 복도 보행을 할 것이다.','대상자는 3일 내 처방된 식이를 오심 없이 섭취할 것이다.')
    diag = @(
        @{plan='매 듀티마다 수술 부위 상태(발적, 부종, 삼출물, 봉합 상태)와 V/S를 사정한다.';why='창상 감염이나 열개는 회복 지연의 주요 원인이므로 조기 발견이 필요하다.'},
        @{plan='활동 수준(보행 거리, 이동 능력), 식이 섭취량, 장음과 배변·배뇨 상태를 확인한다.';why='활동과 장 기능 회복 정도는 수술 후 회복을 평가하는 객관적인 지표다.'},
        @{plan='통증 점수(NRS), 피로, 수면 상태를 사정한다.';why='조절되지 않는 통증과 피로는 활동과 식사를 방해하여 회복을 늦춘다.'})
    ther = @(
        @{plan='처방에 따라 진통제를 규칙적으로 투여하여 활동 전 통증을 조절한다.';why='통증이 조절되어야 조기 이상과 심호흡을 적극적으로 할 수 있다.'},
        @{plan='금기가 아닐 시 점진적인 조기 이상과 보행을 돕는다.';why='조기 보행은 장운동 회복, 폐 합병증과 심부정맥혈전증 예방, 근력 유지에 효과적이다.'},
        @{plan='처방에 따라 식이를 진행하고 단백질과 열량 섭취를 격려한다.';why='충분한 영양은 상처 치유와 체력 회복에 필요하다.'},
        @{plan='매 시간 심호흡과 기침, 필요시 강화폐활량계 사용을 격려한다.';why='폐 확장을 촉진하여 무기폐와 폐렴 같은 수술 후 합병증을 예방한다.'},
        @{plan='무균술로 상처를 관리하고 드레싱을 지침에 따라 교환한다.';why='창상 감염을 예방하여 회복 지연을 막는다.'})
    edu = @(
        @{plan='대상자에게 단계별 활동 증가 계획과 조기 보행의 이점을 교육한다.';why='목표와 이유를 이해하면 대상자가 스스로 회복 활동에 참여하게 된다.'},
        @{plan='대상자와 보호자에게 퇴원 후 상처 관리와 이상 증상(발열, 상처 분비물, 심한 통증) 시 병원에 연락하도록 교육한다.';why='퇴원 후에도 합병증을 조기에 발견하여 회복이 더 늦어지는 것을 막는다.'})
}
$script:Templates['말초 신경혈관 기능장애의 위험'] = @{
    en = 'Risk for peripheral neurovascular dysfunction'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '신경혈관 기능장애 위험'
    priority = 5
    reason = '아직 발생하지 않은 위험 진단이지만, 구획증후군 등이 생기면 사지 기능을 잃을 수 있으므로 안전 요구로서 집중 관찰이 필요하다'
    evalData = '손상 부위 원위부의 5P(통증, 창백, 맥박, 감각이상, 마비), 모세혈관 재충전 시간, 부종, 피부 온도'
    keywords = '골절|fracture|깁스|cast|석고 ?붕대|부목|splint|견인|traction|구획 ?증후군|compartment|외고정|external fixat|정형외과|ORIF|인공 ?관절|arthroplasty|압박 ?붕대|tourniquet|지혈대|저림|numbness|tingling'
    cause = '골절과 석고붕대로 인한 압박'
    long = '대상자는 퇴원 시까지 손상 부위 원위부의 정상 감각·운동·순환을 유지할 것이다.'
    short = @('대상자는 입원 기간 동안 원위부 맥박이 촉지되고 모세혈관 재충전 시간이 2초 이내로 유지될 것이다.','대상자는 1일 내 저림, 창백, 통증 증가 등 이상 증상을 즉시 알려야 함을 말로 표현할 것이다.')
    diag = @(
        @{plan='수술·석고 적용 후 24시간 동안 1~2시간마다, 이후 4시간마다 원위부 신경혈관 상태(5P: 통증, 창백, 맥박, 감각이상, 마비)를 반대편과 비교하여 사정한다.';why='5P 변화는 혈류 장애나 신경 압박의 초기 징후이며 반대편과 비교하면 이상을 정확하게 알 수 있다.'},
        @{plan='모세혈관 재충전 시간, 피부 색과 온도, 부종 정도를 확인한다.';why='재충전 시간 지연과 차고 창백한 피부는 동맥 순환 저하를 의미한다.'},
        @{plan='진통제로 조절되지 않거나 수동적으로 손·발가락을 펼 때 심해지는 통증이 있는지 확인한다.';why='진통제에 반응하지 않는 심한 통증과 수동 신전 시 통증은 구획증후군의 초기 징후다.'})
    ther = @(
        @{plan='금기가 아닐 시 손상된 사지를 심장 높이 정도로 거상한다.';why='정맥 귀환을 도와 부종을 줄이며, 구획증후군이 의심되면 과도한 거상은 동맥 혈류를 줄이므로 심장 높이를 유지한다.'},
        @{plan='석고붕대, 붕대, 부목이 너무 조이지 않는지 확인하고 손가락 하나가 들어갈 정도로 유지한다.';why='외부 압박은 혈류와 신경을 압박하여 기능장애를 일으킨다.'},
        @{plan='금기가 아닐 시 처방에 따라 손상 후 24~48시간 동안 냉요법을 적용한다.';why='냉요법은 혈관을 수축시켜 부종과 통증을 줄인다.'},
        @{plan='이상 징후(맥박 소실, 심한 통증, 감각 저하) 발견 시 즉시 의사에게 보고한다.';why='구획증후군은 수 시간 내 비가역적 신경·근육 손상을 일으키므로 신속한 감압이 필요하다.'},
        @{plan='금기가 아닐 시 손·발가락의 능동 운동을 격려한다.';why='근육 수축은 정맥 귀환을 촉진하여 부종과 혈전 형성을 줄인다.'})
    edu = @(
        @{plan='대상자와 보호자에게 저림, 감각 저하, 창백, 차가움, 통증 증가 시 즉시 알리도록 교육한다.';why='대상자가 느끼는 감각 변화가 가장 빠른 경고 신호이다.'},
        @{plan='석고붕대 안에 물건을 넣거나 젖지 않도록 하고 사지를 올려두는 방법을 교육한다.';why='석고 안의 이물질과 습기는 피부 손상과 압박을 일으킬 수 있다.'})
}
$script:Templates['손상의 위험'] = @{
    en = 'Risk for injury'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '손상 위험'
    priority = 5
    reason = '아직 손상이 발생하지 않은 위험 진단이지만, 손상이 생기면 회복이 지연되므로 안전 요구로서 예방이 필요하다'
    evalData = '손상 발생 여부, 위험 요인(의식·감각·운동 기능, 약물) 변화, 환경 안전 조치 유지 여부, 안전 수칙 설명 여부'
    keywords = '손상 위험|risk for injury|혼돈|섬망|delirium|confusion|지남력 ?(저하|장애)|disorient|경련|seizure|간질|epilepsy|시력 ?저하|시각 ?장애|감각 ?저하|neuropathy|어지러|dizziness|현훈|vertigo|진정제|sedative|치매|dementia'
    cause = '감각·지각 기능 저하'
    long = '대상자는 퇴원 시까지 신체 손상 없이 지낼 것이다.'
    short = @('대상자는 입원 기간 동안 낙상, 화상, 타박상 등의 손상 없이 지낼 것이다.','대상자(보호자)는 2일 내 손상 예방을 위한 안전 수칙을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='입원 시와 매 듀티마다 손상 위험 요인(의식 수준, 지남력, 시력·감각, 근력, 보행 상태)을 사정한다.';why='위험 요인을 파악해야 대상자에게 맞는 예방 중재를 계획할 수 있다.'},
        @{plan='손상 위험을 높이는 약물(진정제, 수면제, 이뇨제, 항고혈압제, 항응고제) 복용 여부를 확인한다.';why='이 약물들은 어지러움, 기립성 저혈압, 졸음, 출혈 경향을 일으켜 손상 위험을 높인다.'},
        @{plan='병실 환경(조명, 바닥 물기, 장애물, 침대 높이, 호출벨 위치)을 점검한다.';why='환경적 위험 요소는 손상의 주요 원인이므로 정기적인 점검이 필요하다.'})
    ther = @(
        @{plan='침대를 가장 낮게 하고 바퀴를 고정하며 필요시 침대 난간을 올린다.';why='낮고 고정된 침대는 낙상 시 충격을 줄이고 이동 중 침대가 밀리는 것을 막는다.'},
        @{plan='호출벨과 자주 쓰는 물건을 손이 닿는 곳에 둔다.';why='혼자 무리하게 움직이는 것을 줄여 손상을 예방한다.'},
        @{plan='야간에 보조 조명을 켜고 바닥의 물기와 장애물을 제거한다.';why='시야 확보와 정돈된 환경은 미끄러짐과 걸려 넘어짐을 예방한다.'},
        @{plan='경련 위험이 있으면 경련 시 대처 물품(흡인기, 산소)을 준비하고 침대 난간에 패드를 댄다.';why='경련 시 기도를 확보하고 외상을 예방하기 위해 미리 준비가 필요하다.'},
        @{plan='자주 순회하고 필요시 보호자가 곁에 있도록 한다.';why='가까이 관찰하면 위험 행동을 미리 발견하여 손상을 예방할 수 있다.'})
    edu = @(
        @{plan='대상자와 보호자에게 병실 안전 수칙(호출벨 사용, 미끄럼 방지 신발, 천천히 일어나기)을 교육한다.';why='안전 수칙을 알고 실천하면 스스로 손상을 예방할 수 있다.'},
        @{plan='보호자에게 퇴원 후 가정 환경의 위험 요소(문턱, 미끄러운 욕실, 어두운 조명)를 개선하도록 교육한다.';why='가정 내 위험 요소를 줄이면 퇴원 후 손상을 예방할 수 있다.'})
}
$script:Templates['영아 돌연사의 위험'] = @{
    en = 'Risk for sudden infant death'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '영아 돌연사 위험'
    priority = 5
    reason = '아직 발생하지 않은 위험 진단이지만, 발생하면 생명을 잃게 되고 수면 환경 교정으로 예방할 수 있어 안전 요구로서 중재가 필요하다'
    evalData = '수면 자세(바로 눕혀 재우는지), 수면 환경(단단한 매트리스, 푹신한 침구·인형 유무, 같은 침대 사용 여부), 간접흡연 노출, 보호자의 안전 수면 수칙 설명 여부'
    keywords = '영아 ?돌연사|SIDS|SUID|sudden infant|엎드려 ?재|prone sleep|조산아|미숙아|preterm|premature|저체중 ?출생|LBW|간접 ?흡연|secondhand smoke|같은 ?침대|co-?sleeping|bed ?sharing'
    cause = '엎드려 재우기와 안전하지 않은 수면 환경'
    long = '보호자는 퇴원 시 안전한 수면 환경을 준비하고 영아를 바로 눕혀 재울 것이다.'
    short = @('보호자는 1일 내 안전 수면 수칙을 세 가지 이상 말로 표현할 것이다.','보호자는 2일 내 영아를 단단한 매트리스 위에 바로 눕혀 재우는 모습을 보일 것이다.')
    diag = @(
        @{plan='영아의 위험 요인(조산, 저체중 출생, 생후 1~6개월, 가족 흡연)을 확인한다.';why='생후 1~6개월, 조산·저체중아, 간접흡연 노출 영아는 영아 돌연사 위험이 높다.'},
        @{plan='보호자의 재우는 자세, 침구, 같은 침대 사용, 실내 온도 등 수면 습관을 사정한다.';why='엎드려 재우기, 푹신한 침구, 성인과 같은 침대에서 자는 것은 질식과 돌연사의 주요 위험 요인이다.'},
        @{plan='보호자의 영아 돌연사 예방에 대한 지식 정도를 확인한다.';why='보호자가 알고 있는 내용을 확인해야 부족한 부분을 중심으로 교육할 수 있다.'})
    ther = @(
        @{plan='병원에서 영아를 재울 때 항상 바로 눕혀 재우는 모습을 보여준다.';why='의료인의 행동은 보호자에게 본보기가 되어 가정에서도 같은 방법을 따르게 한다.'},
        @{plan='단단한 매트리스에 꼭 맞는 시트만 사용하고 베개, 이불, 인형, 범퍼를 치운다.';why='푹신한 물건은 얼굴을 덮거나 재호흡을 일으켜 질식과 돌연사의 위험을 높인다.'},
        @{plan='실내를 적정 온도로 유지하고 영아에게 옷을 과하게 입히지 않는다.';why='과열은 영아 돌연사의 위험 요인이다.'},
        @{plan='금기가 아닐 시 모유 수유를 격려하고 지지한다.';why='모유 수유는 영아 돌연사 위험을 낮추는 보호 요인이다.'},
        @{plan='깨어 있고 보호자가 지켜볼 때 엎드린 자세 놀이(tummy time)를 하도록 돕는다.';why='엎드린 자세 놀이는 목·어깨 근육 발달을 돕고 머리 모양 변형을 예방한다.'})
    edu = @(
        @{plan='보호자에게 안전 수면 수칙(바로 눕혀 재우기, 단단한 매트리스, 침구·인형 치우기, 같은 방 다른 침대 사용)을 교육한다.';why='안전 수면 수칙 실천은 영아 돌연사를 예방하는 가장 효과적인 방법이다.'},
        @{plan='보호자와 가족에게 임신 중과 출생 후 금연, 영아 주변 간접흡연을 피하도록 교육한다.';why='흡연 노출은 영아의 각성 반응을 떨어뜨려 돌연사 위험을 높인다.'})
}
$script:Templates['질식의 위험'] = @{
    en = 'Risk for suffocation'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '2. 신체손상 Physical injury'
    page = $null
    problem = '질식 위험'
    priority = 5
    reason = '아직 발생하지 않은 위험 진단이지만, 질식은 기도를 막아 생명을 위협하므로 위험 진단 중 가장 먼저 예방해야 한다'
    evalData = '연하 상태와 식사 중 기침·사레 여부, 주변 환경의 질식 위험 물건 제거 여부, 보호자의 질식 예방 수칙과 응급처치 설명 여부'
    keywords = '질식|suffocation|choking|사레|연하 ?곤란|삼킴 ?곤란|dysphagia|흡인|aspiration|이물|foreign body|작은 ?장난감|땅콩|떡|비닐|의식 ?저하|목 ?졸|strangulation'
    cause = '연하 기능 저하와 환경 내 질식 위험 물건'
    long = '대상자는 퇴원 시까지 질식 사고 없이 지낼 것이다.'
    short = @('대상자는 입원 기간 동안 식사 중 사레나 기도 막힘 없이 지낼 것이다.','대상자(보호자)는 2일 내 질식 예방 방법과 응급처치(하임리히법)를 말로 표현할 것이다.')
    diag = @(
        @{plan='의식 수준, 연하 능력, 구토 반사, 기침 반사를 사정한다.';why='의식이 떨어지거나 연하·기침 반사가 약하면 음식이나 분비물로 기도가 막힐 위험이 높다.'},
        @{plan='식사 중 기침, 사레, 목소리 변화, 산소포화도 저하가 있는지 관찰한다.';why='식사 중 이러한 증상은 음식이 기도로 넘어가는 신호다.'},
        @{plan='대상자 주변 환경(작은 물건, 비닐봉지, 끈, 침구)을 점검한다.';why='특히 영유아와 인지 저하 대상자는 주변 물건으로 질식할 위험이 높다.'})
    ther = @(
        @{plan='금기가 아닐 시 식사 시 상체를 60~90도 세우고 식후 30분간 유지한다.';why='상체를 세우면 음식이 기도로 넘어가는 것을 막고 역류를 줄인다.'},
        @{plan='연하 상태에 맞는 식이 형태(점도 증진, 잘게 자른 음식)를 제공하고 한 입 양을 적게 한다.';why='대상자의 연하 능력에 맞는 음식은 기도 폐쇄 위험을 줄인다.'},
        @{plan='침상 옆에 흡인기를 준비하고 필요시 구강 분비물을 흡인한다.';why='분비물이나 이물을 빨리 제거하여 기도를 유지할 수 있다.'},
        @{plan='영유아의 경우 손이 닿는 곳에서 작은 물건과 비닐봉지, 끈을 치운다.';why='영유아는 물건을 입에 넣는 발달 특성이 있어 환경 정리가 가장 확실한 예방법이다.'})
    edu = @(
        @{plan='대상자와 보호자에게 천천히 조금씩 먹기, 식사 중 말하지 않기 등 질식 예방 수칙을 교육한다.';why='식사 습관을 바꾸면 음식으로 인한 기도 폐쇄를 줄일 수 있다.'},
        @{plan='보호자에게 연령에 맞는 기도 폐쇄 응급처치(영아: 등 두드리기·가슴 압박, 소아·성인: 하임리히법)를 교육한다.';why='질식은 수 분 내 뇌손상을 일으키므로 보호자의 즉각적인 응급처치가 생명을 지킨다.'})
}
$script:Templates['비자살적 자해의 위험'] = @{
    en = 'Risk for nonsuicidal self-injury'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '3. 폭력 Violence'
    page = $null
    problem = '자해 위험'
    priority = 5
    reason = '아직 자해 행동이 나타나지 않은 위험 진단이지만, 신체 손상과 이후 자살 위험으로 이어질 수 있어 안전 요구로서 우선 중재가 필요하다'
    evalData = '자해 충동 표현과 행동 여부, 신체의 새로운 상처 유무, 대처 방법 사용 여부, 감정을 말로 표현하는 정도'
    keywords = '자해|self-?harm|self-?injur|NSSI|손목을 ?긋|긋는|커팅|cutting|화상을 ?입히|머리를 ?박|경계성|borderline|충동 ?조절|impulsiv|학대 ?경험|abuse|트라우마|trauma'
    cause = '견디기 어려운 감정을 조절하는 대처 기술 부족'
    long = '대상자는 퇴원 시 자해 충동이 들 때 자해 대신 건강한 대처 방법을 사용할 것이다.'
    short = @('대상자는 입원 기간 동안 자해 행동 없이 지낼 것이다.','대상자는 1주일 내 자해 충동이 들 때 사용할 수 있는 대처 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='자해 충동, 과거 자해 이력, 자해 방법과 빈도, 자해를 일으키는 상황을 사정한다.';why='자해를 유발하는 감정과 상황을 알아야 맞춤형 예방 계획을 세울 수 있다.'},
        @{plan='매 듀티마다 대상자의 기분, 행동 변화와 신체의 새로운 상처를 관찰한다.';why='자해는 숨기는 경우가 많아 주의 깊은 관찰로 조기에 발견해야 한다.'},
        @{plan='자살 사고 여부를 직접 묻고 확인한다.';why='비자살적 자해는 이후 자살 시도의 위험 요인이므로 자살 위험을 함께 평가해야 한다.'})
    ther = @(
        @{plan='병실에서 위험한 물건(칼, 면도기, 유리, 끈 등)을 제거한다.';why='자해 수단에 접근하지 못하게 하면 충동적인 자해를 예방할 수 있다.'},
        @{plan='비판하지 않는 태도로 치료적 관계를 형성하고 감정을 말로 표현하도록 격려한다.';why='수용적인 관계는 대상자가 자해 대신 감정을 말로 표현하도록 돕는다.'},
        @{plan='대상자와 함께 자해 충동이 들 때 사용할 대처 방법(얼음 쥐기, 운동, 일기 쓰기, 의료진에게 알리기)을 정한다.';why='대체 행동은 자해 없이 강한 감정을 견디도록 돕는다.'},
        @{plan='자해가 발생하면 차분하게 상처를 치료하고 행동보다 감정에 초점을 맞추어 대화한다.';why='과도한 관심이나 처벌은 자해를 강화할 수 있으므로 침착한 대응이 필요하다.'},
        @{plan='처방에 따라 약물을 투여하고 정신건강 전문가와 협력한다.';why='동반된 우울, 불안 등을 치료하면 자해 충동이 감소한다.'})
    edu = @(
        @{plan='대상자에게 감정 조절 기술(심호흡, 이완법, 감정 이름 붙이기)을 교육한다.';why='감정 조절 기술은 자해 외에 감정을 다루는 건강한 방법을 제공한다.'},
        @{plan='보호자에게 자해의 경고 신호와 위기 시 도움 받을 곳(자살예방 상담전화 109, 정신건강위기상담 1577-0199)을 교육한다.';why='보호자가 위기 신호를 알면 퇴원 후에도 신속하게 도움을 받을 수 있다.'})
}
$script:Templates['자살 행동의 위험'] = @{
    en = 'Risk for suicidal behavior'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '3. 폭력 Violence'
    page = $null
    problem = '자살 위험'
    priority = 5
    reason = '자살은 생명을 직접 위협하므로 위험 진단이지만 안전 요구 중 가장 먼저 중재해야 한다'
    evalData = '자살 사고·계획·수단 유무(C-SSRS 등), 기분 변화, 안전 계획 이해 정도, 지지 체계 활용 여부'
    keywords = '자살|suicid|죽고 ?싶|죽고싶|살고 ?싶지 ?않|사라지고 ?싶|유서|과량 ?복용|overdose|목을 ?매|투신|C-SSRS|우울증|major depress|절망|hopeless|희망이 ?없'
    cause = '우울과 절망감'
    long = '대상자는 퇴원 시 자살 사고가 들 때 안전 계획에 따라 도움을 요청할 것이다.'
    short = @('대상자는 입원 기간 동안 자해나 자살 시도 없이 지낼 것이다.','대상자는 3일 내 자살 사고가 들 때 연락할 사람과 기관을 두 곳 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='자살 사고, 구체적인 계획, 수단 접근성, 과거 시도 이력을 직접적으로 묻고 표준 도구(C-SSRS 등)로 사정한다.';why='자살에 대해 직접 묻는 것은 위험을 높이지 않으며, 계획과 수단이 구체적일수록 위험이 높다.'},
        @{plan='매 듀티마다 기분, 행동 변화(갑자기 차분해짐, 물건 정리, 작별 인사)를 관찰한다.';why='갑작스러운 기분 호전이나 정리 행동은 자살을 결심한 신호일 수 있다.'},
        @{plan='위험 요인(우울, 알코올, 최근의 상실, 만성 질환)과 보호 요인(가족, 종교, 미래 계획)을 확인한다.';why='위험 요인과 보호 요인을 함께 파악해야 위험도를 정확히 판단하고 보호 요인을 강화할 수 있다.'})
    ther = @(
        @{plan='병실과 소지품에서 위험한 물건(끈, 날카로운 물건, 약물, 유리)을 제거한다.';why='자살 수단에 대한 접근을 차단하는 것은 가장 효과적인 자살 예방 방법 중 하나다.'},
        @{plan='위험도에 따라 관찰 수준을 정하고(고위험 시 1:1 지속 관찰) 자주 순회한다.';why='가까운 관찰은 자살 시도를 즉시 발견하고 막을 수 있게 한다.'},
        @{plan='비판하지 않는 태도로 치료적 관계를 형성하고 감정 표현을 격려한다.';why='수용받는 경험은 고립감과 절망감을 줄이고 도움을 요청하게 한다.'},
        @{plan='대상자와 함께 경고 신호, 대처 방법, 연락할 사람과 기관을 담은 안전 계획을 작성한다.';why='구체적인 안전 계획은 위기 순간에 대상자가 따라 할 수 있는 행동 지침이 된다.'},
        @{plan='처방에 따라 항우울제를 투여하고, 복용 초기 기분과 행동 변화를 관찰한다.';why='항우울제 복용 초기에는 기력이 먼저 회복되어 자살 위험이 일시적으로 높아질 수 있다.'})
    edu = @(
        @{plan='대상자와 보호자에게 위기 시 도움 받을 곳(자살예방 상담전화 109, 정신건강위기상담 1577-0199, 119)을 교육한다.';why='도움 받을 곳을 미리 알면 위기 순간에 신속하게 연락할 수 있다.'},
        @{plan='보호자에게 자살 경고 신호와 가정 내 위험 물건(약물, 농약, 끈) 관리 방법을 교육한다.';why='가정 내 수단 제한과 보호자의 관찰은 퇴원 후 자살 위험을 줄인다.'})
}
$script:Templates['타인 지향적 폭력의 위험'] = @{
    en = 'Risk for other-directed violence'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '3. 폭력 Violence'
    page = $null
    problem = '폭력 위험'
    priority = 5
    reason = '아직 폭력이 발생하지 않은 위험 진단이지만, 대상자와 타인의 신체적 안전을 위협하므로 안전 요구로서 예방이 우선된다'
    evalData = '공격적 언어·행동 여부, 초조·흥분 정도, 분노를 말로 표현하는지, 폭력 사건 발생 여부'
    keywords = '폭력|violen|공격적|aggress|난폭|폭언|욕설|위협|threat|때리|hostil|적대|흥분|agitat|초조|조현병|schizophren|피해망상|paranoi|알코올 ?금단|withdrawal|분노 ?조절'
    cause = '충동 조절 능력 저하'
    long = '대상자는 퇴원 시 분노를 폭력 없이 말로 표현할 것이다.'
    short = @('대상자는 입원 기간 동안 타인에게 신체적 폭력 없이 지낼 것이다.','대상자는 1주일 내 화가 날 때 사용할 수 있는 대처 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='과거 폭력 이력, 물질 사용, 환각·망상 여부를 사정한다.';why='과거 폭력 이력은 가장 강력한 예측 요인이며 환각·망상과 물질 사용은 폭력 위험을 높인다.'},
        @{plan='매 듀티마다 폭력의 전조 증상(목소리 커짐, 주먹 쥠, 서성임, 노려봄, 위협적 언어)을 관찰한다.';why='전조 증상을 조기에 발견하면 폭력으로 진행되기 전에 중재할 수 있다.'},
        @{plan='폭력을 유발하는 상황(소음, 대기, 요구 거절)을 확인한다.';why='유발 요인을 알면 환경을 조정하여 폭력을 예방할 수 있다.'})
    ther = @(
        @{plan='자극이 적은 조용한 환경을 제공하고 위험한 물건을 제거한다.';why='과도한 자극은 흥분을 높이고 위험한 물건은 폭력 시 심각한 손상을 일으킨다.'},
        @{plan='차분하고 낮은 목소리로 짧고 분명하게 말하며 안전한 거리를 유지한다.';why='침착한 태도는 긴장을 낮추고, 출입구 쪽에 서서 거리를 두면 간호사의 안전을 지킬 수 있다.'},
        @{plan='분노를 말로 표현하도록 격려하고 신체 활동 등 에너지를 발산할 방법을 제공한다.';why='감정을 말이나 건설적인 활동으로 표현하면 신체적 공격 행동이 줄어든다.'},
        @{plan='처방에 따라 항정신병약물이나 진정제를 투여하고 효과와 부작용(진정, 추체외로 증상)을 확인한다.';why='약물은 심한 흥분을 빠르게 진정시켜 대상자와 타인의 안전을 지킨다.'},
        @{plan='다른 방법이 효과가 없을 때만 병원 지침에 따라 격리나 신체 억제를 시행하고 자주 관찰한다.';why='억제는 최후의 수단이며 억제 중 순환, 피부, 호흡 상태를 확인해 2차 손상을 예방해야 한다.'})
    edu = @(
        @{plan='대상자에게 분노 신호를 알아차리고 타임아웃, 심호흡 등으로 대처하는 방법을 교육한다.';why='분노를 스스로 조절하는 기술은 폭력 행동을 예방한다.'},
        @{plan='보호자에게 폭력 전조 증상과 위급 시 안전하게 피하고 도움을 요청하는 방법(112, 119)을 교육한다.';why='보호자가 대처 방법을 알면 가정에서 위기 상황에 안전하게 대응할 수 있다.'})
}
$script:Templates['알레르기 반응의 위험'] = @{
    en = 'Risk for allergy reaction'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '5. 방어과정 Defensive processes'
    page = $null
    problem = '알레르기 반응 위험'
    priority = 5
    reason = '아직 반응이 나타나지 않은 위험 진단이지만, 아나필락시스로 진행하면 기도와 순환을 위협하므로 안전 요구로서 예방이 필요하다'
    evalData = '알레르기 반응(두드러기, 가려움, 부종, 천명음, 저혈압) 발생 여부, 알레르기 표시 유지 여부, 알레르기 유발 물질 피하는 방법 설명 여부'
    keywords = '알레르기|알러지|allerg|과민 ?반응|hypersensitiv|아나필락시|anaphyla|두드러기|urticaria|페니실린|penicillin|조영제|contrast|라텍스|latex|땅콩|갑각류|에피펜|epipen|epinephrine auto'
    cause = '알려진 알레르기 유발 물질에 대한 노출 가능성'
    long = '대상자는 퇴원 시까지 알레르기 반응 없이 지낼 것이다.'
    short = @('대상자는 입원 기간 동안 두드러기, 호흡곤란 등 알레르기 반응 없이 지낼 것이다.','대상자는 2일 내 자신의 알레르기 유발 물질과 반응 시 대처 방법을 말로 표현할 것이다.')
    diag = @(
        @{plan='입원 시 약물, 음식, 라텍스, 조영제 등 알레르기 이력과 과거 반응 양상을 자세히 사정한다.';why='과거 반응의 종류와 심각도를 알아야 위험 물질을 피하고 대비할 수 있다.'},
        @{plan='새 약물(특히 항생제, 조영제) 투여 후 최소 30분간 피부 발진, 가려움, 부종, 천명음, 혈압 저하를 관찰한다.';why='즉시형 과민반응은 대부분 노출 후 수 분~1시간 안에 나타난다.'},
        @{plan='V/S와 SpO2를 확인하고 호흡음을 청진한다.';why='혈압 저하와 천명음, 산소포화도 저하는 아나필락시스의 위험 징후다.'})
    ther = @(
        @{plan='의무기록, 환자 팔찌, 침상에 알레르기 정보를 눈에 띄게 표시한다.';why='모든 의료진이 알레르기 정보를 공유해야 유발 물질 노출을 막을 수 있다.'},
        @{plan='약물 투여 전 알레르기 여부를 다시 확인하고 병원 지침에 따라 필요시 피부 반응 검사를 시행한다.';why='투여 전 재확인은 투약 오류로 인한 알레르기 반응을 예방한다.'},
        @{plan='라텍스 알레르기 시 라텍스가 없는 장갑과 기구를 사용한다.';why='라텍스 접촉은 피부 반응부터 아나필락시스까지 일으킬 수 있다.'},
        @{plan='응급 물품(에피네프린, 산소, 기도 유지 기구)을 준비하고, 반응 발생 시 즉시 유발 물질을 중단하고 의사에게 보고한다.';why='아나필락시스는 빠르게 진행하므로 즉각적인 유발 물질 중단과 에피네프린 투여가 생명을 지킨다.'})
    edu = @(
        @{plan='대상자에게 자신의 알레르기 유발 물질과 피하는 방법, 진료 시 항상 알리는 습관을 교육한다.';why='대상자가 스스로 알리면 다른 의료기관에서도 노출을 예방할 수 있다.'},
        @{plan='대상자와 보호자에게 알레르기 반응의 초기 증상과 에피네프린 자가주사기 사용법(처방 시), 119 신고를 교육한다.';why='초기 증상을 알고 빠르게 대처하면 심각한 반응으로의 진행을 막을 수 있다.'})
}
$script:Templates['저체온'] = @{
    en = 'Hypothermia'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '6. 체온조절 Thermoregulation'
    page = $null
    problem = '저체온'
    priority = 2
    reason = '중심체온 저하는 부정맥과 응고장애, 의식 저하를 일으켜 순환을 위협하므로 ABC 다음으로 우선 중재가 필요하다'
    evalData = '중심체온(매 30분~1시간), 오한·피부 색과 온도, 심박수와 리듬, 의식 수준, 보온 방법 설명 여부'
    keywords = '저체온|hypotherm|체온 ?3[0-5](\.[0-9])?|BT ?3[0-5](\.[0-9])?|오한|shivering|떨림|한랭 ?노출|cold exposure|동상|frostbite|피부가 ?차|냉감|청색증|cyanosis|익수|drowning'
    cause = '추운 환경 노출'
    long = '대상자는 퇴원 시까지 정상 체온(36.5~37.5℃)을 유지할 것이다.'
    short = @('대상자는 2시간 내 체온이 36℃ 이상으로 상승할 것이다.','대상자는 1일 내 저체온 예방 방법을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='복원 중에는 30분~1시간마다 중심체온(고막, 식도, 방광 등)을 측정한다.';why='재가온 속도와 효과를 확인하고 너무 빠른 체온 변화를 막기 위해 자주 측정해야 한다.'},
        @{plan='심박수와 리듬, 혈압, 호흡수, SpO2를 모니터링한다.';why='저체온은 서맥과 심실세동 등 부정맥을 일으키고, 재가온 중 혈관 확장으로 혈압이 떨어질 수 있다.'},
        @{plan='의식 수준, 오한, 피부 색과 온도, 말초 순환을 사정한다.';why='의식 저하와 오한 소실은 저체온이 심해졌다는 신호다.'})
    ther = @(
        @{plan='젖은 옷을 벗기고 따뜻한 담요로 감싸며 실내 온도를 높인다.';why='젖은 옷은 증발과 전도로 열을 계속 빼앗고, 보온은 추가 열 손실을 막는다.'},
        @{plan='처방에 따라 가온 담요(강제공기 가온장치)를 적용하고 피부 화상 여부를 확인한다.';why='능동적 외부 가온은 체온을 효과적으로 올리며, 말초 순환이 떨어진 피부는 화상에 취약하다.'},
        @{plan='처방에 따라 가온된 수액(약 38~42℃)과 가온·가습된 산소를 투여한다.';why='가온 수액과 산소는 몸 중심부부터 열을 공급하여 체온을 올린다.'},
        @{plan='중등도 이상 저체온 시 대상자를 부드럽게 움직이고 거친 자극을 피한다.';why='저체온 상태의 심장은 자극에 예민하여 거친 움직임이 심실세동을 일으킬 수 있다.'},
        @{plan='의식이 명료하면 따뜻한 음료를 제공한다.';why='따뜻한 음료는 열과 에너지를 공급하며, 알코올과 카페인은 열 손실과 이뇨를 늘리므로 피한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 추운 환경에서 여러 겹의 옷과 모자·장갑 착용 등 보온 방법을 교육한다.';why='겹쳐 입으면 공기층이 단열 효과를 내고 머리와 손발을 통한 열 손실을 줄인다.'},
        @{plan='저체온 초기 증상(떨림, 말이 어눌함, 판단력 저하)과 음주 후 추위 노출의 위험을 교육한다.';why='알코올은 혈관을 확장시켜 열 손실을 늘리고 추위를 느끼지 못하게 한다.'})
}
$script:Templates['수술 전후 저체온의 위험'] = @{
    en = 'Risk for perioperative hypothermia'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '6. 체온조절 Thermoregulation'
    page = $null
    problem = '수술 중 저체온 위험'
    priority = 5
    reason = '아직 발생하지 않은 위험 진단이지만, 수술 중 저체온은 출혈·감염·심장 합병증을 늘리므로 안전 요구로서 예방이 필요하다'
    evalData = '수술 전·중·후 체온(36℃ 이상 유지 여부), 오한, 피부 온도, 가온 장치 적용 여부'
    keywords = '수술 전|수술 중|수술 후|pre ?op|intra ?op|post ?op|perioperative|전신 ?마취|general anesthesia|척추 ?마취|spinal anesthesia|회복실|PACU|수술실|개복|laparotomy|장시간 수술'
    cause = '마취로 인한 체온 조절 기능 저하와 수술실의 차가운 환경'
    long = '대상자는 수술 전후 기간 동안 체온을 36℃ 이상으로 유지할 것이다.'
    short = @('대상자는 회복실 도착 시 체온이 36℃ 이상일 것이다.','대상자는 수술 후 2시간 내 오한 없이 편안함을 표현할 것이다.')
    diag = @(
        @{plan='수술 전, 수술 중 15~30분마다, 회복실 도착 시와 이후 정기적으로 체온을 측정한다.';why='마취 유도 후 첫 1시간에 열 재분포로 체온이 급격히 떨어지므로 지속적인 확인이 필요하다.'},
        @{plan='위험 요인(노인, 저체중, 장시간 수술, 개복·개흉 수술, 대량 수액·수혈)을 확인한다.';why='이러한 요인은 열 손실을 늘리고 열 생산을 줄여 저체온 위험을 높인다.'},
        @{plan='오한, 피부 색과 온도, 심박수와 리듬을 관찰한다.';why='오한은 산소 소모량을 크게 늘리고 저체온은 부정맥을 일으킬 수 있다.'})
    ther = @(
        @{plan='수술 전 대기 중부터 강제공기 가온장치나 따뜻한 담요로 미리 보온한다.';why='수술 전 가온은 마취 후 열 재분포로 인한 체온 저하를 줄인다.'},
        @{plan='수술실 온도를 적정하게 유지하고 수술 부위 외의 신체를 덮는다.';why='노출된 피부를 통한 복사·대류성 열 손실을 줄인다.'},
        @{plan='처방에 따라 가온된 수액과 혈액, 세척액을 사용한다.';why='차가운 수액과 세척액을 많이 사용하면 체온이 크게 떨어진다.'},
        @{plan='회복실에서 체온이 36℃ 미만이면 능동적 가온을 계속하고 오한 시 처방에 따라 약물을 투여한다.';why='저체온과 오한을 빨리 교정해야 회복이 빠르고 합병증이 줄어든다.'})
    edu = @(
        @{plan='대상자에게 수술 전후 추위를 느끼거나 떨리면 바로 알리도록 교육한다.';why='대상자의 호소는 저체온을 조기에 발견하는 단서가 된다.'},
        @{plan='대상자와 보호자에게 수술 중 체온 유지가 상처 감염과 출혈 예방에 중요한 이유를 설명한다.';why='이유를 이해하면 보온 중재에 적극적으로 협조하게 된다.'})
}
$script:Templates['신생아 저체온'] = @{
    en = 'Neonatal hypothermia'
    domain = '11. 안전/보호 Safety/Protection'
    cls = '6. 체온조절 Thermoregulation'
    page = $null
    problem = '신생아 저체온'
    priority = 2
    reason = '신생아 저체온은 저혈당, 대사성 산증, 호흡곤란을 일으켜 순환과 호흡을 위협하므로 우선 중재가 필요하다'
    evalData = '액와 체온(36.5~37.5℃), 피부 색과 사지 온도, 혈당, 호흡수와 활동성, 수유 상태'
    keywords = '신생아|newborn|neonat|미숙아|조산아|preterm|저체중 ?출생|LBW|체온 ?3[0-6](\.[0-9])?|저체온|hypotherm|인큐베이터|incubator|보육기|방사 ?온열기|radiant warmer|캥거루 ?케어|kangaroo|피부 ?대 ?피부|skin-to-skin|말단 ?청색증|acrocyanosis'
    cause = '미숙한 체온 조절 기능과 넓은 체표면적'
    long = '신생아는 퇴원 시까지 액와 체온 36.5~37.5℃를 유지할 것이다.'
    short = @('신생아는 1시간 내 액와 체온이 36.5℃ 이상으로 상승할 것이다.','보호자는 퇴원 전까지 신생아 보온 방법을 두 가지 이상 말로 표현하고 수행할 것이다.')
    diag = @(
        @{plan='액와 체온을 30분~1시간마다(안정 후 3~4시간마다) 측정한다.';why='신생아는 체온이 빠르게 변하므로 자주 측정하여 회복 정도를 확인해야 한다.'},
        @{plan='피부 색(창백, 얼룩덜룩함), 사지 온도, 활동성, 수유 상태를 관찰한다.';why='저체온 신생아는 기면, 빨기 약화, 차고 얼룩덜룩한 피부를 보인다.'},
        @{plan='처방에 따라 혈당을 측정하고 호흡수와 무호흡, SpO2를 관찰한다.';why='저체온 시 갈색지방 대사로 포도당과 산소 소모가 늘어 저혈당과 호흡곤란이 생긴다.'})
    ther = @(
        @{plan='출생 직후 몸을 따뜻한 수건으로 즉시 말리고 젖은 수건을 바꾸며 모자를 씌운다.';why='젖은 피부의 증발과 큰 머리를 통한 열 손실이 신생아 열 손실의 큰 부분을 차지한다.'},
        @{plan='금기가 아닐 시 엄마와 피부 대 피부 접촉(캥거루 케어)을 하고 담요로 덮는다.';why='엄마의 체온이 직접 전달되어 효과적으로 체온을 유지하고 모유 수유도 촉진한다.'},
        @{plan='필요시 방사 온열기나 인큐베이터를 사용하고 피부 온도 센서로 체온을 조절한다.';why='온도가 조절되는 환경은 신생아의 에너지 소모를 최소화하면서 체온을 올린다.'},
        @{plan='처치 시 따뜻한 손과 데운 기구를 사용하고 창문, 에어컨 바람을 피한다.';why='차가운 물체와 공기 흐름은 전도와 대류로 열을 빼앗는다.'},
        @{plan='조기 수유를 격려하고 처방에 따라 저혈당 시 포도당을 공급한다.';why='충분한 열량은 열 생산에 필요하며 저혈당을 예방한다.'})
    edu = @(
        @{plan='보호자에게 체온 측정 방법과 정상 범위(액와 36.5~37.5℃)를 교육한다.';why='보호자가 가정에서 체온 이상을 조기에 발견할 수 있다.'},
        @{plan='보호자에게 보온 방법(모자, 적정 실내 온도, 목욕 후 빨리 말리기, 옷을 한 겹 더 입히기)과 과열도 피해야 함을 교육한다.';why='적절한 보온은 저체온을 예방하고, 과열은 영아 돌연사의 위험 요인이므로 함께 주의해야 한다.'})
}
$script:Templates['만성 통증'] = @{
    en = 'Chronic pain'
    domain = '12. 안위 Comfort'
    cls = '1. 신체적 안위 Physical comfort'
    page = $null
    problem = '만성 통증'
    priority = 3
    reason = '3개월 이상 지속되는 통증이 수면, 활동, 정서 등 일상생활 전반을 방해하므로 안위 요구로서 우선 중재가 필요하다'
    evalData = '통증 점수(NRS)와 양상 변화, 일상활동 수행 정도, 수면 상태, 비약물적 통증 조절 방법 사용 여부, 기분 상태'
    keywords = '만성 ?통증|chronic pain|3개월 ?이상|6개월 ?이상|수년간|몇 ?년째|섬유근육통|fibromyalgia|복합부위통증|CRPS|대상포진 ?후 ?신경통|postherpetic|만성 ?요통|chronic (low )?back|류마티스|rheumatoid|골관절염|osteoarthritis|당뇨병성 ?신경병증|diabetic neuropathy|암성 ?통증|cancer pain'
    cause = '만성 근골격계 질환'
    long = '대상자는 퇴원 시 통증을 스스로 조절하며 일상생활을 수행할 것이다.'
    short = @('대상자는 1주일 내 통증 점수가 입원 시보다 2점 이상 감소했다고 표현할 것이다.','대상자는 1주일 내 비약물적 통증 조절 방법을 두 가지 이상 수행할 것이다.')
    diag = @(
        @{plan='매 듀티마다 통증의 부위, 강도(NRS), 양상, 지속시간, 악화·완화 요인을 사정한다.';why='만성 통증은 양상이 다양하게 변하므로 반복 사정으로 중재 효과를 평가해야 한다.'},
        @{plan='통증이 수면, 식사, 활동, 기분, 대인관계에 미치는 영향을 사정한다.';why='만성 통증은 통증 자체보다 삶의 질과 기능 저하가 더 큰 문제가 되는 경우가 많다.'},
        @{plan='우울, 불안, 피로 정도와 현재 사용 중인 진통제와 대처 방법을 확인한다.';why='우울과 불안은 통증 지각을 높이고, 기존 대처 방법을 알면 효과적인 방법을 강화할 수 있다.'})
    ther = @(
        @{plan='처방에 따라 진통제를 정해진 시간에 규칙적으로 투여하고 효과와 부작용(변비, 졸음, 위장 장애)을 확인한다.';why='만성 통증은 규칙적인 투여로 혈중 농도를 일정하게 유지해야 통증 악화를 예방할 수 있다.'},
        @{plan='금기가 아닐 시 온요법, 마사지, 이완요법, 음악요법 등 비약물적 방법을 적용한다.';why='비약물적 방법은 근육 긴장을 풀고 통증에 대한 주의를 분산시켜 약물 효과를 보완한다.'},
        @{plan='대상자와 함께 휴식과 활동을 조절한 일과 계획을 세운다.';why='무리한 활동과 지나친 휴식 모두 통증과 기능 저하를 악화시키므로 균형 있는 활동 조절이 필요하다.'},
        @{plan='통증 경험을 인정하고 감정을 표현하도록 격려한다.';why='통증을 믿어주는 태도는 신뢰를 높이고 우울과 고립감을 줄인다.'},
        @{plan='필요시 통증 클리닉, 물리치료, 정신건강 전문가와 협력한다.';why='만성 통증은 다학제적 접근이 가장 효과적이다.'})
    edu = @(
        @{plan='대상자에게 통증 일기 쓰기와 통증 악화 요인 피하는 방법을 교육한다.';why='통증 양상을 기록하면 유발 요인을 파악하고 스스로 조절하는 능력이 높아진다.'},
        @{plan='대상자와 보호자에게 처방된 진통제의 올바른 복용법과 임의로 양을 늘리거나 중단하지 않도록 교육한다.';why='올바른 복용은 통증 조절 효과를 높이고 부작용과 의존 위험을 줄인다.'})
}
$script:Templates['오심'] = @{
    en = 'Nausea'
    domain = '12. 안위 Comfort'
    cls = '1. 신체적 안위 Physical comfort'
    page = $null
    problem = '오심'
    priority = 3
    reason = '오심은 현재 대상자가 호소하는 불편감으로 식사와 수분 섭취를 방해하여 탈수와 영양 결핍으로 이어질 수 있다'
    evalData = '오심 정도(0~10점)와 빈도, 구토 횟수와 양, 식이·수분 섭취량, 섭취량·배설량, 항구토제 투여 후 반응'
    keywords = '오심|메스꺼|울렁|속이 ?안 ?좋|구역|nausea|구토|vomit|헛구역질|retching|입덧|morning sickness|항암|chemotherapy|CINV|PONV|멀미|motion sickness|온단세트론|ondansetron|조프란|맥페란|metoclopramide'
    cause = '항암화학요법의 부작용'
    long = '대상자는 퇴원 시 오심 없이 식사할 것이다.'
    short = @('대상자는 2일 내 오심 정도가 3점 이하로 감소했다고 표현할 것이다.','대상자는 3일 내 하루 수분 1,500mL 이상과 처방된 식이의 절반 이상을 섭취할 것이다.')
    diag = @(
        @{plan='매 듀티마다 오심의 정도(0~10점), 빈도, 지속시간, 유발 요인(냄새, 움직임, 식사, 약물)을 사정한다.';why='유발 요인과 정도를 알아야 맞춤형 중재를 하고 효과를 평가할 수 있다.'},
        @{plan='구토 횟수, 양, 색, 성상과 섭취량·배설량을 확인한다.';why='잦은 구토는 수분과 전해질을 잃게 하므로 정확한 측정이 필요하다.'},
        @{plan='탈수 징후(구강 점막 건조, 피부 긴장도 저하, 소변량 감소)와 전해질(Na, K) 결과를 확인한다.';why='오심과 구토가 지속되면 탈수와 저칼륨혈증 같은 전해질 불균형이 생길 수 있다.'})
    ther = @(
        @{plan='처방에 따라 항구토제를 투여하고(항암 시 투여 전 예방적으로) 30분~1시간 후 효과와 부작용을 확인한다.';why='항구토제는 구토 중추로 가는 자극을 차단하며, 예방적으로 투여할 때 효과가 더 크다.'},
        @{plan='냄새가 강한 음식, 향수 등을 피하고 환기가 잘 되는 환경을 제공한다.';why='강한 냄새는 화학수용체를 자극하여 오심을 유발한다.'},
        @{plan='소량씩 자주, 차갑거나 상온의 담백하고 마른 음식(크래커, 토스트)을 제공한다.';why='위가 과도하게 팽창하는 것을 막고 자극이 적은 음식은 오심을 덜 유발한다.'},
        @{plan='식사 후 바로 눕지 않고 상체를 높인 자세를 유지하게 한다.';why='상체를 높이면 위 내용물의 역류를 줄여 오심을 완화한다.'},
        @{plan='구토 후 구강 간호를 제공하고 심호흡과 이완요법을 격려한다.';why='입 안의 불쾌한 맛과 냄새를 없애면 오심이 줄고, 이완은 자율신경 반응을 진정시킨다.'})
    edu = @(
        @{plan='대상자에게 오심을 줄이는 식사 방법(소량씩 자주, 천천히 먹기, 식사 중 물 적게 마시기)을 교육한다.';why='식사 방법을 조절하면 위 자극을 줄여 오심을 스스로 관리할 수 있다.'},
        @{plan='대상자와 보호자에게 구토가 계속되거나 소변량 감소, 어지러움 등 탈수 증상 시 알리도록 교육한다.';why='탈수는 빠르게 진행할 수 있어 조기 수액 공급이 필요하다.'})
}
$script:Templates['분만 통증'] = @{
    en = 'Labor pain'
    domain = '12. 안위 Comfort'
    cls = '1. 신체적 안위 Physical comfort'
    page = $null
    problem = '분만 통증'
    priority = 3
    reason = '분만 과정의 자궁수축으로 인한 현재의 극심한 통증이 산모의 협조와 진통 진행에 영향을 주므로 우선 중재가 필요하다'
    evalData = '통증 점수(NRS)와 자궁수축 양상(빈도, 지속시간, 강도), 호흡법 사용 여부, 경막외 마취 후 반응, 태아심음, 산모의 대처 행동'
    keywords = '분만|labor|진통|자궁 ?수축|uterine contraction|산통|경막외|epidural|무통 ?분만|자궁경부 ?개대|cervical dilat|태아심음|FHR|NST|라마즈|lamaze|양막 ?파열|분만 ?1기|분만 ?2기|옥시토신|oxytocin|임신 ?[34][0-9] ?주'
    cause = '자궁수축과 자궁경부 개대'
    long = '대상자는 분만 종료 시까지 통증을 견딜 수 있는 수준으로 조절하며 분만 과정에 참여할 것이다.'
    short = @('대상자는 1시간 내 자궁수축 시 배운 호흡법을 사용할 것이다.','대상자는 진통제 또는 경막외 마취 적용 후 30분 내 통증이 견딜 만하다고 표현할 것이다.')
    diag = @(
        @{plan='자궁수축의 빈도, 지속시간, 강도와 통증 점수(NRS), 통증 부위를 정기적으로 사정한다.';why='자궁수축과 통증 양상은 분만 진행 정도를 반영하며 중재 효과를 평가하는 지표다.'},
        @{plan='분만 진행(자궁경부 개대와 소실, 선진부 하강)과 태아심음을 확인한다.';why='진행 단계에 따라 적절한 통증 조절 방법이 다르고, 진통제는 태아에게 영향을 줄 수 있어 태아 상태 확인이 필요하다.'},
        @{plan='산모의 불안 정도, 대처 행동, 분만 준비 교육 여부와 원하는 통증 조절 방법을 확인한다.';why='불안은 통증을 증가시키며, 산모의 선호를 반영하면 만족도와 협조가 높아진다.'})
    ther = @(
        @{plan='자궁수축 시 호흡법(이완 호흡, 느린 흉식 호흡)을 함께 하도록 돕는다.';why='리듬 있는 호흡은 주의를 분산시키고 이완을 촉진하여 통증 지각을 줄인다.'},
        @{plan='금기가 아닐 시 자유로운 체위(측위, 앉기, 걷기)를 취하게 하고 천골 마사지를 제공한다.';why='체위 변경은 태아 하강을 돕고 천골 압박은 요통을 완화한다.'},
        @{plan='처방에 따라 진통제나 경막외 마취를 적용하고 산모의 혈압, 태아심음, 호흡 상태를 확인한다.';why='경막외 마취는 저혈압을, 마약성 진통제는 산모와 신생아의 호흡 억제를 일으킬 수 있다.'},
        @{plan='조용하고 편안한 환경을 제공하고 보호자가 곁에 있도록 한다.';why='정서적 지지와 안정된 환경은 불안을 줄여 통증을 덜 느끼게 한다.'},
        @{plan='수축 사이에 휴식을 격려하고 방광을 2시간마다 비우게 한다.';why='휴식은 에너지를 보존하고, 꽉 찬 방광은 불편감을 늘리고 태아 하강을 방해한다.'})
    edu = @(
        @{plan='대상자와 보호자에게 분만 단계별 진행 과정과 통증 양상을 설명한다.';why='무엇이 일어날지 알면 두려움과 불안이 줄어 통증 대처 능력이 높아진다.'},
        @{plan='보호자에게 마사지, 호흡 함께 하기 등 산모를 돕는 방법을 교육한다.';why='보호자의 적극적인 지지는 산모의 통증 대처와 분만 만족도를 높인다.'})
}
$script:Templates['안위 장애'] = @{
    en = 'Impaired comfort'
    domain = '12. 안위 Comfort'
    cls = '1. 신체적 안위 Physical comfort'
    page = $null
    problem = '안위 장애'
    priority = 3
    reason = '대상자가 현재 신체적·정신적 불편감을 호소하고 있어 휴식과 수면 등 다른 기본 욕구 충족을 방해하므로 우선 중재가 필요하다'
    evalData = '불편감 호소 정도와 양상, 휴식·수면 상태, 안절부절못하는 행동, 이완 방법 사용 여부'
    keywords = '불편감|불편하|안위|discomfort|impaired comfort|가려움|소양증|pruritus|안절부절|restless|잠을 ?못|더워|추워|신경 ?쓰여|소음|완화 ?의료|palliative|호스피스|hospice'
    cause = '질병 관련 증상'
    long = '대상자는 퇴원 시 편안함을 말로 표현할 것이다.'
    short = @('대상자는 2일 내 불편감 정도가 감소했다고 표현할 것이다.','대상자는 3일 내 편안함을 높이는 방법을 두 가지 이상 수행할 것이다.')
    diag = @(
        @{plan='매 듀티마다 불편감의 원인, 양상, 정도와 대상자가 느끼는 편안함 정도를 사정한다.';why='불편감의 원인과 정도를 알아야 맞춤형 중재를 계획하고 효과를 평가할 수 있다.'},
        @{plan='안절부절못함, 얼굴 찡그림, 자주 자세를 바꾸는 행동 등 비언어적 표현을 관찰한다.';why='비언어적 행동은 말로 표현하지 못한 불편감을 파악하는 단서가 된다.'},
        @{plan='수면 상태와 환경 요인(온도, 소음, 조명, 침구)을 확인한다.';why='환경적 요인은 신체적 불편감을 악화시키고 휴식을 방해한다.'})
    ther = @(
        @{plan='불편감의 원인이 되는 증상(통증, 가려움, 오심 등)을 처방에 따라 조절한다.';why='원인 증상을 조절하는 것이 불편감을 줄이는 가장 직접적인 방법이다.'},
        @{plan='실내 온도, 조명, 소음을 조절하고 침구를 깨끗하고 주름 없이 유지한다.';why='쾌적한 환경은 신체적 불편감을 줄이고 휴식을 돕는다.'},
        @{plan='금기가 아닐 시 편안한 체위를 취하게 하고 베개로 지지한다.';why='편안한 체위는 근육 긴장과 압박을 줄여 안위를 높인다.'},
        @{plan='마사지, 음악, 심호흡 등 이완요법을 제공한다.';why='이완요법은 교감신경 활동을 줄여 몸과 마음을 편안하게 한다.'},
        @{plan='대상자의 이야기를 경청하고 정서적 지지를 제공한다.';why='정서적 지지는 불안을 줄여 불편감을 덜 느끼게 한다.'})
    edu = @(
        @{plan='대상자에게 스스로 할 수 있는 이완 방법(심호흡, 점진적 근육 이완)을 교육한다.';why='스스로 이완 방법을 사용하면 불편감에 대한 조절감이 높아진다.'},
        @{plan='대상자와 보호자에게 불편감이 심해지거나 새로운 증상이 생기면 알리도록 교육한다.';why='새로운 증상은 질병 변화의 신호일 수 있어 조기 확인이 필요하다.'})
}
$script:Templates['사회적 고립'] = @{
    en = 'Social isolation'
    domain = '12. 안위 Comfort'
    cls = '3. 사회적 안위 Social comfort'
    page = $null
    problem = '사회적 고립'
    priority = 6
    reason = '생리적·안전 요구는 충족되었으나 타인과의 관계가 부족하여 사랑과 소속의 욕구가 위협받고 있다'
    evalData = '타인과 교류하는 횟수와 시간, 외로움 표현 여부, 활동 참여 정도, 지지 체계 이용 여부'
    keywords = '고립|isolat|외로|lonel|혼자 ?(살|지내)|독거|living alone|찾아오는 ?사람이 ?없|면회 ?없|대인 ?기피|위축|withdrawn|은둔|사회적 ?지지 ?부족|social support'
    cause = '사회적 지지 체계의 부족'
    long = '대상자는 퇴원 시 지속적으로 교류할 수 있는 사람이나 모임을 한 곳 이상 갖게 될 것이다.'
    short = @('대상자는 1주일 내 하루 1회 이상 다른 사람과 대화하거나 활동에 참여할 것이다.','대상자는 1주일 내 이용할 수 있는 지지 자원(가족, 친구, 지역사회 기관)을 두 가지 이상 말로 표현할 것이다.')
    diag = @(
        @{plan='대상자의 가족 관계, 친구, 이웃 등 사회적 관계망과 교류 빈도를 사정한다.';why='현재 지지 체계를 파악해야 활용할 수 있는 관계를 찾고 강화할 수 있다.'},
        @{plan='고립을 일으키는 요인(신체 기능 저하, 감각 장애, 외모 변화, 우울, 경제적 문제)을 확인한다.';why='고립의 원인을 알아야 이를 해결하는 맞춤형 중재를 할 수 있다.'},
        @{plan='외로움, 소외감, 우울 정도를 대상자의 말과 행동으로 관찰한다.';why='장기간의 고립은 우울과 건강 악화로 이어지므로 정서 상태를 함께 확인해야 한다.'})
    ther = @(
        @{plan='정기적으로 시간을 정해 대상자와 대화하며 신뢰 관계를 형성한다.';why='일관된 만남은 대상자에게 관심받는 경험을 주어 대인관계의 시작이 된다.'},
        @{plan='대상자가 관심 있는 활동이나 소그룹 활동에 참여하도록 격려한다.';why='공통 관심사를 가진 사람과의 활동은 자연스러운 교류를 촉진한다.'},
        @{plan='가족과 친구의 방문이나 전화·영상통화를 격려한다.';why='기존의 의미 있는 관계를 유지하면 소속감이 높아진다.'},
        @{plan='보청기, 안경 등 의사소통을 돕는 보조기구를 사용하게 한다.';why='감각 장애를 보완하면 의사소통이 쉬워져 위축이 줄어든다.'},
        @{plan='필요시 사회복지사와 협력하여 지역사회 자원(복지관, 자조모임, 방문 서비스)을 연계한다.';why='퇴원 후에도 지속적인 교류를 유지할 수 있는 기반을 마련한다.'})
    edu = @(
        @{plan='대상자에게 이용할 수 있는 지역사회 프로그램과 연락 방법을 교육한다.';why='자원을 알고 있으면 대상자가 스스로 교류를 시작할 수 있다.'},
        @{plan='가족에게 대상자와 규칙적으로 연락하고 함께하는 시간의 중요성을 교육한다.';why='가족의 정기적인 관심은 대상자의 고립감과 우울을 줄인다.'})
}
$script:Templates['아동 발달 지연의 위험'] = @{
    en = 'Risk for delayed child development'
    domain = '13. 성장/발달 Growth/Development'
