    evalData = '연령별 발달 선별검사(K-DST) 결과, 대근육·소근육·언어·사회성 발달 이정표 도달 여부, 보호자의 발달 자극 활동 수행 여부'
    keywords = '발달 ?지연|developmental delay|발달 ?이정표|milestone|K-?DST|영유아 ?건강검진|덴버|Denver|미숙아|조산아|preterm|저체중 ?출생|LBW|장기 ?입원|선천성|congenital|다운 ?증후군|Down syndrome|뇌성마비|cerebral palsy|말이 ?늦|걷지 ?못'
    cause = '조산과 장기 입원'
    long = '아동은 퇴원 시까지 연령(교정연령)에 맞는 발달 이정표에 도달하고 있을 것이다.'
    short = @('보호자는 1주일 내 아동의 연령에 맞는 발달 자극 놀이를 두 가지 이상 수행할 것이다.','보호자는 3일 내 정기적인 영유아 건강검진과 발달 선별검사의 필요성을 말로 표현할 것이다.')
    diag = @(
        @{plan='연령에 맞는 발달 선별검사(K-DST 등)로 대근육, 소근육, 언어, 인지, 사회성 발달을 사정한다.';why='표준화된 도구를 사용하면 발달 지연을 객관적이고 조기에 발견할 수 있다.'},
        @{plan='발달 위험 요인(조산, 저체중 출생, 만성 질환, 장기 입원, 영양 상태, 양육 환경)을 확인한다.';why='위험 요인이 많을수록 발달 지연 가능성이 높아 더 자주 관찰해야 한다.'},
        @{plan='키, 몸무게, 머리둘레를 측정하여 성장 곡선에 기록한다.';why='신체 성장은 영양과 건강 상태를 반영하며 발달과 밀접하게 관련된다.'})
    ther = @(
        @{plan='미숙아는 교정연령을 기준으로 발달을 평가하고 계획한다.';why='미숙아를 출생 연령으로 평가하면 실제보다 지연된 것으로 잘못 판단할 수 있다.'},
        @{plan='입원 중에도 연령에 맞는 장난감과 놀이 활동을 제공한다.';why='놀이는 아동의 운동, 인지, 사회성 발달을 자극하는 가장 자연스러운 방법이다.'},
        @{plan='보호자가 아동과 함께 지내며 돌봄에 참여하도록 격려한다.';why='보호자와의 안정된 애착은 정서와 사회성 발달의 기초가 된다.'},
        @{plan='충분한 영양 섭취와 규칙적인 수면을 돕는다.';why='적절한 영양과 수면은 뇌 성장과 발달에 필수적이다.'},
        @{plan='필요시 재활의학과, 언어치료, 작업치료 등 조기 중재 서비스와 연계한다.';why='발달 지연은 일찍 중재할수록 효과가 크다.'})
    edu = @(
        @{plan='보호자에게 연령별 발달 이정표와 발달을 돕는 놀이 방법(말 걸기, 책 읽어주기, 엎드려 놀기)을 교육한다.';why='보호자가 일상에서 발달을 자극하면 발달 지연을 예방하고 이상을 빨리 알아챌 수 있다.'},
        @{plan='보호자에게 영유아 건강검진과 예방접종 일정을 지키도록 교육한다.';why='정기 검진에서 발달 선별검사를 받으면 발달 문제를 조기에 발견할 수 있다.'})
}
